/// `GET /agents.txt` — robots.txt-style plaintext discovery card.
/// One line per canonical agent-facing surface. Directory crawlers
/// (AgenstryBot, MCP-Catalog-Bot) model discovery after `/robots.txt`
/// and find emem here in a single fetch. All URLs are agent-readable
/// and self-describing; an LLM that lands here knows where to go next
/// without rendering HTML.
async fn serve_agents_txt() -> Response {
    let origin = public_origin().unwrap_or_else(|| "https://emem.dev".into());
    let body = format!(
        "# {origin} — Earth memory protocol for AI agents.\n\
         # Plaintext discovery card. One line per canonical agent surface.\n\
         # Source: github.com/Vortx-AI/emem (Apache-2.0).\n\
         \n\
         Agent-Card: {origin}/.well-known/agent-card.json\n\
         MCP: {origin}/mcp\n\
         MCP-Card: {origin}/.well-known/mcp/server-card.json\n\
         OpenAPI: {origin}/openapi.json\n\
         LLMs-Txt: {origin}/llms.txt\n\
         LLMs-Full-Txt: {origin}/llms-full.txt\n\
         Agents-Md: {origin}/agents.md\n\
         Spec: {origin}/spec.md\n\
         Whitepaper: {origin}/whitepaper.md\n\
         Discover: {origin}/v1/agent_card\n\
         Tools: {origin}/v1/tools\n\
         Algorithms: {origin}/v1/algorithms\n\
         Manifests: {origin}/v1/manifests\n\
         Stream: {origin}/v1/stream\n\
         Coverage: {origin}/v1/coverage_map.svg\n\
         Verify: {origin}/verify\n\
         Operator-Attestation: {origin}/.well-known/emem.json\n\
         Repository: https://github.com/Vortx-AI/emem\n\
         License: Apache-2.0\n\
         Contact: avijeet@vortx.ai\n\
         Auth: none (reads); ed25519-signed responses; offline-verifiable\n\
         Allow: *\n\
         Disallow:\n"
    );
    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "text/plain; charset=utf-8")
        .header(CACHE_CONTROL, "public, max-age=86400")
        .body(axum::body::Body::from(body))
        .unwrap_or_else(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response())
}

/// `GET /v1/deprecations` — empty list with the deprecation policy.
/// ClaudeBot polls this; returning a typed stable list (instead of
/// 404) tells a crawler the surface exists and is intentionally empty.
async fn serve_deprecations() -> Json<JsonValue> {
    Json(json!({
        "schema":     "emem.deprecations.v1",
        "deprecated": [],
        "policy":     "Pre-1.0. A breaking change carries a deprecation entry here one minor release before removal. Entries name the path, the replacement, and the earliest version that removes the old surface.",
        "spec":       "https://emem.dev/spec.md",
        "served_at":  iso8601_utc(now_unix_s() as u64),
    }))
}

/// `GET /v1/models` and `GET|POST /v1/chat/completions` — agents
/// probing for the OpenAI-API shape land here. Return a typed 404
/// pointing them at `/v1/ask` (the closest emem equivalent: a
/// place-anchored Q&A with a signed receipt) and `/v1/algorithms`
/// (the equivalent of a "model catalog" on this surface).
async fn not_an_llm_provider() -> Response {
    let origin = public_origin().unwrap_or_else(|| "https://emem.dev".into());
    let body = json!({
        "schema":  "emem.error.v1",
        "code":    "not_found",
        "message": "emem is not an LLM provider; there is no chat/completions or model-list endpoint. The closest emem equivalents are POST /v1/ask (a place-anchored question with a signed answer) and GET /v1/algorithms (the catalog of named composition recipes).",
        "details": {
            "ask":        format!("POST {origin}/v1/ask   body: {{q, place|cell|lat+lng}}"),
            "algorithms": format!("GET  {origin}/v1/algorithms?summary=true"),
            "tools":      format!("GET  {origin}/v1/tools"),
            "agent_card": format!("GET  {origin}/.well-known/agent-card.json"),
            "spec":       format!("GET  {origin}/spec.md"),
        }
    });
    (StatusCode::NOT_FOUND, Json(body)).into_response()
}

/// `GET /v1/algorithm_cids` — list-form alias for the algorithms hash
/// surfaced under `/v1/manifests`. Some agents reach here first when
/// asked to "pin the algorithm registry"; mirror the relevant fields
/// so they don't bounce through two URLs.
async fn serve_algorithm_cids() -> Json<JsonValue> {
    let algos = &emem_core::algorithms::DEFAULT;
    Json(json!({
        "schema":         "emem.algorithm_cids.v1",
        "algorithms_cid": ALGORITHMS_CID.clone(),
        "n_algorithms":   algos.algorithms.len(),
        "manifests":      "/v1/manifests",
        "algorithms":     "/v1/algorithms?summary=true",
        "per_algorithm":  "/v1/algorithms/<key>",
        "served_at":      iso8601_utc(now_unix_s() as u64),
    }))
}

// ── Introspection routes ─────────────────────────────────────────────────

async fn health(State(s): State<AppState>) -> Json<JsonValue> {
    // Cheap runtime stats — agents check this before relying on cache
    // hit rates or recently-attested facts. Distinct bands / total
    // facts come from one storage.scan_index pass capped at the same
    // limit coverage_matrix uses, so the call stays bounded even on a
    // large corpus.
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let uptime_s = (now - s.started_at_unix_s).max(0);
    let limit: usize = 32_768;
    let mut total_facts: u64 = 0;
    let mut distinct_cells = std::collections::HashSet::<String>::new();
    let mut distinct_bands = std::collections::HashSet::<String>::new();
    if let Ok(rows) = s.storage.iter_index(Some(limit)).await {
        for (k, _) in &rows {
            total_facts += 1;
            distinct_cells.insert(k.cell.clone());
            distinct_bands.insert(k.band.clone());
        }
    }
    Json(json!({
        "ok": true,
        "name": "emem",
        "version": env!("CARGO_PKG_VERSION"),
        "responder_pubkey_b32": data_encoding::BASE32_NOPAD
            .encode(&s.identity.pubkey.0)
            .to_lowercase(),
        "responder_key_epoch": s.identity.epoch.0,
        "registry_cid": s.manifests.registry_cid.as_str(),
        "schema_cid": s.manifests.schema_cid.as_str(),
        "bands_cid": &s.manifests.bands_cid,
        "sources_cid": &s.manifests.sources_cid,
        "algorithms_cid": ALGORITHMS_CID.clone(),
        "started_at_unix_s": s.started_at_unix_s,
        "now_unix_s": now,
        "uptime_seconds": uptime_s,
        "corpus": {
            "facts_scanned": total_facts,
            "distinct_cells": distinct_cells.len(),
            "distinct_bands": distinct_bands.len(),
            "scan_index_limit": limit,
            "note": "facts_scanned reflects the index scan cap; corpora above the cap are paginated via /v1/coverage_matrix",
        },
    }))
}

async fn well_known(State(s): State<AppState>) -> Response {
    // Operator attestation: a signed liveness claim binding the running
    // binary's provenance (git commit, build timestamp, BLAKE3 hash of
    // the on-disk executable) plus the protocol state (version, key
    // epoch, manifest CIDs, served_at) under the responder's Ed25519
    // key. A verifier reconstructs `preimage` from the named fields and
    // checks the signature against `responder.pubkey_b32`. The chain is
    // operator-grade, not yet TEE-grade: a full Intel SGX / AMD SEV-SNP
    // attestation report (`tee_quote`) is deployment infrastructure and
    // ships as `null` from this responder until that infra lands;
    // whitepaper §20 holds the path.
    let version = env!("CARGO_PKG_VERSION");
    let git_commit = option_env!("EMEM_GIT_COMMIT").unwrap_or("unknown");
    let build_timestamp = option_env!("EMEM_BUILD_TIMESTAMP").unwrap_or("unknown");
    let binary_blake3 = binary_blake3_hex();
    let attested_at = {
        let secs = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);
        iso8601_utc(secs)
    };
    let pubkey_b32 = data_encoding::BASE32_NOPAD
        .encode(&s.identity.pubkey.0)
        .to_lowercase();
    let bands_cid: &str = s.manifests.bands_cid.as_ref();
    let registry_cid: &str = s.manifests.registry_cid.as_str();
    let attest_preimage = format!(
        "emem.operator_attestation|v{}|epoch{}|{}|git:{}|build:{}|binary:{}|bands:{}|registry:{}",
        version,
        s.identity.epoch.0,
        attested_at,
        git_commit,
        build_timestamp,
        binary_blake3,
        bands_cid,
        registry_cid,
    );
    let attest_sig = s
        .identity
        .signing
        .sign(attest_preimage.as_bytes())
        .to_bytes();
    let attest_sig_b32 = data_encoding::BASE32_NOPAD
        .encode(&attest_sig)
        .to_lowercase();

    // /.well-known/emem.json is the *only* response that intentionally
    // emits `x-emem-version` — the manifest's whole purpose is
    // responder disclosure (pubkey, manifest CIDs, version). The header
    // is now stripped from the global middleware (see headers fn) so
    // auditors stop dinging us for server-version disclosure on every
    // /v1/* response, but it stays here.
    let body = Json(json!({
        "protocol": "emem",
        "version": version,
        "manifests": {
            "bands_cid": &s.manifests.bands_cid,
            "sources_cid": &s.manifests.sources_cid,
            "registry_cid": s.manifests.registry_cid.as_str(),
            "schema_cid": s.manifests.schema_cid.as_str(),
            "algorithms_cid": ALGORITHMS_CID.clone(),
            "topics_cid": TOPICS_CID.clone(),
        },
        "responder": {
            "pubkey_b32": pubkey_b32,
            "key_epoch": s.identity.epoch.0,
            "signature_alg": "ed25519",
            "hash_alg": "blake3",
            "cid_encoding": "base32-nopad-lowercase",
        },
        "operator_attestation": {
            "version":         version,
            "key_epoch":       s.identity.epoch.0,
            "attested_at":     attested_at,
            "git_commit":      git_commit,
            "build_timestamp": build_timestamp,
            "binary_blake3":   binary_blake3,
            "tee_quote":       JsonValue::Null,
            "preimage":        attest_preimage,
            "signature_b32":   attest_sig_b32,
            "alg":             "ed25519",
            "_note":           "Verify by recomputing `preimage` from the named fields and checking ed25519 over it against `responder.pubkey_b32`. `binary_blake3` is the BLAKE3 hash of the running emem-server executable, computed once at startup by reading /proc/self/exe; together with `git_commit` and `build_timestamp` this binds the running code to a verifiable source tree. `tee_quote` is null on this responder (full Intel SGX / AMD SEV-SNP attestation report); operators who deploy under a TEE populate it from the platform's quoting service. Whitepaper §20 names the path.",
        },
        "tools_url": "/v1/tools",
        "openapi_url": "/openapi.json",
        "mcp_url": "/mcp",
        "agent_card_url": "/v1/agent_card",
        "quickstart_url": "/v1/quickstart",
        "stream_url": "/v1/stream",
        "corpus_state_stats_url": "/v1/corpus_state_stats",
        "benchmark_url": "/v1/benchmark",
        // POST-only endpoints. A bare GET on these returns 405 by design;
        // the `post:` prefix is a discoverability hint so a crawler doesn't
        // chase a GET that cannot answer.
        "state_url": "post:/v1/state",
        "state_multi_url": "post:/v1/state_multi",
        "state_diff_url": "post:/v1/state_diff",
        "memory_token_url": "post:/v1/memory_token",
        "memory_token_resolve_url": "post:/v1/memory_token/resolve",
        "benchmark_grade_url": "post:/v1/benchmark/grade",
        // Discovery hooks for connector-directory reviewers + offline
        // signature-verifying clients. The full text lives at /privacy,
        // /terms, /support; the canonical contact is the maintainer
        // email. `operator` carries the legal entity (Vortx AI Private
        // Limited, India); the flat `vendor`/`*_url` keys below are
        // kept as compatibility shims for tools that scrape the older
        // shape from earlier in the directory-prep work.
        "vendor": "Vortx-AI",
        "contact_email": "avijeet@vortx.ai",
        "privacy_url": "/privacy",
        "terms_url":   "/terms",
        "support_url": "/support",
        "operator": {
            "name":    "Vortx AI Private Limited",
            "country": "India",
            "url":     "https://vortx.ai",
            "contact": "avijeet@vortx.ai",
        },
        "policies": {
            "privacy_policy":   "/privacy",
            "terms_of_service": "/terms",
            "support":          "/support",
            "security":         "https://github.com/Vortx-AI/emem/blob/main/SECURITY.md",
        },
    }));
    let mut resp = body.into_response();
    resp.headers_mut()
        .insert("x-emem-version", version_header_value().clone());
    resp
}

async fn manifests(State(s): State<AppState>) -> Json<JsonValue> {
    let algorithms_cid = ALGORITHMS_CID.clone();
    let topics_cid = TOPICS_CID.clone();
    Json(json!({
        "bands_cid":     &s.manifests.bands_cid,
        // Spec name. The earlier `functions_cid` alias is kept below for
        // one release so existing clients don't break.
        "registry_cid":  s.manifests.registry_cid.as_str(),
        "functions_cid": s.manifests.registry_cid.as_str(),
        "sources_cid":   &s.manifests.sources_cid,
        "schema_cid":    s.manifests.schema_cid.as_str(),
        "algorithms_cid": algorithms_cid,
        "topics_cid":    topics_cid,
    }))
}

async fn bands(State(s): State<AppState>) -> Json<JsonValue> {
    // Hoist the registry's existing fields into the response root and
    // graft `bands_cid` next to them so an agent reading /v1/bands can
    // see the same content-address /v1/manifests publishes — without
    // having to call /v1/manifests separately.
    //
    // Per-band materializer status: declared bands without a wired
    // materializer used to be invisible from this endpoint. Inject
    // `materializer:{kind:"live"|"scalars_only"|"declared_no_connector",...}`
    // so the catalog tells the truth in one call. The kind is sourced
    // from the same `band_materializer_meta` dispatch that powers
    // /v1/recall, so it can't drift.
    let mut payload = serde_json::to_value(&*emem_core::bands::DEFAULT).unwrap_or(json!({}));
    if let Some(map) = payload.as_object_mut() {
        map.insert(
            "bands_cid".into(),
            JsonValue::String(s.manifests.bands_cid.clone()),
        );
        if let Some(arr) = map.get_mut("bands").and_then(|v| v.as_array_mut()) {
            for entry in arr.iter_mut() {
                let Some(obj) = entry.as_object_mut() else {
                    continue;
                };
                let key = obj
                    .get("key")
                    .and_then(|v| v.as_str())
                    .map(str::to_owned)
                    .unwrap_or_default();
                let status = if let Some(meta) = band_materializer_meta(&key) {
                    json!({
                        "kind": "live",
                        "tempo_seconds": meta.tempo.slot_seconds(),
                        "temporal_kind": meta.kind.as_str(),
                        "history_from_unix": meta.history_from_unix,
                        "history_to_unix": meta.history_to_unix,
                        "wire_path": meta.wire_path,
                    })
                } else if let Some(sample_scalar) = family_root_sample_scalar(&key) {
                    // Family-root key (e.g. `nightlights`, `terraclimate`,
                    // `sentinel2_raw`) has no direct materializer at the
                    // root, but a representative scalar child IS wired.
                    // Probe the dispatch with that child so we can quote
                    // its tempo / history / wire_path verbatim.
                    let child_meta = band_materializer_meta(sample_scalar);
                    json!({
                        "kind": "scalars_only",
                        "note": "Family-root cube key — recall on this exact key returns existing attestations only. Scalar children under this family (e.g. ".to_string() + sample_scalar + ") are auto-materialized; call /v1/materializers for the full per-scalar list.",
                        "sample_wired_child": sample_scalar,
                        "sample_child_wire_path": child_meta.as_ref().map(|m| m.wire_path),
                        "sample_child_temporal_kind": child_meta.as_ref().map(|m| m.kind.as_str()),
                    })
                } else {
                    json!({
                        "kind": "declared_no_connector",
                        "note": "Registered in the band catalog but no auto-materializer is wired at this responder, and no scalar child under this family is wired either. /v1/recall on this band will return only existing attestations (no upstream fetch). Genuine placeholders today: air_quality, _reserved_512, reserved.",
                    })
                };
                obj.insert("materializer".into(), status);
            }
        }
    }
    Json(payload)
}

/// Pick a representative scalar child for a cube family root, returning
/// the key the materializer dispatch knows about. Lets `/v1/bands`
/// distinguish "family root with wired children" from "true placeholder".
///
/// Sourced from `band_materializer_meta` arms — every entry below is
/// either an explicit case in that match or a prefix arm (`b.starts_with`).
/// If you wire a new family-root child, add the family here so the
/// catalog reflects it.
fn family_root_sample_scalar(family: &str) -> Option<&'static str> {
    Some(match family {
        // Prefix-matched arms in band_materializer_meta:
        "weather" => "weather.temperature_2m",
        "overture" => "overture.places_count",
        "power" => "power.solar_radiation_yearly",
        "cams" => "cams.air_quality_pm25",
        "era5" => "era5.t2m_yearly_mean",
        "marine" => "marine.wave_height",
        "terraclimate" => "terraclimate.tmax_jan_normal",
        "soilgrids" => "soilgrids.bulk_density_0_5cm",
        // s2_band_plan(*)-matched arm covers Sentinel-2 reflectance + indices:
        "sentinel2_raw" => "sentinel2.b04",
        "indices" => "indices.ndvi",
        // Specific scalar arms whose family root appears in the cube manifest:
        "dem" | "cop_dem" => "copdem30m.elevation_mean",
        "landcover" => "esa_worldcover.lc_2021",
        "surface_water" => "surface_water.recurrence",
        "nightlights" => "nightlights.dmsp_v4_2013",
        "forest_change" => "forest_change.tree_loss_y2024",
        "population" => "population", // root resolves; reachable via the live arm above
        // Native parametric arm (parses temporal_diff:<inner>:<window>):
        "temporal_diff" => "temporal_diff:geotessera:31536000",
        _ => return None,
    })
}

/// `GET /v1/materializers` — declare which bands this responder will
/// auto-materialize on a recall miss, what upstream source produces
/// the value, and what the resulting fact looks like (Primary or
/// Absence). Lets an agent discover, without trial-and-error, which
/// bands work cite-ably for any cell on Earth versus which require a
/// pre-existing attestation.
async fn materializers(
    State(s): State<AppState>,
    axum::extract::Query(q): axum::extract::Query<PageQuery>,
) -> Json<JsonValue> {
    let pubkey_b32 = data_encoding::BASE32_NOPAD
        .encode(&s.identity.pubkey.0)
        .to_lowercase();
    // Resolve the active Overture release tag once per call so the
    // three `overture.*` materializer entries below quote the currently
    // cached release in their `coverage` and `upstream_endpoint` fields
    // rather than an immutable literal baked in at compile time. On a
    // discovery failure the field reads `"unavailable"` (observably
    // distinct from a real tag) — no silent stale fallback.
    let overture_release = match emem_fetch::overture::OvertureClient::shared()
        .release()
        .await
    {
        Ok(r) => r,
        Err(e) => {
            tracing::warn!(
                target: "emem_api_rest::materializers",
                "could not resolve Overture release for /v1/materializers: {e}"
            );
            "unavailable".to_string()
        }
    };
    let overture_buildings_endpoint = format!(
        "s3://overturemaps-us-west-2/release/{overture_release}/theme=buildings/type=building/"
    );
    let overture_places_endpoint =
        format!("s3://overturemaps-us-west-2/release/{overture_release}/theme=places/type=place/");
    let overture_segments_endpoint = format!(
        "s3://overturemaps-us-west-2/release/{overture_release}/theme=transportation/type=segment/"
    );
    let overture_coverage = format!(
        "global vector; Overture Maps Foundation {overture_release} release (auto-discovered, refreshed every 24h)"
    );
    let mut payload = json!({
        "schema": "emem.materializers.v1",
        "responder_pubkey_b32": pubkey_b32.clone(),
        "auto_materialize_enabled": auto_materialize_enabled(),
        "materializers": [
            {
                "band":              "modis.ndvi_mean",
                "unit":              null,
                "value_kind":        "primary",
                "coverage":          "global terrestrial; 250m native; latest valid 16-day composite within last 90 days",
                "upstream_scheme":   "ornl_modis",
                "upstream_endpoint": "https://modis.ornl.gov/rst/api/v1/MOD13Q1/subset",
                "derivation_fn_key": "modis_ornl_subset@1",
                "confidence":        0.9,
                "tempo":             "medium",
                "kernel_for_router": "heat_gaussian",
                "notes":             "MOD13Q1 16-day composite NDVI from MODIS Terra. ~10–15 s upstream latency. NDVI ∈ [-0.2, 1.0]; values <0 mean water/snow, >0.4 mean dense vegetation. Quality flag filtering uses fill_value=-3000 from the NASA QA layer."
            },
            {
                "band":              "gmrt.topobathy_mean",
                "unit":              "m",
                "value_kind":        "primary",
                "coverage":          "global; positive over land, negative over water",
                "upstream_scheme":   "gmrt",
                "upstream_endpoint": "https://www.gmrt.org/services/PointServer",
                "derivation_fn_key": "gmrt_pointserver@1",
                "confidence":        0.9,
                "notes":             "Lamont-Doherty Earth Observatory's Global Multi-Resolution Topography. Single dataset that fuses Cop-DEM, GEBCO, multibeam swaths, and high-res surveys into a globally-consistent topo-bathy raster. The right band when you need a number for any point on Earth, including ocean."
            },
            {
                "band":              "copdem30m.elevation_mean",
                "unit":              "m",
                "value_kind":        "primary_or_absence",
                "coverage":          "land surface only; AWS Open Data Cop-DEM GLO-30 publishes no tile over open ocean (responder signs Absence) and has documented gaps in some Antarctic interiors. Land cells globally.",
                "upstream_scheme":   "copernicus.dem.30m.aws",
                "upstream_endpoint": "https://copernicus-dem-30m.s3.amazonaws.com/",
                "derivation_fn_key": "copernicus_dem_30m_aws_pixel@1",
                "confidence":        0.95,
                "notes":             "Migrated 2026-05-29 from the rate-limited Open-Meteo per-point HTTPS path (`open_meteo_copdem90m@1`) to the AWS Open Data COG mirror. Polygon recalls now fire one HTTP range read per tile via `prewarm_polygon_static_cog_bands` instead of N rate-limited point queries. Use this when you specifically want a *land DEM* answer with a signed absence over water rather than topo-bathy. For most general-purpose elevation queries, prefer gmrt.topobathy_mean."
            },
            {
                "band":              "geotessera",
                "unit":              null,
                "value_kind":        "primary",
                "value_shape":       [128],
                "coverage":          "global terrestrial; 0.1° tile grid; v1 vintage 2024",
                "upstream_scheme":   "geotessera",
                "upstream_endpoint": "https://dl2.geotessera.org/v1/global_0.1_degree_representation",
                "derivation_fn_key": "geotessera_v1@2",
                "confidence":        0.85,
                "tempo":             "slow",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "https_range",
                "fetch_bytes_per_cell": 640,
                "notes":             "Tessera 128-D foundation embedding (Cambridge/Clay-style; quantized int8 + float32 scales). Per-cell HTTPS range reads against the public bucket — ~640 B downloaded per recall instead of the full 91 MB tile. Native CRS is per-tile UTM; we project (lat,lng) into the tile's UTM CRS (tessera_row_col) to pick the exact pixel — the @2 fn_key marks this UTM-correct mapping (@1 used a linear-in-degrees row/col that mis-sampled by ~1–2 px near tile corners). Default vintage 2024; use geotessera.YYYY for an explicit year, or geotessera.multi_year for the 8-year stack."
            },
            {
                "band":              "geotessera.multi_year",
                "unit":              null,
                "value_kind":        "primary",
                "value_shape":       [1024],
                "coverage":          "global terrestrial; 0.1° tile grid; 8-year stack 2017-2024",
                "upstream_scheme":   "geotessera",
                "upstream_endpoint": "https://dl2.geotessera.org/v1/global_0.1_degree_representation",
                "derivation_fn_key": "geotessera_multi_year@2",
                "confidence":        0.85,
                "tempo":             "slow",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "9x https_range (one per year)",
                "fetch_bytes_per_cell": 5760,
                "notes":             "1152-D = 128 × 9 years (2017,2018,2019,2020,2021,2022,2023,2024,2025). Years with no tile coverage at this cell get NaN-masked slices (so cosine over real dims is honest, not pulled toward zero); derivation.args.years_covered records which slices are real. NaN-aware scoring (find_similar / query_region) compares only the finite overlap. Use this for time-aware similarity search — the temporal trajectory of a place across the Tessera vintage."
            },
            {
                "band":              "geotessera.bin128",
                "unit":              "bin128_be",
                "value_kind":        "primary",
                "value_shape":       [16],
                "value_encoding":    "cbor.bytes(16)",
                "coverage":          "wherever geotessera is attested — derived locally, no extra upstream call",
                "upstream_scheme":   "geotessera",
                "upstream_endpoint": "(derived from cached geotessera int8+scale vector decoded to f32)",
                "derivation_fn_key": "turboquant_geotessera_bin128_v1@1",
                "confidence":        0.85,
                "tempo":             "slow",
                "fetch_strategy":    "derived: turboquant rotation + sign-bit pack",
                "fetch_bytes_per_cell": 16,
                "use_with":          "find_similar mode=hamming or hamming_then_rerank",
                "compression_ratio": "~8x vs geotessera int8+scale (~132 B → 16 B per cell); ~32x vs the recall-decoded f32 (512 B)",
                "scoring_throughput": "~10⁹ pairs/sec/core via XOR + popcount",
                "notes":             "Sign-bit-packed 128-bit binary embedding derived from the geotessera vector (int8 + per-pixel f32 scale upstream, decoded to f32 by recall) after a fixed random orthogonal rotation (TurboQuant — Corley, https://geospatialml.com/posts/terrabit/). Designed to feed `find_similar` as a triage layer: ~65% recall@10 on its own, matches cosine precision when used with mode=hamming_then_rerank (the responder pulls 4·k Hamming candidates, re-ranks by cosine on the underlying geotessera vector). Rotation matrix is content-addressed via derivation.args[2] so a verifier can re-derive bit-for-bit."
            },
            {
                "band":              "weather.temperature_2m",
                "unit":              "degC",
                "value_kind":        "primary",
                "coverage":          "global; 15-minute updates from blended HRRR/ICON/GFS/ECMWF",
                "upstream_scheme":   "met_no",
                "upstream_endpoint": "https://api.met.no/weatherapi/locationforecast/2.0/compact",
                "derivation_fn_key": "met_no_locationforecast_compact@1",
                "confidence":        0.85,
                "tempo":             "ultra_fast",
                "kernel_for_router": "advection_linear",
                "notes":             "Current 2-m air temperature in °C. MET Norway's locationforecast/2.0/compact requires no API key and is not per-IP rate-limited; their TOS asks only for an identifying User-Agent. The data is sat-fed (ECMWF + EUMETSAT geostationary fleet)."
            },
            {
                "band":              "weather.cloud_cover",
                "unit":              "percent",
                "value_kind":        "primary",
                "coverage":          "global; 15-minute updates",
                "upstream_scheme":   "met_no",
                "upstream_endpoint": "https://api.met.no/weatherapi/locationforecast/2.0/compact",
                "derivation_fn_key": "met_no_locationforecast_compact@1",
                "confidence":        0.80,
                "tempo":             "ultra_fast",
                "kernel_for_router": "advection_linear",
                "notes":             "Total cloud-cover percentage from the geostationary-fed NWP blend. Use alongside indices.ndvi to gate vegetation queries — high cloud_cover means the latest optical composite is likely stale."
            },
            {
                "band":              "weather.precipitation_mm",
                "unit":              "mm",
                "value_kind":        "primary",
                "coverage":          "global; 15-minute updates",
                "upstream_scheme":   "met_no",
                "upstream_endpoint": "https://api.met.no/weatherapi/locationforecast/2.0/compact",
                "derivation_fn_key": "met_no_locationforecast_compact@1",
                "confidence":        0.75,
                "tempo":             "ultra_fast",
                "kernel_for_router": "advection_linear",
                "notes":             "Liquid-equivalent precipitation in the last 15-minute window."
            },
            {
                "band":              "weather.wind_speed_10m",
                "unit":              "m/s",
                "value_kind":        "primary",
                "coverage":          "global; 15-minute updates",
                "upstream_scheme":   "met_no",
                "upstream_endpoint": "https://api.met.no/weatherapi/locationforecast/2.0/compact",
                "derivation_fn_key": "met_no_locationforecast_compact@1",
                "confidence":        0.80,
                "tempo":             "ultra_fast",
                "kernel_for_router": "advection_linear",
                "notes":             "10-m wind speed in m/s. The advection kernel matches how wind itself transports the rest of the weather state."
            },
            {
                "band":              "indices.ndvi",
                "unit":              null,
                "value_kind":        "primary",
                "coverage":          "global; Sentinel-2 L2A 10 m; 5-day revisit at the equator",
                "upstream_scheme":   "sentinel_s2_l2a",
                "upstream_endpoint": "https://earth-search.aws.element84.com/v1/search → https://sentinel-cogs.s3.us-west-2.amazonaws.com/...",
                "derivation_fn_key": "sentinel2_l2a_ndvi@1",
                "confidence":        0.92,
                "tempo":             "fast",
                "kernel_for_router": "wave_seasonal",
                "fetch_strategy":    "stac_search + https_range_cog",
                "fetch_bytes_per_cell": "~600 KB (IFD + 1 tile per band × 2 bands)",
                "notes":             "Pure-Rust COG range read against AWS Open Data sentinel-cogs bucket. STAC search picks the latest scene <40% cloud that *contains* the point (intersects: Point); reflectance scale = 1e-4. NDVI = (B08 − B04) / (B08 + B04). No API key. Range read uses Predictor 2 (horizontal differencing) + Deflate decompression."
            },
            {
                "band":              "sentinel1_raw",
                "unit":              "dB",
                "value_kind":        "primary",
                "coverage":          "global; Sentinel-1 RTC (Radiometrically Terrain Corrected) C-band SAR; ~10 m; 6-12-day revisit",
                "upstream_scheme":   "sentinel_s1_rtc_mpc",
                "upstream_endpoint": "https://planetarycomputer.microsoft.com/api/stac/v1/search (collection: sentinel-1-rtc) → Azure Blob COG signed with anonymous SAS",
                "derivation_fn_key": "sentinel1_rtc_vv_db@1",
                "confidence":        0.85,
                "tempo":             "fast",
                "kernel_for_router": "wave_seasonal",
                "fetch_strategy":    "stac_search + https_range_cog (Azure SAS-signed)",
                "fetch_bytes_per_cell": "~700 KB (IFD + 1 tile)",
                "notes":             "VV polarisation gamma-naught backscatter in dB (10·log₁₀ of linear power). Radar — works at night and through cloud, complements indices.ndvi for all-weather monitoring. Source: Microsoft Planetary Computer's `sentinel-1-rtc` collection — proper UTM-projected COG (the upstream Element84 `sentinel-1-grd` mirror ships SAFE-format scenes with GCP-based georeferencing the pure-Rust COG sampler can't decode). Asset URLs are anonymous Azure Blobs signed with a free SAS token cached process-wide."
            },
            {
                "band":              "surface_water.recurrence",
                "unit":              "percent",
                "value_kind":        "primary_or_absence",
                "value_shape":       "scalar",
                "coverage":          "global ±60° lat from JRC observation footprint; 30 m native; static climatology over 1984-2021. Absence over permanent non-water and unmapped polar interiors (255 nodata).",
                "upstream_scheme":   "jrc.gsw.v1_4.recurrence",
                "upstream_endpoint": "https://storage.googleapis.com/global-surface-water/downloads2021/recurrence/recurrence_{lon_left10}_{lat_top10}v1_4_2021.tif",
                "derivation_fn_key": "jrc_gsw_recurrence_pixel@1",
                "confidence":        0.95,
                "tempo":             "static",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "https_range_cog",
                "fetch_bytes_per_cell": "~320 KB (IFD head + 1 tile)",
                "notes":             "Inter-annual water recurrence in percent: 0 = never water, 100 = water every year of the 1984-2021 record, intermediate = flood-prone or seasonal water. The canonical signed answer to 'has this place been wet historically?' Pure-Rust COG range read against the public GCS bucket; tiles are EPSG:4326 so no UTM projection step. License: JRC open."
            },
            {
                "band":              "overture.buildings.count",
                "unit":              null,
                "value_kind":        "primary",
                "coverage":          overture_coverage,
                "upstream_scheme":   "overture.maps.foundation.v1",
                "upstream_endpoint": overture_buildings_endpoint,
                "active_release":    overture_release,
                "derivation_fn_key": "overture_buildings_count@1",
                "confidence":        0.95,
                "tempo":             "slow",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "anonymous_s3 + parquet_row_group_pruning + wkb_polygon_centroid",
                "notes":             "Count of building footprints whose vertex-mean centroid falls inside the cell bbox. Pure-Rust path: object_store anonymous AWS S3 + parquet 55 async reader + WKB decode. No GDAL, no Python, no API key. Per-file parquet footers cached in process memory; first-call to a region warms the cache. Release tag is auto-discovered from the public bucket on startup and refreshed every 24h."
            },
            {
                "band":              "overture.places.count",
                "unit":              null,
                "value_kind":        "primary",
                "coverage":          overture_coverage,
                "upstream_scheme":   "overture.maps.foundation.v1",
                "upstream_endpoint": overture_places_endpoint,
                "active_release":    overture_release,
                "derivation_fn_key": "overture_places_count@1",
                "confidence":        0.90,
                "tempo":             "slow",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "anonymous_s3 + parquet_row_group_pruning + wkb_point_inside",
                "notes":             "Count of POIs (places) whose Point geometry falls inside the cell bbox. Same anonymous S3 + pure-Rust parquet path as buildings."
            },
            {
                "band":              "overture.transportation.road_length_m",
                "unit":              "m",
                "value_kind":        "primary",
                "coverage":          overture_coverage,
                "upstream_scheme":   "overture.maps.foundation.v1",
                "upstream_endpoint": overture_segments_endpoint,
                "active_release":    overture_release,
                "derivation_fn_key": "overture_road_length_m@1",
                "confidence":        0.85,
                "tempo":             "slow",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "anonymous_s3 + parquet_row_group_pruning + wkb_linestring_clip",
                "notes":             "Sum of road-segment length (metres) intersecting the cell bbox. Each WKB LineString is clipped to the bbox via Liang-Barsky and projected planar with a local-tangent-plane scale at the cell's mid-latitude. The cell is small (~10 m × ~6 m at 52° N) so planar approximation is well within millimetres of haversine."
            }
        ],
        "agent_hint": {
            "how_it_works": "Call POST /v1/recall {cell, bands: [<band>]}. If the cell has no fact yet AND auto_materialize_enabled is true, the responder fetches the upstream value, signs the resulting fact under its identity, persists it, and returns it in the same response. The next call hits the hot cache (~10 ms instead of ~180 ms).",
            "trust_model":  "Materialized facts are signed by the responder pubkey above, NOT by the upstream provider. The fact's `derivation.fn_key` declares the function that produced the value; an external attester can run the same function and submit their own signed fact to corroborate or correct.",
            "absence_facts": "Fact::Absence (kind: \"absence\") records confirmed no-data with a content-addressed `reason_cid`. Treat it as a signed statement that the responder tried and got no answer — don't re-fetch on every call.",
            "history_bounds": "Each entry now carries `history_available_from_unix` / `history_available_to_unix` derived from the upstream provider's documented record. `null` means present-only (e.g. weather nowcast, Overture release snapshot, or static climatology). Pass these to `emem_backfill` to materialize and sign every per-tslot fact in the window — turns 'I want history' into 'history exists in the ledger'.",
        }
    });

    // Decorate every materializer entry with history bounds + a tempo
    // seconds value so an agent can size an `emem_backfill` window
    // without a second round-trip to /v1/coverage_matrix. We post-process
    // here rather than inlining per-entry to keep the inline JSON literal
    // above the single source of truth for connector text — `band_materializer_meta`
    // is the single source of truth for the bounds themselves.
    if let Some(arr) = payload
        .get_mut("materializers")
        .and_then(|v| v.as_array_mut())
    {
        for entry in arr.iter_mut() {
            let band = entry
                .get("band")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string());
            let Some(band) = band else { continue };
            let meta = band_materializer_meta(&band);
            if let Some(obj) = entry.as_object_mut() {
                obj.insert(
                    "history_available_from_unix".into(),
                    meta.as_ref()
                        .and_then(|m| m.history_from_unix)
                        .map(JsonValue::from)
                        .unwrap_or(JsonValue::Null),
                );
                obj.insert(
                    "history_available_to_unix".into(),
                    meta.as_ref()
                        .and_then(|m| m.history_to_unix)
                        .map(JsonValue::from)
                        .unwrap_or(JsonValue::Null),
                );
                if let Some(m) = meta.as_ref() {
                    obj.insert(
                        "tempo_seconds".into(),
                        JsonValue::from(m.tempo.slot_seconds()),
                    );
                    obj.insert("temporal_kind".into(), JsonValue::from(m.kind.as_str()));
                    obj.insert("upstream_wire_path".into(), JsonValue::from(m.wire_path));
                }
                obj.insert(
                    "responder_pubkey_b32".into(),
                    JsonValue::from(pubkey_b32.clone()),
                );
            }
        }
    }
    // Backfill every materializable band that the curated payload above
    // doesn't already mention, using `band_materializer_meta` +
    // `all_materializable_bands` as the registry. This guarantees the
    // /v1/materializers endpoint is never a partial view of the responder
    // — agents that introspect either /v1/materializers or
    // /v1/data_availability see the same band list. The auto-generated
    // entries have less editorial text but full machine-readable fields.
    if let Some(arr) = payload
        .get_mut("materializers")
        .and_then(|v| v.as_array_mut())
    {
        let curated: std::collections::HashSet<String> = arr
            .iter()
            .filter_map(|e| {
                e.get("band")
                    .and_then(|v| v.as_str())
                    .map(|s| s.to_string())
            })
            .collect();
        for band in all_materializable_bands() {
            if curated.contains(&band) {
                continue;
            }
            let Some(meta) = band_materializer_meta(&band) else {
                continue;
            };
            let mut obj = serde_json::Map::new();
            obj.insert("band".into(), JsonValue::from(band.clone()));
            obj.insert("value_kind".into(), JsonValue::from("primary"));
            obj.insert("auto_generated".into(), JsonValue::from(true));
            obj.insert(
                "notes".into(),
                JsonValue::from("auto-registered from band_materializer_meta — see /v1/data_availability for the full machine-readable catalog and any peer-reviewed citation in source code"),
            );
            obj.insert(
                "history_available_from_unix".into(),
                meta.history_from_unix
                    .map(JsonValue::from)
                    .unwrap_or(JsonValue::Null),
            );
            obj.insert(
                "history_available_to_unix".into(),
                meta.history_to_unix
                    .map(JsonValue::from)
                    .unwrap_or(JsonValue::Null),
            );
            obj.insert(
                "tempo_seconds".into(),
                JsonValue::from(meta.tempo.slot_seconds()),
            );
            obj.insert("temporal_kind".into(), JsonValue::from(meta.kind.as_str()));
            obj.insert("upstream_wire_path".into(), JsonValue::from(meta.wire_path));
            obj.insert(
                "responder_pubkey_b32".into(),
                JsonValue::from(pubkey_b32.clone()),
            );
            arr.push(JsonValue::Object(obj));
        }
    }

    // Pagination + summary projection. The full materializer registry was
    // ~62 KB at 0.0.4 — well over MCP's 25 KB cap. Slice the array into a
    // page and (optionally) drop the long `notes` field per entry. The
    // top-level `pagination` envelope makes the slicing honest:
    // agents see `total` and `next_url` and know to iterate.
    let (page, page_size) = resolve_page_params(&q);
    let summary = q.summary.unwrap_or(false);
    let materializers_full = payload
        .as_object_mut()
        .and_then(|m| m.remove("materializers"))
        .and_then(|v| match v {
            JsonValue::Array(a) => Some(a),
            _ => None,
        })
        .unwrap_or_default();
    let total = materializers_full.len();
    let start = (page - 1).saturating_mul(page_size).min(total);
    let end = start.saturating_add(page_size).min(total);
    let items: Vec<JsonValue> = materializers_full[start..end]
        .iter()
        .map(|entry| project_materializer_entry(entry, summary))
        .collect();
    let extra = if summary { "&summary=true" } else { "" };
    let pagination = pagination_envelope(page, page_size, total, "/v1/materializers", extra);
    if let Some(map) = payload.as_object_mut() {
        map.insert(
            "_explanation".into(),
            JsonValue::from(
                "Paginated list — defaults to page=1, page_size=20 (max 100) so the response fits MCP's 25 KB cap. Pass `?page=N&page_size=K` to walk the registry, or `?summary=true` to drop the long `notes` body per entry. `pagination.total` is the full registry size — agents MUST follow `pagination.next_url` to see the rest.",
            ),
        );
        map.insert("pagination".into(), pagination);
        map.insert("items".into(), JsonValue::Array(items.clone()));
        // Back-compat alias. Older clients read the top-level
        // `materializers` key. Keep it pointing at the SAME paginated
        // slice — never the full set — so the page-size contract is
        // honoured uniformly.
        map.insert("materializers".into(), JsonValue::Array(items));
    }
    Json(payload)
}

/// Project one materializer entry. When `summary == true`, drop the
/// long `notes` field (often 1-3 paragraphs of editorial prose per
/// entry). Always retains `band`, `unit`, `value_kind`, `coverage`,
/// `upstream_scheme`, `upstream_endpoint`, `derivation_fn_key`,
/// `confidence`, `tempo`, `responder_pubkey_b32`, and the
/// `history_available_*` window so an agent can decide whether to
/// fetch the full entry from `/v1/materializers?page=…` without
/// `summary=true`.
fn project_materializer_entry(entry: &JsonValue, summary: bool) -> JsonValue {
    if !summary {
        return entry.clone();
    }
    let Some(obj) = entry.as_object() else {
        return entry.clone();
    };
    let drop_keys = ["notes"];
    let mut out = serde_json::Map::with_capacity(obj.len());
    for (k, v) in obj.iter() {
        if drop_keys.contains(&k.as_str()) {
            continue;
        }
        out.insert(k.clone(), v.clone());
    }
    out.insert("summary".into(), JsonValue::Bool(true));
    JsonValue::Object(out)
}

/// `GET /v1/data_availability` — temporal catalog: for every band this
/// responder can materialize, the upstream-of-record window the data
/// genuinely covers and the temporal shape an agent should expect from
/// `recall` / `backfill`. Driven entirely by `band_materializer_meta`
/// (single source of truth) and `all_materializable_bands` (concrete
/// enumeration including each Tessera vintage). No hardcoded windows
/// or duplicated lookups.
///
/// Shape (per entry):
/// ```json
/// {
///   "band": "geotessera.2020",
///   "kind": "annual_snapshot",
///   "tempo": "slow",
///   "tempo_seconds": 31556952,
///   "history_available_from_unix": 1577836800,
///   "history_available_to_unix":   1609459199,
///   "history_available_from_iso":  "2020-01-01T00:00:00Z",
///   "history_available_to_iso":    "2020-12-31T23:59:59Z",
///   "upstream_wire_path": "dl2.geotessera.org per-year .npy HTTPS-Range",
///   "backfill_supported": true,
///   "tslot_grid_seconds": 31556952
/// }
/// ```
///
/// `backfill_supported` is `true` iff the band has a `kind` other than
/// `now_only` AND `materialize_band_at` will accept a past `target_unix`
/// for it. Used by /v1/backfill clients to skip nowcast bands without a
/// trial-and-error 422.
async fn data_availability(State(s): State<AppState>) -> Json<JsonValue> {
    let pubkey_b32 = data_encoding::BASE32_NOPAD
        .encode(&s.identity.pubkey.0)
        .to_lowercase();
    let mut entries: Vec<JsonValue> = Vec::new();
    for band in all_materializable_bands() {
        let Some(meta) = band_materializer_meta(&band) else {
            continue;
        };
        let backfill_supported = !matches!(meta.kind, BandKind::NowOnly);
        let from_iso = meta
            .history_from_unix
            .and_then(|u| u64::try_from(u).ok())
            .map(iso8601_utc);
        let to_iso = meta
            .history_to_unix
            .and_then(|u| u64::try_from(u).ok())
            .map(iso8601_utc);
        entries.push(json!({
            "band": band,
            "kind": meta.kind.as_str(),
            "tempo": format!("{:?}", meta.tempo).to_lowercase(),
            "tempo_seconds": meta.tempo.slot_seconds(),
            "tslot_grid_seconds": meta.tempo.slot_seconds(),
            "history_available_from_unix": meta.history_from_unix,
            "history_available_to_unix": meta.history_to_unix,
            "history_available_from_iso": from_iso,
            "history_available_to_iso": to_iso,
            "upstream_wire_path": meta.wire_path,
            "backfill_supported": backfill_supported,
        }));
    }
    Json(json!({
        "schema": "emem.data_availability.v1",
        "responder_pubkey_b32": pubkey_b32,
        "auto_materialize_enabled": auto_materialize_enabled(),
        "tessera_vintages": TESSERA_YEARS_RANGE_PUBLIC.clone().collect::<Vec<_>>(),
        "kinds": [
            {"name": "static",          "meaning": "single signed fact valid for all time (Cop-DEM, GMRT, JRC GSW recurrence)"},
            {"name": "annual_snapshot", "meaning": "one fact per calendar year on Jan 1 UTC (Tessera per-year)"},
            {"name": "annual_stack",    "meaning": "stack of multiple annual snapshots fused into one fact (Tessera multi-year 1024-D)"},
            {"name": "time_series",     "meaning": "per-tslot historical series fetched on demand from a STAC-style archive (Sentinel-2 L2A, Sentinel-1 RTC, MODIS NDVI)"},
            {"name": "now_only",        "meaning": "provider only exposes current value plus short forecast — no historical record (met.no)"},
            {"name": "per_release",     "meaning": "versioned global snapshot — each release replaces the previous (Overture Maps)"}
        ],
        "entries": entries,
    }))
}

/// `GET /v1/fleet` — declare the satellite/sensor lineage that feeds each
/// materialized band. The protocol-level contract is the *band manifest*;
/// this endpoint is the editorial layer that names the actual hardware
/// platforms and their cadences, so an agent can decide "I need 15-min
/// observation rate" or "I need radar so it works at night" without
/// reading every band's documentation.
///
/// The mapping is keyed by upstream sensor (TerrA-MODIS, GMRT multibeam,
/// Cop-DEM 30m, etc.) → list of bands that derive from it. Geostationary
/// weather satellites (GOES-16/17/18, Himawari-9, Meteosat-9/11) are
/// declared as the *cadence source* for the weather bands even though
/// the wire path goes through Open-Meteo's NWP blend — this matches how
/// the temporal router classifies these bands as `ultra_fast`.
/// `GET /v1/coverage_matrix` — observability layer that lets agents (and
/// operators) see, in one call, which bands are *actually being answered*
/// by the responder right now. Combines the static manifest (what bands
/// exist), the materializer registry (what we know how to fetch), and the
/// live storage index (what we have).
///
/// For every band in the active manifest plus every materializer-only band
/// (modis.ndvi_mean, gmrt.topobathy_mean, copdem30m.elevation_mean,
/// indices.*, s2.*, sentinel1_raw, geotessera.*, weather.*) we surface:
///   - has_materializer: bool — wired into try_materialize_bands?
///   - facts_count       : u64 — distinct (cell, tslot) pairs cached
///   - last_attested_at  : ISO 8601 — when the responder last signed under
///     this band; helps an agent cite the freshest band for a query
///   - tempo / family    : from the manifest, for the temporal router
///   - sat_lineage       : satellite/sensor names from the fleet declaration
///
/// O(N) over the full storage index; capped by EMEM_COVERAGE_MATRIX_LIMIT
/// (default 50_000) so big deployments don't blow the response.
async fn coverage_matrix(State(s): State<AppState>) -> Json<JsonValue> {
    use std::collections::BTreeMap;
    // Clamp the operator-provided limit to a sane range. An unbounded
    // value lets a single anonymous GET pin the storage index scan for
    // arbitrarily long; below 1k the matrix loses utility. 100k is
    // already ~enough memory pressure that we don't want callers
    // raising it accidentally.
    let limit: usize = std::env::var("EMEM_COVERAGE_MATRIX_LIMIT")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(50_000)
        .clamp(1_000, 100_000);

    // Aggregate over the storage index. For each entry we resolve the
    // actual fact and parse its `signed_at` to get a real wall-clock
    // last-attested per band. This is one cache get_many call per ~256
    // entries (chunked) so a 50k-entry deployment still answers in
    // sub-second range. Entries with non-zero tslots that *look* like
    // unix timestamps still update the bound (cheap path) so weather/
    // index bands surface freshness even when the get_many lookup is
    // slow or partial.
    let mut counts: BTreeMap<String, (u64, Option<i64>)> = BTreeMap::new();
    if let Ok(entries) = s.storage.iter_index(Some(limit)).await {
        // First pass: counts + tslot proxy (cheap, no fact lookups).
        let mut cids: Vec<emem_fact::FactCid> = Vec::with_capacity(entries.len());
        let mut keys: Vec<emem_cache::CanonicalKey> = Vec::with_capacity(entries.len());
        for (k, cid) in entries {
            let entry = counts.entry(k.band.clone()).or_insert((0, None));
            entry.0 += 1;
            if k.tslot >= 1_577_836_800 {
                let cur = entry.1.unwrap_or(0);
                if (k.tslot as i64) > cur {
                    entry.1 = Some(k.tslot as i64);
                }
            }
            cids.push(cid);
            keys.push(k);
        }
        // Second pass: chunked fact resolution to pick up signed_at on
        // bands whose tslot is 0 (static bands like copdem, koppen, dem)
        // or non-timestamp-shaped (foundation embedding tslots).
        const CHUNK: usize = 256;
        for (chunk_keys, chunk_cids) in keys.chunks(CHUNK).zip(cids.chunks(CHUNK)) {
            if let Ok(facts) = s.storage.get_facts_many(chunk_cids).await {
                for (k, fact) in chunk_keys.iter().zip(facts) {
                    let signed_at_unix = match fact.as_ref() {
                        Some(emem_fact::Fact::Primary(p)) => parse_iso8601_unix(&p.signed_at),
                        Some(emem_fact::Fact::Absence(n)) => parse_iso8601_unix(&n.signed_at),
                        _ => None,
                    };
                    if let Some(ts) = signed_at_unix {
                        let entry = counts.entry(k.band.clone()).or_insert((0, None));
                        let cur = entry.1.unwrap_or(0);
                        if ts > cur {
                            entry.1 = Some(ts);
                        }
                    }
                }
            }
        }
    }

    // Bands that ship a materializer in this build, with metadata for the agent.
    let materializer_bands: &[(&str, &str, &str, &[&str])] = &[
        ("modis.ndvi_mean", "medium", "vegetation",
            &["Terra (NASA EOS AM-1) MODIS"]),
        ("gmrt.topobathy_mean", "static", "terrain",
            &["GMRT (Lamont-Doherty multibeam fleet)"]),
        ("copdem30m.elevation_mean", "static", "terrain",
            &["TanDEM-X / Copernicus DEM"]),
        ("geotessera", "slow", "foundation",
            &["Tessera v1 (Cambridge AAILab + Clay-style composite)"]),
        ("geotessera.multi_year", "slow", "foundation",
            &["Tessera v1 multi-year (2017-2024 stacked, 1024-D)"]),
        ("geotessera.2017", "slow", "foundation", &["Tessera v1 2017"]),
        ("geotessera.2018", "slow", "foundation", &["Tessera v1 2018"]),
        ("geotessera.2019", "slow", "foundation", &["Tessera v1 2019"]),
        ("geotessera.2020", "slow", "foundation", &["Tessera v1 2020"]),
        ("geotessera.2021", "slow", "foundation", &["Tessera v1 2021"]),
        ("geotessera.2022", "slow", "foundation", &["Tessera v1 2022"]),
        ("geotessera.2023", "slow", "foundation", &["Tessera v1 2023"]),
        ("geotessera.2024", "slow", "foundation", &["Tessera v1 2024"]),
        ("geotessera.bin128", "slow", "foundation",
            &["Derived: turboquant rotation + sign-bit pack of geotessera vector (int8+scale upstream, decoded f32 via recall). 16 B/cell on disk; Hamming-distance triage k-NN at ~10⁹ pairs/sec/core. Designed to feed `find_similar` mode=hamming / hamming_then_rerank — the full vector under `geotessera` is still attested for re-rank."]),
        ("indices.ndvi", "fast", "vegetation", &["Sentinel-2A/B/C MSI (NDVI)"]),
        ("indices.ndwi", "fast", "water",      &["Sentinel-2A/B/C MSI (NDWI Gao)"]),
        ("indices.mndwi", "fast", "water",     &["Sentinel-2A/B/C MSI (MNDWI McFeeters)"]),
        ("indices.evi", "fast", "vegetation",  &["Sentinel-2A/B/C MSI (EVI)"]),
        ("indices.nbr", "fast", "fire",        &["Sentinel-2A/B/C MSI (NBR)"]),
        ("indices.ndmi", "fast", "vegetation", &["Sentinel-2A/B/C MSI (NDMI)"]),
        ("indices.savi", "fast", "vegetation", &["Sentinel-2A/B/C MSI (SAVI)"]),
        ("indices.bsi",  "fast", "soil",       &["Sentinel-2A/B/C MSI (BSI)"]),
        ("indices.ndbi", "fast", "human",      &["Sentinel-2A/B/C MSI (NDBI built-up)"]),
        ("s2.B01", "fast", "optical", &["Sentinel-2A/B/C MSI B01 60m coastal aerosol"]),
        ("s2.B02", "fast", "optical", &["Sentinel-2A/B/C MSI B02 10m blue"]),
        ("s2.B03", "fast", "optical", &["Sentinel-2A/B/C MSI B03 10m green"]),
        ("s2.B04", "fast", "optical", &["Sentinel-2A/B/C MSI B04 10m red"]),
        ("s2.B05", "fast", "optical", &["Sentinel-2A/B/C MSI B05 20m red-edge 1"]),
        ("s2.B06", "fast", "optical", &["Sentinel-2A/B/C MSI B06 20m red-edge 2"]),
        ("s2.B07", "fast", "optical", &["Sentinel-2A/B/C MSI B07 20m red-edge 3"]),
        ("s2.B08", "fast", "optical", &["Sentinel-2A/B/C MSI B08 10m wide NIR"]),
        ("s2.B8A", "fast", "optical", &["Sentinel-2A/B/C MSI B8A 20m narrow NIR"]),
        ("s2.B09", "fast", "optical", &["Sentinel-2A/B/C MSI B09 60m water vapor"]),
        ("s2.B11", "fast", "optical", &["Sentinel-2A/B/C MSI B11 20m SWIR-1"]),
        ("s2.B12", "fast", "optical", &["Sentinel-2A/B/C MSI B12 20m SWIR-2"]),
        ("s2.scl", "fast", "vision",  &["Sentinel-2 L2A scene-classification (uint8 0..11)"]),
        ("sentinel1_raw", "fast", "radar",
            &["Sentinel-1A/C C-band SAR (RTC γ0 VV in dB) via Microsoft Planetary Computer"]),
        ("surface_water.recurrence", "static", "water",
            &["JRC Global Surface Water v1.4 (Pekel et al. 2016, Landsat-derived 1984-2021 inter-annual recurrence climatology)"]),
        ("koppen", "static", "climate",
            &["Beck Köppen-Geiger v1 1-km present-day classification (Beck et al. 2018, Sci Data 5:180214; CC-BY-4.0)"]),
        ("weather.temperature_2m", "ultra_fast", "climate",
            &["MET Norway api.met.no — sat-fed via ECMWF + EUMETSAT geostationary fleet"]),
        ("weather.cloud_cover", "ultra_fast", "climate",
            &["MET Norway api.met.no"]),
        ("weather.precipitation_mm", "ultra_fast", "climate",
            &["MET Norway api.met.no"]),
        ("weather.wind_speed_10m", "ultra_fast", "climate",
            &["MET Norway api.met.no"]),
        ("weather.relative_humidity_2m", "ultra_fast", "climate",
            &["MET Norway api.met.no — instant.details.relative_humidity"]),
        ("weather.dew_point_2m", "ultra_fast", "climate",
            &["MET Norway api.met.no — instant.details.dew_point_temperature"]),
        ("weather.air_pressure_msl", "ultra_fast", "climate",
            &["MET Norway api.met.no — instant.details.air_pressure_at_sea_level"]),
        ("weather.wind_direction_10m", "ultra_fast", "climate",
            &["MET Norway api.met.no — instant.details.wind_from_direction"]),
        ("overture.buildings.count", "slow", "human",
            &["Overture Maps Foundation buildings parquet (anonymous S3)"]),
        ("overture.places.count", "slow", "human",
            &["Overture Maps Foundation places parquet (anonymous S3)"]),
        ("overture.transportation.road_length_m", "slow", "human",
            &["Overture Maps Foundation transportation parquet (anonymous S3)"]),
        // WDPA-equivalent protected-area lookup. Source-of-record is
        // OpenStreetMap `boundary=protected_area` polygons via the public
        // Overpass API (point-in-polygon `is_in()` filter); OSM mirrors
        // the same designations WDPA tracks (NPS / USFWS / IUCN / EU
        // CDDA) and tags `protect_class` 1..6 → IUCN Ia..VI. Protected
        // Planet's own REST API requires an account-gated token, so OSM
        // is the canonical open-data path.
        ("protected", "static", "human",
            &["OpenStreetMap WDPA mirror (Overpass API, boundary=protected_area + protect_class → IUCN)"]),
    ];
    let mat_set: std::collections::HashSet<&str> = materializer_bands.iter().map(|t| t.0).collect();

    let registry = &*emem_core::bands::DEFAULT;
    let mut bands_json: Vec<JsonValue> = Vec::new();
    let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();

    // Cube placeholder slots are family aliases (`dem`, `cop_dem`,
    // `climate`, `indices`, `landcover`, …) — they reserve cube offsets
    // for a *family* of attestable sub-keys and are not themselves
    // directly materialized. Without this map, the coverage matrix
    // shows `cop_dem mat=False facts=0` next to a working
    // `copdem30m.elevation_mean mat=True`, which makes agents conclude
    // "DEM is offline" when in fact it's wired under a different key.
    //
    // Source of truth: `Band.scalar_keys` from `bands-v0.json`,
    // intersected with `band_materializer_meta(child).is_some()` (the
    // canonical wired-band predicate). No hardcoded sub-key tables —
    // adding a child to the registry automatically surfaces it here.
    // The same registry CID input always produces the same alias map,
    // so this is deterministic and federation-safe.
    let cube_aliases: BTreeMap<String, Vec<String>> = registry
        .bands
        .iter()
        .map(|b| {
            let wired: Vec<String> = b
                .scalar_keys
                .iter()
                .filter(|child| {
                    // A child is "wired" iff this responder has a
                    // materializer for it. Family-bands whose own key
                    // is materializable (e.g. `geotessera`,
                    // `sentinel1_raw`) include themselves so the alias
                    // map remains a complete list of attestable keys.
                    band_materializer_meta(child).is_some() || mat_set.contains(child.as_str())
                })
                .cloned()
                .collect();
            (b.key.clone(), wired)
        })
        .collect();
    let alias_for =
        |k: &str| -> &[String] { cube_aliases.get(k).map(|v| v.as_slice()).unwrap_or(&[]) };
    let aggregate_subkey_facts = |subkeys: &[String]| -> (u64, Option<i64>) {
        let mut n_total = 0u64;
        let mut latest: Option<i64> = None;
        for k in subkeys {
            if let Some((n, last)) = counts.get(k) {
                n_total += *n;
                if let Some(t) = last {
                    latest = Some(latest.map_or(*t, |x| x.max(*t)));
                }
            }
        }
        (n_total, latest)
    };

    let pubkey_b32 = data_encoding::BASE32_NOPAD
        .encode(&s.identity.pubkey.0)
        .to_lowercase();

    // Cube bands first — every entry from bands-v0.json. For family
    // alias slots we surface the wired sub-keys so an agent reading
    // this view is never told a family is offline when its sub-keys
    // are live.
    for b in &registry.bands {
        seen.insert(b.key.clone());
        let (n_self, last_self) = counts.get(&b.key).copied().unwrap_or((0, None));
        let direct_mat = mat_set.contains(b.key.as_str());
        let subkeys = alias_for(b.key.as_str());
        // A band is a family alias when its registry-declared
        // `scalar_keys` includes at least one *distinct* wired child —
        // `sentinel1_raw` listing only itself is NOT a family alias,
        // but `cop_dem` listing `copdem30m.elevation_mean` IS.
        let is_family_alias = subkeys.iter().any(|k| k != &b.key);
        let (n_sub, last_sub) = if is_family_alias {
            aggregate_subkey_facts(subkeys)
        } else {
            (0, None)
        };
        let n = n_self + n_sub;
        let last = match (last_self, last_sub) {
            (Some(a), Some(b)) => Some(a.max(b)),
            (Some(a), None) | (None, Some(a)) => Some(a),
            (None, None) => None,
        };
        let has_mat = direct_mat
            || is_family_alias
                && subkeys
                    .iter()
                    .any(|k| mat_set.contains(k.as_str()) || band_materializer_meta(k).is_some());
        let sat_lineage: Vec<&str> = materializer_bands
            .iter()
            .find(|t| t.0 == b.key.as_str())
            .map(|t| t.3.to_vec())
            .unwrap_or_default();
        let meta = band_materializer_meta(b.key.as_str());
        let history_from = meta.as_ref().and_then(|m| m.history_from_unix);
        let history_to = meta.as_ref().and_then(|m| m.history_to_unix);
        // Build the per-subkey detail array. Always emit the field
        // (even as `[]`) so agents can discriminate "no children"
        // from "field missing / handler hasn't been updated".
        let wired_subkeys_detail: Vec<JsonValue> = subkeys
            .iter()
            .map(|k| {
                let m = band_materializer_meta(k);
                let kind = m.as_ref().map(|m| m.kind.as_str()).unwrap_or("unknown");
                let has_mat = m.is_some() || mat_set.contains(k.as_str());
                json!({
                    "key": k,
                    "kind": kind,
                    "has_materializer": has_mat,
                    "source_scheme": source_scheme_for(k),
                })
            })
            .collect();
        let mut row = json!({
            "band":             b.key,
            "family":           format!("{:?}", b.family).to_ascii_lowercase(),
            "tempo":            format!("{:?}", b.tempo).to_ascii_lowercase(),
            "tempo_seconds":    b.tempo.slot_seconds(),
            "in_cube":          true,
            "cube_offset":      b.offset,
            "cube_dims":        b.dims,
            "has_materializer": has_mat,
            "facts_count":      n,
            "last_attested_unix_s": last,
            "sat_lineage":      sat_lineage,
            "history_available_from_unix": history_from,
            "history_available_to_unix":   history_to,
            "responder_pubkey_b32": pubkey_b32,
            // Honest default: empty array, never null and never
            // omitted. Agents that see this field can rely on it being
            // present on every band row.
            "wired_subkeys":    wired_subkeys_detail,
        });
        if is_family_alias {
            row.as_object_mut()
                .unwrap()
                .insert("is_family_alias".into(), JsonValue::Bool(true));
        }
        bands_json.push(row);
    }
    // Auxiliary materializer-only bands (not in the cube). These are
    // leaf scalar bands, never family aliases — `wired_subkeys` is
    // always `[]` here, but we emit the field so agents can
    // unconditionally read `row["wired_subkeys"]` without a presence
    // check (honest defaults rule, see commit notes).
    for (key, tempo, family, sats) in materializer_bands {
        if seen.contains(*key) {
            continue;
        }
        let (n, last) = counts.get(*key).copied().unwrap_or((0, None));
        let meta = band_materializer_meta(key);
        let tempo_seconds = meta.as_ref().map(|m| m.tempo.slot_seconds()).unwrap_or(0);
        let history_from = meta.as_ref().and_then(|m| m.history_from_unix);
        let history_to = meta.as_ref().and_then(|m| m.history_to_unix);
        bands_json.push(json!({
            "band":             key,
            "family":           family,
            "tempo":            tempo,
            "tempo_seconds":    tempo_seconds,
            "in_cube":          false,
            "has_materializer": true,
            "facts_count":      n,
            "last_attested_unix_s": last,
            "sat_lineage":      sats,
            "history_available_from_unix": history_from,
            "history_available_to_unix":   history_to,
            "responder_pubkey_b32": pubkey_b32,
            "wired_subkeys":    JsonValue::Array(Vec::new()),
        }));
    }

    // Roll-ups for the agent's at-a-glance view.
    let total_bands = bands_json.len();
    let total_facts: u64 = counts.values().map(|(n, _)| *n).sum();
    let with_materializer = bands_json
        .iter()
        .filter(|b| {
            b.get("has_materializer")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
        })
        .count();
    let with_facts = bands_json
        .iter()
        .filter(|b| b.get("facts_count").and_then(|v| v.as_u64()).unwrap_or(0) > 0)
        .count();

    // Top-level family-alias summary so an agent can read the whole
    // alias map in one shot without iterating `bands[]`. Derived from
    // the same `cube_aliases` map built above — only family bands
    // (those with at least one *distinct* wired child) are included,
    // and entries are key-only (the per-child detail lives in the
    // band row's `wired_subkeys[]`). The map is sorted by family key
    // (BTreeMap iteration order) so the response is deterministic.
    let family_aliases_summary: serde_json::Map<String, JsonValue> = cube_aliases
        .iter()
        .filter(|(family, subs)| subs.iter().any(|k| k != *family))
        .map(|(family, subs)| {
            (
                family.clone(),
                JsonValue::Array(subs.iter().map(|k| JsonValue::String(k.clone())).collect()),
            )
        })
        .collect();

    Json(json!({
        "schema": "emem.coverage_matrix.v1",
        "totals": {
            "bands_declared": total_bands,
            "bands_with_materializer": with_materializer,
            "bands_with_facts": with_facts,
            "total_facts": total_facts,
            "iter_index_limit": limit,
        },
        "responder_pubkey_b32": data_encoding::BASE32_NOPAD
            .encode(&s.identity.pubkey.0).to_lowercase(),
        "bands": bands_json,
        "family_aliases": family_aliases_summary,
        "agent_hint": {
            "use_when": "Decide which band to /v1/recall before paying for materialization. has_materializer=false bands need a third-party signed Attestation; in_cube=false bands ride alongside the 1792-D layout but aren't byte-addressable in the cube.",
            "family_aliases": "Some cube slots reserve byte ranges for a *family* of attestable sub-keys; recall calls go to the granular subkey, not the family slot. When `is_family_alias=true`, the row reports rolled-up `facts_count` and a per-band `wired_subkeys[]` array of `{key, kind, has_materializer, source_scheme}` so the agent can pick the actual band to materialize. The top-level `family_aliases` object summarises the same map family→[subkey,…] for one-shot scanning. Both are derived from `bands-v0.json` `scalar_keys` intersected with the materializer registry — no hardcoded sub-key tables, deterministic per registry CID.",
            "freshness": "facts_count>0 with a recent last_attested_unix_s means the band has been answered globally somewhere recently; per-cell freshness still needs /v1/temporal_route.",
            "history_bounds": "history_available_from_unix / history_available_to_unix bound what an `emem_backfill` call can materialize on this responder. `null` = the band has no historical materializer here (e.g. weather nowcast, Overture snapshot, or static climatology where one fact answers for all time).",
            "tempo_seconds": "Slot duration in seconds. 0 = static (one fact). Use it to convert between Unix epoch and tslot when planning a backfill window.",
            "federation": "responder_pubkey_b32 is the ed25519 key that signs every fact for this band at this responder. When the directory grows beyond one responder, the same band may be signed by different pubkeys across responders — agents should treat (responder_pubkey, fact_cid) as the unit of trust.",
            "fleet": "/v1/fleet for per-platform sensor lineage (cadence, swath, native_res_m).",
        },
    }))
}

async fn fleet() -> Json<JsonValue> {
    Json(json!({
        "schema": "emem.fleet.v1",
        "platforms": [
            {
                "platform":      "Terra (NASA EOS AM-1)",
                "sensor":        "MODIS",
                "swath_km":      2330,
                "revisit":       "1–2 days global; 16-day composite for indices",
                "native_res_m":  250,
                "tempo":         "medium",
                "bands":         ["modis.ndvi_mean"],
                "wire_path":     "ORNL DAAC TESViS REST → Primary fact",
                "notes":         "Optical multi-spectral; NDVI 16-day composite is the canonical vegetation signal at 250 m. Aqua (PM-1) provides the same MOD13 family with a 90-min phase shift; not yet wired."
            },
            {
                "platform":      "GMRT (Lamont-Doherty multibeam fleet)",
                "sensor":        "Acoustic + DEM fusion",
                "swath_km":      null,
                "revisit":       "static (peer-reviewed updates ~quarterly)",
                "native_res_m":  null,
                "tempo":         "static",
                "bands":         ["gmrt.topobathy_mean"],
                "wire_path":     "GMRT PointServer → Primary fact",
                "notes":         "Single peer-reviewed topo-bathy raster fusing Cop-DEM, GEBCO, multibeam, and high-res sounders. The right band for any-point-on-Earth elevation including ocean."
            },
            {
                "platform":      "TanDEM-X (Copernicus DEM GLO-30, ESA)",
                "sensor":        "Cop-DEM 30 m",
                "swath_km":      null,
                "revisit":       "static",
                "native_res_m":  30,
                "tempo":         "static",
                "bands":         ["copdem30m.elevation_mean"],
                "wire_path":     "AWS Open Data Cop-DEM GLO-30 COG (HTTPS range-read) → Primary or Absence fact",
                "notes":         "Land DEM. Returns Fact::Absence over water (Cop-DEM uses 0 m as no-data marker over ocean) so downstream models can distinguish 'sea level over water' from 'land at 0 m'."
            },
            {
                "platform":      "Tessera v1 (Cambridge AAILab + Clay-style)",
                "sensor":        "Multi-source self-supervised composite",
                "swath_km":      null,
                "revisit":       "annual",
                "native_res_m":  10,
                "tempo":         "slow",
                "bands":         ["geotessera"],
                "wire_path":     "dl2.geotessera.org HTTPS range → Primary fact",
                "notes":         "128-D foundation embedding ingested via HTTPS range reads against the public bucket; ~640 B per cell instead of 91 MiB per tile. Native CRS is per-tile UTM."
            },
            {
                "platform":      "GOES-16/17/18 + Himawari-9 + Meteosat-9/11 (geostationary fleet)",
                "sensor":        "ABI / AHI / SEVIRI imagers, blended through HRRR/ICON/GFS/ECMWF NWP",
                "swath_km":      "full disk",
                "revisit":       "10–15 minutes",
                "native_res_m":  500,
                "tempo":         "ultra_fast",
                "bands":         [
                    "weather.temperature_2m",
                    "weather.cloud_cover",
                    "weather.precipitation_mm",
                    "weather.wind_speed_10m"
                ],
                "wire_path":     "Open-Meteo Forecast `current` endpoint → Primary fact",
                "notes":         "Open-Meteo blends NWP runs that ingest the geostationary fleet every ~15 min. We declare the geostationary cadence as the temporal class so the router scores `wave_seasonal` / `advection_linear` against actual orbital physics rather than against the JSON wire format."
            },
            {
                "platform":      "Sentinel-2A/B/C",
                "sensor":        "MSI",
                "swath_km":      290,
                "revisit":       "5 days at equator",
                "native_res_m":  10,
                "tempo":         "fast",
                "bands":         ["indices.ndvi"],
                "wire_path":     "Element84 STAC search → AWS Open Data sentinel-cogs bucket → pure-Rust COG range read (TIFF IFD + Deflate + Predictor 2 decode) → Primary fact",
                "notes":         "Optical multi-spectral. Per-cell call touches ~600 KB across two bands (B04 + B08) instead of the 200 MB native scene; STAC search uses intersects:Point so we always get a tile that *contains* the cell."
            },
            {
                "platform":      "Sentinel-1A/C",
                "sensor":        "C-band SAR (RTC)",
                "swath_km":      250,
                "revisit":       "6-12 days",
                "native_res_m":  10,
                "tempo":         "fast",
                "bands":         ["sentinel1_raw"],
                "wire_path":     "MPC STAC (sentinel-1-rtc) → Azure Blob COG (anonymous SAS) → range read → Primary fact (dB-scaled VV gamma0)",
                "notes":         "All-weather radar; complements Sentinel-2 when cloudy. dB = 10·log₁₀(linear γ0). Source: Microsoft Planetary Computer's Radiometrically Terrain Corrected mirror — proper UTM-projected COG. Anonymous SAS token cached process-wide."
            },
            {
                "platform":      "Overture Maps Foundation (open vector basemap consortium)",
                "sensor":        "Crowdsourced + commercial vector aggregation (OSM, Microsoft, Meta, Esri, TomTom contributions)",
                "swath_km":      "global vector",
                "revisit":       "monthly snapshots",
                "native_res_m":  null,
                "tempo":         "slow",
                "bands":         [
                    "overture.buildings.count",
                    "overture.places.count",
                    "overture.transportation.road_length_m"
                ],
                "wire_path":     "Anonymous S3 (overturemaps-us-west-2) → ListObjectsV2 → parquet 55 async reader (row-group pruning on bbox struct stats) → WKB decode (Point/LineString/Polygon centroid) → Primary fact",
                "notes":         "Vector basemap, not a satellite — but the cadence and routing class match `slow` foundation embeddings (annual-ish cadence + linear AR(1) kernel). Each cell touches one or two row groups across one or two parquet files; per-file footers are cached so adjacent cells are cheap. No API key, no auth header."
            }
        ],
        "agent_hint": {
            "by_cadence": {
                "ultra_fast (<= 1 hour)": ["weather.temperature_2m","weather.cloud_cover","weather.precipitation_mm","weather.wind_speed_10m"],
                "fast (~5–12 days)":      ["indices.ndvi","sentinel1_raw","s2.B04","s2.B08"],
                "medium (~16–30 days)":   ["modis.ndvi_mean"],
                "slow (annual or monthly)": ["geotessera","geotessera.multi_year","overture.buildings.count","overture.places.count","overture.transportation.road_length_m"],
                "static":                 ["copdem30m.elevation_mean","gmrt.topobathy_mean"]
            },
            "by_capability": {
                "all_weather":   ["sentinel1_raw"],
                "night":         ["sentinel1_raw"],
                "vegetation":    ["modis.ndvi_mean","indices.ndvi","geotessera"],
                "weather":       ["weather.temperature_2m","weather.cloud_cover","weather.precipitation_mm","weather.wind_speed_10m"],
                "elevation":     ["gmrt.topobathy_mean","copdem30m.elevation_mean"],
                "embedding":     ["geotessera","geotessera.multi_year"],
                "human_geography": ["overture.buildings.count","overture.places.count","overture.transportation.road_length_m"]
            },
            "router":            "POST /v1/temporal_route to score these bands against your query time and intent.",
            "live_observability": "GET /v1/coverage_matrix for live per-band facts_count, has_materializer, last_attested_at."
        }
    }))
}

async fn functions() -> Json<JsonValue> {
    Json(serde_json::to_value(&*emem_core::functions::DEFAULT).unwrap_or(json!({})))
}

async fn sources() -> Json<JsonValue> {
    Json(serde_json::to_value(&*emem_core::sources::DEFAULT).unwrap_or(json!({})))
}

/// `GET /v1/algorithms` — content-addressed algorithm registry.
///
/// Composition recipes that fuse already-attested band facts (and
/// embeddings) into derived scores, classifications, and similarity
/// metrics. Distinct from `/v1/functions` (which derives a single band
/// value from raw upstream sources) and from `/v1/bands` (the data slot
/// itself). Receipts that quote a derived score should cite
/// `algorithm_cid` alongside the input `fact_cids` so a downstream
/// verifier can replay the same composition.
///
/// Three kinds: `solo` (one band → derived), `combined` (multi-band
/// composite), `embedding` (operations on the geotessera vector).
/// Process-wide cached algorithms_cid — the registry is content-addressed
/// and immutable for the life of the process, so we hash it once and
/// reuse the string everywhere it's surfaced (/health, /v1/manifests,
/// /v1/discover, /v1/agent_card, /v1/algorithms, /v1/intent, /.well-known).
pub(crate) static ALGORITHMS_CID: LazyLock<Option<String>> =
    LazyLock::new(|| emem_core::manifest::manifest_cid(&*emem_core::algorithms::DEFAULT).ok());

/// Process-wide cached topics_cid — the topic registry (`topics-v0.json`)
/// is content-addressed and immutable for the life of the process. The
/// CID is surfaced on `/v1/manifests` so an agent can pin which routing
/// taxonomy was active when its receipt was issued, and dual-write a
/// new taxonomy without breaking older receipts.
static TOPICS_CID: LazyLock<Option<String>> =
    LazyLock::new(|| emem_core::manifest::manifest_cid(&*emem_core::topics::DEFAULT).ok());

/// Pagination + projection options for `/v1/algorithms` and
/// `/v1/materializers`. Both endpoints used to return the entire registry
/// in a single response (190 KB and 62 KB respectively at 0.0.4) which
/// blew through MCP's 25 KB cap and silently truncated against agent
/// context windows. The handlers now accept `?page=N&page_size=K` (clamped
/// to 1..=100) and an optional `?summary=true` projection that drops the
/// long `formula` body and `temporal_recipe` so an agent can browse the
/// catalog cheaply, then GET `/v1/algorithms/<key>` for one entry's full
/// detail.
///
/// The default behaviour with NO query params still returns page 1 — never
/// the full set — so MCP responses stay bounded by default and agents
/// learn to iterate. The response body always carries `pagination.total`
/// and `pagination.has_next` so the slicing is honest.
#[derive(serde::Deserialize, Default, Debug, Clone)]
struct PageQuery {
    /// 1-indexed page number. Defaults to `1` when absent.
    #[serde(default)]
    page: Option<usize>,
    /// Items per page. Defaults to `20`, clamped to `1..=100`.
    #[serde(default)]
    page_size: Option<usize>,
    /// When `true`, drop the long `formula` / `notes` body and
    /// `temporal_recipe` so each entry stays compact.
    #[serde(default)]
    summary: Option<bool>,
}

/// Default page size when the caller omits `?page_size=`. Held in one
/// place so the test that pins the clamp also pins the default.
const PAGINATION_DEFAULT_PAGE_SIZE: usize = 20;
/// Hard cap on `page_size` — anything above this is silently clamped so
/// a runaway client can't ask for the full registry in one shot.
const PAGINATION_MAX_PAGE_SIZE: usize = 100;

/// Resolve `(page, page_size)` from a `PageQuery`, applying the default
/// page (`1`), default size (`PAGINATION_DEFAULT_PAGE_SIZE`), and the
/// hard `page_size` clamp. Pulled into a free function so the same
/// resolution logic is unit-testable without spinning a router.
fn resolve_page_params(q: &PageQuery) -> (usize, usize) {
    let page = q.page.unwrap_or(1).max(1);
    let page_size = q
        .page_size
        .unwrap_or(PAGINATION_DEFAULT_PAGE_SIZE)
        .clamp(1, PAGINATION_MAX_PAGE_SIZE);
    (page, page_size)
}

/// Build the `pagination` envelope shared by `/v1/algorithms` and
/// `/v1/materializers`. `path` is the relative URL prefix (e.g.
/// `/v1/algorithms`) used to render `next_url` / `prev_url`. `extra`
/// is appended verbatim after `page=N&page_size=K` so callers can
/// preserve filters like `&summary=true` across pages.
fn pagination_envelope(
    page: usize,
    page_size: usize,
    total: usize,
    path: &str,
    extra: &str,
) -> JsonValue {
    let total_pages = total.div_ceil(page_size.max(1));
    let has_next = page < total_pages;
    let has_prev = page > 1 && total > 0;
    let url_for = |p: usize| -> String { format!("{path}?page={p}&page_size={page_size}{extra}") };
    json!({
        "page":       page,
        "page_size":  page_size,
        "total":      total,
        "total_pages": total_pages,
        "has_next":   has_next,
        "next_url":   if has_next { Some(url_for(page + 1)) } else { None },
        "has_prev":   has_prev,
        "prev_url":   if has_prev { Some(url_for(page - 1)) } else { None },
    })
}

/// Project one algorithm entry. When `summary == true`, drop `formula`
/// and `temporal_recipe` — the two heavy fields that pushed the full
/// registry response over MCP's 25 KB cap. The `key`, `kind`,
/// `input_bands`, and `citation` headline are always retained so an
/// agent can decide whether to GET `/v1/algorithms/<key>` for the full
/// body. Returns the structured-serde value when the entry can't be
/// projected (defensive — `Algorithm` always serializes, but we never
/// panic in a route handler).
fn project_algorithm_entry(a: &emem_core::algorithms::Algorithm, summary: bool) -> JsonValue {
    if !summary {
        return serde_json::to_value(a).unwrap_or(json!({}));
    }
    let inputs: Vec<&str> = a.inputs.iter().filter_map(|i| i.band.as_deref()).collect();
    json!({
        "key":           a.key,
        "kind":          a.kind,
        "domain":        a.domain,
        "inputs":        inputs,
        "output":        a.output,
        "citation":      a.citation,
        "when_to_use":   a.when_to_use,
        "fetch_url":     format!("/v1/algorithms/{}", a.key),
        // 2026-05-29 audit honesty: agents must know which algorithms
        // have a runtime evaluator and which are formula-only. As of the
        // post-audit landing 76 of 159 entries are documentation-only
        // and the dispatcher silently skips them. Surfacing the flag
        // here makes the "agent quotes an algorithm_key whose math
        // never ran" trap impossible to fall into.
        "documentation_only": a.documentation_only,
        "runtime_evaluable":  (a.evaluation.is_some() || a.runtime_path.is_some()) && !a.documentation_only,
        "runtime_path":       a.runtime_path,
        "partial_runtime":    a.partial_runtime,
        "summary":       true,
    })
}

/// Project one entry of the `/v1/ask` `algorithms_for_question[]` list.
/// When `verbose == false` (the default since the 2026-05-05 deepscan)
/// drop the long `formula` body and the `temporal_recipe` block — both
/// live at `/v1/algorithms/<key>` so the agent can fetch them on
/// demand. The signed receipt itself is unrelated to this projection
/// and stays intact in `facts.facts[]`.
fn project_algorithm_for_question(
    topic: &str,
    a: &emem_core::algorithms::Algorithm,
    inputs: &[&str],
    verbose: bool,
) -> JsonValue {
    if verbose {
        json!({
            "topic":            topic,
            "key":              a.key,
            "kind":             a.kind,
            "input_bands":      inputs,
            "formula":          a.formula,
            "output":           a.output,
            "citation":         a.citation,
            "fetch_url":        format!("/v1/algorithms/{}", a.key),
            "temporal_recipe":  a.temporal_recipe,
        })
    } else {
        json!({
            "topic":            topic,
            "key":              a.key,
            "kind":             a.kind,
            "input_bands":      inputs,
            "output":           a.output,
            "citation":         a.citation,
            "fetch_url":        format!("/v1/algorithms/{}", a.key),
            "documentation_only": a.documentation_only,
            "runtime_evaluable":  (a.evaluation.is_some() || a.runtime_path.is_some()) && !a.documentation_only,
            "runtime_path":       a.runtime_path,
            "partial_runtime":    a.partial_runtime,
        })
    }
}

async fn algorithms(axum::extract::Query(q): axum::extract::Query<PageQuery>) -> Json<JsonValue> {
    let reg = &*emem_core::algorithms::DEFAULT;
    let cid = ALGORITHMS_CID.clone();
    let (page, page_size) = resolve_page_params(&q);
    let summary = q.summary.unwrap_or(false);

    let total = reg.algorithms.len();
    let start = (page - 1).saturating_mul(page_size).min(total);
    let end = start.saturating_add(page_size).min(total);
    let items: Vec<JsonValue> = reg.algorithms[start..end]
        .iter()
        .map(|a| project_algorithm_entry(a, summary))
        .collect();
    let extra = if summary { "&summary=true" } else { "" };
    let pagination = pagination_envelope(page, page_size, total, "/v1/algorithms", extra);

    Json(json!({
        "manifest": reg.manifest,
        "version":  reg.version,
        "algorithms_cid": cid,
        "_note": reg.note,
        "_explanation": "Paginated list — defaults to page=1, page_size=20 (max 100) so the response fits MCP's 25 KB cap. Pass `?page=N&page_size=K` to walk the registry, `?summary=true` to drop the long `formula` body and `temporal_recipe` per entry, or GET `/v1/algorithms/<key>` for one entry's full detail. `pagination.total` is the full registry size — agents MUST follow `pagination.next_url` to see the rest.",
        "agent_hint": {
            "what_this_is": "A content-addressed dictionary of recipes that combine attested band facts into composite answers (e.g. flood_risk@1, water_consensus@1, embedding_novelty@1). Receipts citing one of these names + the algorithm_cid let any other operator replay the same composition deterministically.",
            "how_to_use":    "1) Pick the entry whose `when_to_use` matches the agent's query. 2) Read its `inputs[].band` list and assemble a single `/v1/recall` (or `/v1/recall_many`) body. 3) Apply the `formula` in-process. 4) Cite the algorithm key + algorithms_cid alongside the fact_cids in the agent's reply.",
            "kinds": {
                "solo":      "single band → derived classification or scalar",
                "combined":  "multi-band weighted composite",
                "embedding": "cosine / novelty / change over geotessera vectors",
            },
        },
        "pagination": pagination,
        "items": items.clone(),
        // Back-compat alias. Older clients (and the homepage demo) still
        // read the top-level `algorithms` key. Keep it pointing at the
        // SAME paginated slice — never the full set — so the page-size
        // contract is honoured uniformly. Agents that want everything
        // must follow `pagination.next_url`.
        "algorithms": items,
    }))
}

/// `GET /v1/algorithms/:key` — one algorithm entry by key (URL-encode
/// the `@` in keys like `flood_risk@1` if your client cares — most
/// don't). Returns 404 if the key is unknown.
async fn algorithm_detail(
    axum::extract::Path(key): axum::extract::Path<String>,
) -> Result<Json<JsonValue>, ApiError> {
    let reg = &*emem_core::algorithms::DEFAULT;
    match reg.lookup(&key) {
        Some(a) => Ok(Json(serde_json::to_value(a).unwrap_or(json!({})))),
        None => {
            let known: Vec<&str> = reg.algorithms.iter().map(|a| a.key.as_str()).collect();
            Err(ApiError(
                StatusCode::NOT_FOUND,
                ErrorBody {
                    code: emem_core::error::ErrorCode::CidNotFound,
                    message: format!(
                        "no algorithm with key {key:?}; see /v1/algorithms — known keys: {}",
                        known.join(", "),
                    ),
                    details: None,
                },
            ))
        }
    }
}

/// Topic-grouped band + algorithm registry. Single source of truth for
/// the discovery surface that lives at `/v1/topics`, the
/// `data_at_this_cell` block in `/v1/locate`, and the MCP
/// `emem_topics` tool. Lifting it out of inline JSON literals
/// guarantees the three surfaces never drift.
///
/// Design contract: every band in `live_bands_by_topic` has a live
/// materializer at this responder; every algorithm in
/// `algorithms_for_topic` resolves in
/// `emem_core::algorithms::DEFAULT`. The
/// `declared_but_no_materializer_at_this_responder` block is the
/// honest "slot reserved, no connector" hint — agents should report
/// these as gaps rather than concluding the protocol can't answer.
fn topics_payload() -> JsonValue {
    // Drive the topic groupings from `topics-v0.json` (the content-addressed
    // registry under `topics_cid`) so /v1/topics surfaces every routable
    // topic instead of the partial inline subset the function originally
    // hardcoded. `live_bands_by_topic` keeps its old contract — only bands
    // the responder will actually materialise — by filtering each topic's
    // declared bands against `all_materializable_bands()`. Algorithms are
    // surfaced verbatim from the registry; the existing `topics_payload_
    // algorithm_keys_resolve_in_registry` test guards against drift between
    // topics-v0.json and algorithms-v0.json.
    let topic_reg = &*emem_core::topics::DEFAULT;
    let materializable: Vec<String> = all_materializable_bands();
    let live: std::collections::HashSet<&str> = materializable.iter().map(|s| s.as_str()).collect();
    let algo_reg = &*emem_core::algorithms::DEFAULT;
    let caps = cached_capabilities();
    let live_extensions: std::collections::HashSet<&str> =
        caps.extensions.iter().map(|s| s.as_str()).collect();

    let mut live_bands_by_topic = serde_json::Map::new();
    let mut algorithms_for_topic = serde_json::Map::new();
    // Capability overlay: for every algorithm key referenced by any
    // topic, declare whether it can run *right now* given the cached
    // sidecar capabilities. Uses the `inference.required_extension`
    // field on each algorithm — `None` means scalar/CPU and runs
    // unconditionally; `Some("gpu")` requires the sidecar to advertise
    // `gpu` in `extensions[]`. Surface as a map so agents can filter
    // their candidate list at planning time without hitting /health.
    let mut algorithm_availability = serde_json::Map::new();
    for t in &topic_reg.topics {
        let live_only: Vec<JsonValue> = t
            .bands
            .iter()
            .filter(|b| live.contains(b.as_str()))
            .cloned()
            .map(JsonValue::String)
            .collect();
        if !live_only.is_empty() {
            live_bands_by_topic.insert(t.key.clone(), JsonValue::Array(live_only));
        }
        if !t.algorithms.is_empty() {
            algorithms_for_topic.insert(
                t.key.clone(),
                JsonValue::Array(
                    t.algorithms
                        .iter()
                        .cloned()
                        .map(JsonValue::String)
                        .collect(),
                ),
            );
            for k in &t.algorithms {
                if algorithm_availability.contains_key(k) {
                    continue;
                }
                let required = algo_reg
                    .lookup(k)
                    .and_then(|a| a.inference.as_ref())
                    .and_then(|i| i.required_extension.as_deref());
                let available_now = required
                    .map(|ext| live_extensions.contains(ext))
                    .unwrap_or(true);
                algorithm_availability.insert(
                    k.clone(),
                    json!({
                        "available_now": available_now,
                        "required_extension": required,
                    }),
                );
            }
        }
    }

    json!({
        "_purpose": "Topic-grouped list of every band you can recall at this cell, plus the algorithm recipes that compose those bands into named scores. Read this BEFORE concluding the responder doesn't have data on a topic, and BEFORE inventing a synthesis formula in your own reasoning.",
        "_source": format!(
            "Driven from the content-addressed topic registry (topics-v0.json, {} topics). `live_bands_by_topic` filters each topic's declared bands against this responder's wired materializers; `algorithms_for_topic` is verbatim from the registry. Topics absent from `live_bands_by_topic` have all their bands declared-but-not-wired here — see `declared_but_no_materializer_at_this_responder`.",
            topic_reg.topics.len()
        ),
        "_pointer_to_algorithms": format!(
            "GET /v1/algorithms for the full content-addressed registry of {} composition recipes (flood_risk, walkability, embedding_novelty, carbon-MRV, SDG indicators, etc.) used by `algorithms_for_topic` below. Cite the algorithm key + algorithms_cid in the receipt.",
            emem_core::algorithms::DEFAULT.algorithms.len()
        ),
        "live_bands_by_topic": live_bands_by_topic,
        "algorithms_for_topic": algorithms_for_topic,
        "algorithm_availability": algorithm_availability,
        "_capabilities_hint": "GET /v1/capabilities for the live extensions[] snapshot. \
                                `algorithm_availability[<key>].available_now == false` means \
                                the algorithm's `inference.required_extension` is not in the \
                                sidecar's current extensions[] (typically GPU off / sidecar down). \
                                Use a CPU/scalar alternative for the same topic, or surface an \
                                honest `gpu_unavailable` to the user.",
        "visual_surfaces": {
            "rgb_scene_png": "GET /v1/cells/{cell64}/scene.png?max_cloud=20  (or MCP `emem_cell_scene_rgb`) — true-colour Sentinel-2 L2A 256×256 thumbnail",
            "cell_geojson":  "GET /v1/cells/{cell64}/geojson — polygon hexagon for any GIS / map renderer",
            "cell_recall_geojson": "GET /v1/cells/{cell64}/recall_geojson?bands=... — properties carry every fact value the responder has, ready to style",
        },
        "declared_but_no_materializer_at_this_responder": {
            "_meaning": "Bands reserved in the cube manifest but with no live connector at this responder. Recall returns empty (existing attestations only, no upstream fetch).",
            "_authoritative_list": "GET /v1/bands — every band entry now carries a `materializer:{kind:'live'|'declared_no_connector', ...}` field. Filter on kind=='declared_no_connector' for the canonical, code-derived set.",
            "_note_on_cube_family_roots": "Most unwired keys are cube FAMILY-ROOT slots whose SCALAR children are wired (e.g. `koppen` root unwired but `koppen.major_class` live; `surface_water` cube key reserved but `surface_water.recurrence` answers the flood-history question). Use /v1/materializers for the per-scalar wired list.",
            "_note_on_foundation_models_at_this_responder": "Four foundation embeddings are wired at this responder. `geotessera` (Tessera v1, 128-D, 10 m grid, annual) is the default similarity surface. `prithvi_eo2` (IBM-NASA Prithvi-EO-2.0-300M-TL, 1024-D fact value carried in the 384-D cube slot at offset 894, 30 m chip / 6.7 km receptive field, scene-aware) anchors algorithms that need a learned ViT representation rather than a contrastive embedding. `clay_v1` (Made With Clay v1.5, 1024-D fact value in the 384-D cube slot at offset 199, 10 m chip / 2.56 km receptive field, wavelength-conditioned) is the finer-resolution sibling. `galileo` (NASA Harvest Galileo Base / Tiny, 768-D or 192-D pooled embedding, 30 m × 8×8 chip / 240 m receptive field; variant set by EMEM_GALILEO_VARIANT) is the small-footprint multi-modal foundation surfaced via the sidecar's /predict/galileo_embed. All three GPU-only foundation bands sign honest Absence with reason=gpu_unavailable when the sidecar is unreachable — no CPU fallback because the embedding's kernel-order accumulation would differ.",
        },
        "how_to_use": "Pick the topic that matches the user's question. (1) If the user wants ONE band's value, look up `live_bands_by_topic` and call `emem_recall` with those bands — they auto-fetch on miss. (2) If the user wants a COMPOSITE answer (flood risk, walkability, climate exposure, similarity, change), look up `algorithms_for_topic` and call `emem_algorithms` for the recipe — apply its `formula` over a single `emem_recall` body that fetches every input band, then cite the algorithm key + algorithms_cid alongside the input fact_cids. (3) For a VISUAL answer, hit `visual_surfaces.rgb_scene_png` (or MCP `emem_cell_scene_rgb`). (4) If the topic only appears under `declared_but_no_materializer_at_this_responder`, tell the user this responder has the slot reserved but no live connector (don't claim emem has no flood/water/etc. data — be precise). Topics not listed at all (e.g. real-time air quality, traffic) are genuinely out of scope for this protocol today.",
        "for_temporal_questions": "For 'last N years' questions, materializers return one fact at the latest available tslot. To get a series, call `emem_recall` repeatedly for past tslots only if the band's tempo is `slow`/`static` (which means one fact covers the period). For `fast`/`medium` tempo bands, history requires the responder to have already seeded past tslots — call `emem_trajectory` to enumerate what's there, do NOT assume historical lookback materializes on demand.",
    })
}

/// `GET /v1/topics` — content-addressed topic registry exposed as a
/// first-class endpoint. Same body the `/v1/locate` `data_at_this_cell`
/// block returns; broken out so an agent can browse the topic
/// inventory without having to first locate a cell.
async fn topics() -> Json<JsonValue> {
    let topic_reg = &*emem_core::topics::DEFAULT;
    let declared_total = topic_reg.topics.len();
    let materializable: std::collections::HashSet<String> =
        all_materializable_bands().into_iter().collect();
    let live_total = topic_reg
        .topics
        .iter()
        .filter(|t| t.bands.iter().any(|b| materializable.contains(b)))
        .count();
    Json(json!({
        "schema": "emem.topics.v1",
        // Top-level counts so an agent can audit drift between the
        // declared registry (topics-v0.json) and what this responder
        // can actually serve right now. `declared_total` is the static
        // registry size; `live_total` is the count of topics with at
        // least one wired materialiser for one of its bands on this
        // node. The difference is also surfaced field-by-field under
        // `topics.declared_but_no_materializer_at_this_responder`.
        "counts": {
            "declared_total": declared_total,
            "live_total":     live_total,
        },
        "topics": topics_payload(),
    }))
}

/// `GET /v1/errors` — error catalogue with action hints. Just listing the
/// codes (which is what we did before) doesn't tell an agent what to DO
/// when it hits one. Each entry now has a `recover` field naming the
/// concrete next step.
fn errors_payload() -> JsonValue {
    let entries: &[(&str, &str, &str)] = &[
        ("invalid_cell",                 "cell64 string did not parse",
         "Re-encode (lat,lng) via POST /v1/locate, or check the bigram boundaries (must be exactly four base-1024 bigrams joined by '.')."),
        ("invalid_resolution",           "resolution bits out of range",
         "Use the cell64 returned by /v1/locate; that's always at the active resolution. See /v1/grid_info."),
        ("tslot_mismatch",               "tslot in request doesn't match band's expected tempo",
         "Check /v1/bands for the band's `tempo` field and round your tslot to that grid."),
        ("band_not_in_registry",         "band key isn't in the active manifest",
         "GET /v1/bands for the canonical list. Common typos: missing schema namespace (need `copdem30m.elevation_mean`, not `elevation_mean`)."),
        ("function_not_in_registry",     "derivation fn_key not registered",
         "Functions ship via /v1/functions. To use a private function, register it in your registry_cid before attesting."),
        ("source_scheme_unknown",        "source.scheme not in /v1/sources",
         "GET /v1/sources for the active connector list. Self-hosters can add via the source manifest."),
        ("cid_not_found",                "fact CID exists but no matching object on disk",
         "The fact may have been pruned, or the CID is from a different responder. Verify `responder_pubkey_b32` matches between the receipt and /health."),
        ("no_geocoder_match",            "place name did not resolve in any geocoder tier (Photon + Nominatim both said 'no such place')",
         "Refine the query (more specific name; add country / region / admin level), pass `lat`+`lng` coordinates directly, or call POST /v1/locate first to inspect alternatives."),
        ("place_not_found",              "all upstream geocoders responded successfully but unanimously returned zero results — the place name is genuinely not in any layer of the cascade (embedded gazetteer, cache, Photon, Nominatim). Distinct from `geocoder_transport_down`, which means the upstream HTTP/JSON layer itself failed.",
         "Refine the query: add country/region disambiguation (e.g. 'Springfield, IL, USA'), use the official local-language spelling, or pass `lat`+`lng` directly. /v1/locate's response surfaces `via` so an agent can see which tier rejected the query."),
        ("geocoder_transport_down",      "the upstream geocoder transport failed (HTTP 5xx, DNS, timeout, malformed JSON) before a real not-found verdict could be issued. Distinct from `place_not_found` (transports succeeded but returned zero results) and from `no_geocoder_match` (the legacy code that conflated both — kept for backwards compatibility).",
         "Retry with backoff (Photon and Nominatim are public services and occasionally rate-limit). If persistent, pass `lat`+`lng` directly to bypass the geocoder. Operators can switch the primary geocoder via env."),
        ("invalid_argument",             "syntactically valid but semantically invalid request field (e.g. unparseable timestamp, out-of-range numeric, malformed enum)",
         "Re-read /openapi.json for the field's accepted shape. Common causes: ISO 8601 missing 'Z' for UTC; max_cells > 1024; band key with wrong namespace prefix."),
        ("registry_cid_unknown",         "the bound registry_cid isn't recognised",
         "Receipts pin manifest CIDs at issue time; if the responder rotated manifests, check /v1/manifests for the current `registry_cid`."),
        ("schema_cid_unknown",           "fact's schema_cid isn't loaded",
         "GET /v1/manifests for the current `schema_cid`. Re-attest with the active schema, or pin the older manifest if the responder still has it."),
        ("privacy_refused",              "band's privacy_class blocks this query at the requested resolution",
         "Drop the resolution (snap to a coarser cell) or request via an authorised attester. Check /v1/bands for `privacy_class`."),
        ("level_too_low",                "operation requires a higher protocol level (L1/L2)",
         "L0/L1 are anonymous; L2 (write/challenge) requires an attester key. Generate ed25519, post to /v1/attest_cbor."),
        ("attester_revoked",             "the attester pubkey is in the revocation set",
         "Check /v1/contributors for `revoked` flag. Submit a fresh keypair if revoked legitimately, or contest via /v1/challenge."),
        ("unauthorized",                 "missing or invalid attester signature on a write",
         "Re-sign with the same keypair that issued the registered attester pubkey; signature must be over blake3(batch_root || registry_cid || schema_cid)."),
        ("claim_undecidable",            "verify input doesn't yield true/false (e.g. NaN, type mismatch)",
         "Inspect the fact via /v1/recall — the value may be missing, the wrong type, or NaN. Tighten your claim or pre-filter before /v1/verify."),
        ("bad_signature",                "ed25519 signature failed to verify",
         "Re-sign with the correct preimage. /v1/verify_receipt's response includes `preimage_blake3_hex` so you can debug locally."),
        ("bad_merkle_proof",             "Merkle inclusion proof is malformed or doesn't reach the batch_root",
         "Re-build the proof from the canonical-sorted leaf list; verify `leaf_index` is correct."),
        ("canonical_encoding_divergence","CBOR you sent isn't deterministic per RFC 8949 §4.2.1",
         "Use a CBOR library with `canonical=true`; serde-derived structs are usually fine, freeform maps must have sorted keys."),
        ("source_fetch_failed",          "upstream open-data provider returned non-2xx",
         "Retry with backoff; check /v1/sources to confirm the URL template still resolves. May indicate provider-side outage."),
        ("source_format_mismatch",       "fetched bytes don't match the declared scheme (e.g. GeoTIFF magic missing)",
         "Re-fetch with explicit content-type. Could indicate provider migrated to a new format; consult their docs."),
        ("compute_timeout",              "derivation function exceeded EMEM_TIMEOUT_SECS",
         "Submit smaller inputs, or run the computation client-side and attest the derivative directly."),
        ("compute_quota_exceeded",       "function call hit per-attester quota",
         "Throttle, or request quota increase via /v1/contributors leaderboard (high-score attesters get larger quotas)."),
        ("rate_limited",                 "per-IP rate limit hit",
         "Backoff per the `Retry-After` header (default 60 s). Operators tune via EMEM_RATE_LIMIT_RPS."),
        ("cache_error",                  "responder's hot cache (sled) had an internal error",
         "Retry; if persistent, the responder's storage may need recovery — operators see the cause in the journald log."),
        ("internal",                     "responder-side bug",
         "Capture the response and the request that produced it; file at https://github.com/Vortx-AI/emem/issues."),
    ];
    let codes: Vec<JsonValue> = entries
        .iter()
        .map(|(c, m, r)| {
            json!({
                "code": c, "meaning": m, "recover": r,
            })
        })
        .collect();
    json!({
        "schema": "emem.errors.v1",
        "codes": codes,
        "next": [
            "GET /v1/manifests  — current registry/schema/bands/sources CIDs",
            "GET /v1/bands      — band catalogue with tempo + privacy_class",
            "POST /v1/verify_receipt — debug a bad_signature with `preimage_blake3_hex`"
        ],
    })
}

async fn errors() -> Json<JsonValue> {
    Json(errors_payload())
}

async fn tools(Query(params): Query<std::collections::HashMap<String, String>>) -> Json<JsonValue> {
    let tier = params.get("tier").map(|s| s.as_str()).unwrap_or("all");
    let filtered = emem_mcp::tools_at_tier(tier);
    let descriptors: Vec<JsonValue> = filtered.iter().map(|t| json!({
        "name": t.name,
        "title": t.title,
        "description": t.description,
        "when_to_use": t.when_to_use,
        "input_schema": serde_json::from_str::<JsonValue>(t.input_schema).unwrap_or(json!({})),
        "example_args": serde_json::from_str::<JsonValue>(t.example_args).unwrap_or(json!({})),
        "level": t.level,
        "category": t.category,
        "tier": t.tier,
        "annotations": {
            "title":           t.title,
            "readOnlyHint":    t.read_only_hint,
            "destructiveHint": t.destructive_hint,
            "idempotentHint":  t.idempotent_hint,
            "openWorldHint":   t.open_world_hint,
        },
    })).collect();
    Json(json!({ "tools": descriptors, "total": emem_mcp::TOOLS.len(), "showing_tier": tier }))
}

async fn agent_card(State(s): State<AppState>) -> Json<JsonValue> {
    // Tools are SUMMARIZED here, not inlined. Dumping all 80 full
    // descriptors (input_schema + when_to_use + example_args + annotations)
    // made this discovery card ~150 KB / ~38K tokens — a cost an agent pays
    // just to learn what exists. The full catalog is one fetch away at
    // /v1/tools (or MCP tools/list, tiered). See `tools_summary` below.
    let core_count = emem_mcp::TOOLS.iter().filter(|t| t.tier == "core").count();
    let mut by_category: std::collections::BTreeMap<String, usize> =
        std::collections::BTreeMap::new();
    for t in emem_mcp::TOOLS {
        let cat = serde_json::to_value(t.category)
            .ok()
            .and_then(|v| v.as_str().map(str::to_string))
            .unwrap_or_else(|| "other".to_string());
        *by_category.entry(cat).or_insert(0) += 1;
    }
    let tools_summary = json!({
        "count": emem_mcp::TOOLS.len(),
        "core": core_count,
        "extended": emem_mcp::TOOLS.len() - core_count,
        "by_category": by_category,
        "list": "/v1/tools",
        "mcp": "POST /mcp {\"method\":\"tools/list\"} returns all 81 tools by default; pass {\"tier\":\"core\"} for just the 10 essentials",
        "note": "Full descriptors (input_schema, when_to_use, annotations) at /v1/tools or via MCP tools/list. Summarized here to keep discovery token-cheap.",
    });
    Json(json!({
        "name": "emem",
        "version": env!("CARGO_PKG_VERSION"),
        "purpose": "Agent-native, content-addressed memory of every place on Earth. Cite-able answers about places, signed receipts, token-economical addressing.",
        // Read this FIRST. The fastest path from zero to a signed answer.
        // `discover_first` below builds the full mental model; this block
        // is the 3-call shortcut a fresh agent should try before anything
        // else. Keep it machine-readable and small on purpose.
        "getting_started": {
            "tldr": "One question → one signed answer: POST /v1/ask (free text) or POST /v1/intent (structured). Want control? locate → recall → verify_receipt.",
            "fastest_path": {
                "one_shot": {
                    "rest": "POST /v1/ask  {\"q\":\"what is the NDVI near Mount Fuji?\"}",
                    "mcp_tool": "emem_ask",
                    "also": "POST /v1/intent {\"type\":\"what_is_here\",\"place\":\"Mount Fuji\"} (emem_intent) for a structured single-shot plan+answer; `type` is one of where_is | what_is_here | is_like | did_change | find_like | confirm | ask",
                    "why": "The classifier routes the question to recall / compare / diff / hunt and returns a signed receipt — no need to pick a primitive yourself."
                },
                "controlled_path": [
                    { "n": 1, "rest": "POST /v1/locate {\"place\":\"Mount Fuji\"}", "mcp_tool": "emem_locate", "gives": "cell64 + neighborhood_cells" },
                    { "n": 2, "rest": "POST /v1/recall {\"cell\":\"<cell64>\"}", "mcp_tool": "emem_recall", "gives": "signed facts + receipt (auto-materializes on a miss)" },
                    { "n": 3, "rest": "POST /v1/verify_receipt {\"receipt\":{…}}", "mcp_tool": "emem_verify_receipt", "gives": "{valid, signer_pubkey_b32} — the answer is now cite-able" }
                ]
            },
            "first_call": "emem_ask",
            "to_cite_a_fact": "Hand another agent / audit a `memt:` token from emem_memory_token (cell + fact_cid), or emem_memory_bundle for many; anyone verifies it offline at /verify or via emem_verify_receipt.",
            "full_mental_model": "Then walk `discover_first` (bands → materializers → algorithms → coverage_matrix → manifests)."
        },
        "trigger_phrases": [
            "what is at <place>",
            "tell me about this cell",
            "compare X and Y",
            "find places like X",
            "did <band> change between t1 and t2",
            "is <claim> true at <place>",
            "average <band> over this region",
            "find <event> in <region>",
            "where is <event> happening",
            "show me <event> hotspots in <region>"
        ],
        // Negative triggers — questions the LLM should NOT route to emem.
        // Pattern-matching one of these saves a wasted call against the
        // responder and a confusingly-empty answer back to the user.
        // Each entry pairs a typical question shape with the reason emem
        // is the wrong tool, so a router that surfaces the explanation
        // to the user keeps the trust contract clean rather than just
        // saying "I don't know".
        "anti_trigger_phrases": [
            { "pattern": "is it raining right now in <place>",      "reason": "real-time / sub-daily weather is out of scope; use met.no, NOAA, or Open-Meteo directly." },
            { "pattern": "what's the forecast for <place> in 6 months", "reason": "forecasts beyond ~2 weeks fall outside the JEPA v2 horizon; emem returns an `untrained_baseline` short-circuit rather than a fake number." },
            { "pattern": "show me the sub-metre building footprint",  "reason": "imagery resolution is 10 m native (Sentinel-2 / Landsat). Sub-metre commercial imagery (Planet Pelican, Maxar) needs a different connector." },
            { "pattern": "what's the price of land at <place>",       "reason": "market / economic data is out of scope. emem signs Earth observation facts, not commercial valuations." },
            { "pattern": "live air quality reading at <place>",        "reason": "real-time air quality is out of scope; cams.* bands carry global model output, not sensor-grade now-casts. For PurpleAir / OpenAQ ground truth, call those services directly." },
            { "pattern": "stream the latest tile of <band>",           "reason": "emem is a snapshot-at-tslot model, not a streaming feed. For continuous ingest, subscribe to the upstream STAC API." },
            { "pattern": "what's inside this building",                "reason": "indoor mapping is out of scope. emem grids the outdoor surface." },
            { "pattern": "the price of carbon credits today",          "reason": "market data is out of scope. emem signs the physical MRV signal (NDVI trajectories, biomass change), not the credit price." },
            { "pattern": "verify land tenure / FPIC / country-of-origin law compliance for an EUDR DDS", "reason": "EUDR Article 9(1)(b) legality verification is structurally out of Earth-observation scope. /v1/eudr_dds covers the geolocation + deforestation parts of Annex II only; pair with a partner legality module before submitting to TRACES NT." },
            { "pattern": "submit a Due Diligence Statement to the EU Information System on my behalf", "reason": "TRACES NT submission requires EU Login + EORI registration and is the operator's responsibility. /v1/eudr_dds produces the structured payload; the operator authenticates and submits." }
        ],
        "primary_tools": ["emem_recall", "emem_state", "emem_memory_token", "emem_memory_token_resolve", "emem_compare", "emem_find_similar", "emem_diff", "emem_verify", "emem_ask", "emem_hunt"],
        // Order matters: bands → materializers → coverage_matrix builds
        // the agent's mental model in the right order. Bands declare
        // what *can* exist; materializers declare what auto-fetches on
        // recall miss (so the agent knows it can recall any cell on
        // Earth without seeding); coverage_matrix declares what's
        // already cached + freshness. Manifests pin the CIDs for
        // citation. Without `emem_materializers` here, agents miss the
        // auto-materialize contract and assume empty recall = no data.
        "discover_first": ["emem_bands", "emem_materializers", "emem_algorithms", "emem_coverage_matrix", "emem_manifests"],
        "authentication": "none for L0/L1; ed25519 attester for L2 writes",
        // Required by the Anthropic Software Directory submission flow:
        // every connector must expose a privacy URL, a terms URL, and a
        // support contact. These point to the markdown docs served from
        // /privacy and /terms; vendor + contact email are explicit so the
        // reviewer can reach the maintainer without scraping the repo.
        "vendor": "Vortx-AI",
        "contact_email": "avijeet@vortx.ai",
        // Path-relative so a self-hosted operator on a different origin
        // doesn't publish broken external links. Mirrors the same shape
        // already used at /.well-known/emem.json.
        "privacy_url": "/privacy",
        "terms_url": "/terms",
        "support_url": "https://github.com/Vortx-AI/emem/issues",
        "documentation_url": "https://github.com/Vortx-AI/emem#readme",
        "license": "Apache-2.0",
        "license_url": "https://github.com/Vortx-AI/emem/blob/main/LICENSE",
        "responder": {
            "pubkey_b32": data_encoding::BASE32_NOPAD.encode(&s.identity.pubkey.0).to_lowercase(),
            "key_epoch": s.identity.epoch.0,
        },
        "manifests": {
            "bands_cid": &s.manifests.bands_cid,
            // Spec key. `functions_cid` is the legacy alias for the same
            // value; both are set so clients diffing by either key see
            // a match. New code should read `registry_cid`.
            "registry_cid": s.manifests.registry_cid.as_str(),
            "functions_cid": s.manifests.registry_cid.as_str(),
            "sources_cid": &s.manifests.sources_cid,
            "schema_cid": s.manifests.schema_cid.as_str(),
            "algorithms_cid": ALGORITHMS_CID.clone(),
            "topics_cid": TOPICS_CID.clone(),
            // Which routing backend the topic_router actually loaded at
            // startup. "transformer" = model2vec-rs cosine match (the
            // happy path); "keyword" = alias-keyword fallback because
            // the model could not be fetched / loaded. Surfaced so an
            // agent debugging routing quality can tell at a glance
            // whether the responder is in degraded mode.
            "topic_router_backend": topic_router::TopicRouter::global().backend_name(),
        },
        // Reconciles the four band counts agents see across surfaces so
        // they don't have to guess which one is authoritative. The
        // numbers come from one place each — no copy / no constant —
        // so this stays in sync as connectors land or retire.
        "band_taxonomy": {
            "_purpose": "Four different band counts surface across the protocol because they measure different things. This block names each one and gives the live count from the same source the corresponding endpoint reads, so an agent sees a unified picture.",
            "cube_slots": {
                "count":          emem_core::bands::DEFAULT.bands.len(),
                "what_it_means":  "Top-level band keys in the canonical 1792-D voxel layout (geotessera, sentinel2_raw, indices, etc.). One slot can carry many attestable subkeys (e.g. sentinel2_raw covers s2.B01..B12).",
                "see_endpoint":   "/v1/bands",
            },
            "materializer_wired": {
                "count":          all_materializable_bands().len(),
                "what_it_means":  "Concrete band names (cube slot + subkey) that this responder will auto-fetch on a recall miss. Every entry maps to a real upstream connector.",
                "see_endpoint":   "/v1/materializers (also /v1/data_availability with kind/tempo/history-window per band)",
            },
            "tools": {
                "count":          emem_mcp::TOOLS.len(),
                "what_it_means":  "Distinct MCP / REST tools — what an agent actually calls. Some tools cross many bands (e.g. emem_recall is one tool that recalls any wired band).",
                "see_endpoint":   "/v1/tools (or MCP tools/list)",
            },
            "algorithms": {
                "count":          emem_core::algorithms::DEFAULT.algorithms.len(),
                "what_it_means":  "Composition recipes that fuse multiple band facts into named scores (flood_risk, walkability, carbon NPP, SDG indicators, …). Each is content-addressed under algorithms_cid.",
                "see_endpoint":   "/v1/algorithms",
            },
        },
        "surfaces": {
            "rest_openapi":     "/openapi.json",
            "rest_openapi_action_subset": "/v1/openapi.action.json",
            "mcp_jsonrpc":      "/mcp",
            "well_known":       "/.well-known/emem.json",
            "ai_plugin":        "/.well-known/ai-plugin.json",
            "agents_md":        "/agents.md",
            "whitepaper_md":    "/whitepaper.md",
            "llms_txt":         "/llms.txt",
            "privacy":          "/privacy",
            "terms":            "/terms",
            "fleet":            "/v1/fleet",
            "coverage_matrix":  "/v1/coverage_matrix",
            "materializers":    "/v1/materializers",
            "data_availability":"/v1/data_availability",
            "algorithms":       "/v1/algorithms",
            "temporal_route":   "/v1/temporal_route",
            "reviews":          "/v1/reviews",
            "state":            "/v1/state",
            "state_multi":      "/v1/state_multi",
            "state_diff":       "/v1/state_diff",
            "memory_token":     "/v1/memory_token",
            "memory_token_resolve": "/v1/memory_token/resolve",
            "memory_contradictions": "/v1/memory_contradictions",
            "edges":            "/v1/edges",
            "edges_recall":     "/v1/edges/recall",
            // Runtime algorithm endpoints — documentation-only registry
            // algorithms made computable; each signs its result and
            // returns an honest `inconclusive` when inputs aren't
            // materializable.
            "triple_consensus": "/v1/triple_consensus",
            "deforestation_alert": "/v1/deforestation_alert",
            "spi":              "/v1/spi",
            "burn_severity":    "/v1/burn_severity",
            "rice_ch4":         "/v1/rice_ch4",
            "verify_receipt":   "/v1/verify_receipt",
            "stream":           "/v1/stream",
            "corpus_state_stats":"/v1/corpus_state_stats",
            "benchmark":        "/v1/benchmark",
            "benchmark_grade":  "/v1/benchmark/grade",
        },
        // Honest declaration of which non-JSON surfaces exist and which
        // protocol channels actually expose them. The infrastructure
        // pre-dates wide MCP image-block support, so today: SVG/GeoJSON
        // are reachable via REST but get text-wrapped by MCP. Documented
        // here so agents discover the gap rather than assuming emem
        // doesn't ship multimodal at all.
        "multimodal_surfaces": {
            "_status_summary": "REST DELIVERS images (image/svg+xml + image/png) and geo+json today. MCP delivers the coverage map as a native EmbeddedResource via `emem_coverage_map`, per-cell true-colour Sentinel-2 thumbnails as native ImageContent via `emem_cell_scene_rgb`, and cell polygons as native EmbeddedResource (geo+json) via `emem_cell_geojson`. INGESTION is JSON/CBOR only — no image upload or binary-vector-as-payload endpoint yet.",
            "deliver": {
                "coverage_map_svg": {
                    "url": "/v1/coverage_map.svg",
                    "mime": "image/svg+xml",
                    "wired_via": "REST + MCP",
                    "mcp_tool": "emem_coverage_map",
                    "mcp_content_block": "EmbeddedResource (text resource, mimeType image/svg+xml) + a text summary block",
                    "agent_use":  "Multimodal MCP agents call `emem_coverage_map` and receive a native EmbeddedResource block. Plain REST callers GET /v1/coverage_map.svg and receive the bare 1440×720 Plate-Carrée SVG. Both paths share the same renderer."
                },
                "cell_geojson": {
                    "url_template": "/v1/cells/{cell64}/geojson",
                    "mime": "application/geo+json",
                    "wired_via": "REST + MCP",
                    "mcp_tool": "emem_cell_geojson",
                    "mcp_content_block": "EmbeddedResource (text resource, mimeType application/geo+json) + a text summary block",
                    "agent_use":  "Polygon (4-vertex rectangle on the active ~10 m square cell64 grid; the spec target is a 3.4 m H3 hex but that grid is not yet active — surface this in the receipt's caveats) + bbox / centre lat,lng / neighbours. Drop straight into Mapbox/Leaflet/Deck.gl/QGIS without a GIS pipeline."
                },
                "cell_scene_rgb": {
                    "url_template": "/v1/cells/{cell64}/scene.png?max_cloud=20",
                    "mime": "image/png",
                    "wired_via": "REST + MCP",
                    "mcp_tool": "emem_cell_scene_rgb",
                    "mcp_content_block": "ImageContent (base64 PNG, mimeType image/png) + a text summary block with the STAC item id / capture time / stretch values",
                    "agent_use":  "True-colour Sentinel-2 L2A thumbnail centred on the cell, 256×256 px (~2.56 km × ~2.56 km at S2's 10 m native). Auto-picks the latest scene with `eo:cloud_cover < max_cloud` (default 20 %, override via query/arg). Pure-Rust pipeline — STAC search + HTTPS-Range COG reads + 2-98 percentile stretch + PNG encode. The STAC item id is emitted in `x-emem-scene-item-id` header (REST) and structuredContent (MCP) so the receipt is reproducible."
                },
                "cell_recall_geojson": {
                    "url_template": "/v1/cells/{cell64}/recall.geojson?bands={bands}",
                    "mime": "application/geo+json",
                    "wired_via": "REST",
                    "mcp_wrapped_as": "text",
                    "agent_use":  "Polygon properties carry every fact value the responder has at the cell — one call to render a styled choropleth."
                },
                "embedding_vectors": {
                    "transport": "JSON arrays inside Fact.value",
                    "wired_via": "REST + MCP",
                    "agent_use":  "Geotessera 128-D and multi_year 1024-D vectors travel as JSON-encoded float arrays inside the standard recall envelope (decoded from upstream int8+scale). There is no separate binary / Arrow / msgpack vector channel today."
                }
            },
            "ingest": {
                "_state": "no image / vector ingestion path is wired today",
                "attestations": {
                    "url": "/v1/attest_cbor",
                    "mime": "application/cbor",
                    "carries": "PrimaryFact / DerivativeFact / Absence as canonical CBOR — structured fact data, NOT image bytes. Submit ed25519-signed batches to grow the corpus."
                },
                "image_input_for_similarity": {
                    "status": "not_wired",
                    "note":   "There is no /v1/find_similar_image (or equivalent multipart upload) for 'find places that look like this satellite preview'. Workaround today: have the agent map the image to a known cell64 (e.g. by user-supplied location), then /v1/find_similar over `geotessera`."
                },
                "vector_payload_input": {
                    "status": "supported_via_inline_literal",
                    "note":   "/v1/find_similar accepts `key: \"inline:[v0,v1,...]\"` — a JSON-array literal. There is no binary fp16 ingestion path."
                }
            },
            "what_to_build_next": [
                "MCP `emem_coverage_map` tool that returns the SVG as a `resource` content block with mime + text — so multimodal MCP agents see the image natively.",
                "Server-side SVG → PNG raster (resvg crate) so Anthropic / OpenAI image-input clients can ingest the coverage map.",
                "/v1/find_similar_image — multipart upload → geotessera lookup via a small image encoder (Tessera v1 has a published encoder).",
                "Binary vector channel: application/octet-stream fp16 for k-NN payloads (saves ~6× over JSON arrays for the 1024-D multi_year vector)."
            ]
        },
        // Curated signposts grouped by use-case so agents skimming the
        // card can see at a glance which family of question maps to
        // which band(s). Only WIRED materializers appear here — empty
        // groups are omitted rather than stubbed. For the canonical
        // per-band roster (with upstream URLs and absence semantics),
        // call `emem_materializers`; for live counts and freshness
        // call `emem_coverage_matrix`.
        "live_bands": {
            "vegetation_fast":      ["indices.ndvi","indices.evi","indices.savi","indices.ndmi"],
            "vegetation_medium":    ["modis.ndvi_mean"],
            "water_history_long":   ["surface_water.recurrence"],
            "water_event_window":   ["indices.ndwi","indices.mndwi"],
            "fire_burn_scar":       ["indices.nbr"],
            "soil_bare":            ["indices.bsi"],
            "built_up":             ["indices.ndbi","overture.buildings.count","overture.places.count","overture.transportation.road_length_m"],
            "weather_15min":        ["weather.temperature_2m","weather.cloud_cover","weather.precipitation_mm","weather.wind_speed_10m"],
            "elevation_global":     ["gmrt.topobathy_mean"],
            "elevation_land_only":  ["copdem30m.elevation_mean"],
            "optical_raw":          ["s2.B02","s2.B03","s2.B04","s2.B08","s2.B11","s2.B12"],
            "scene_classification": ["s2.scl"],
            "foundation_embedding": ["geotessera","geotessera.multi_year","geotessera.bin128"],
        },
        "live_bands_discovery_hint": "live_bands is a curated subset; call `emem_materializers` for the full registry with upstream URLs, licenses, and value-kind (primary | absence | primary_or_absence). Call `emem_coverage_matrix` for per-band facts_count and last-attested timestamps.",
        "runtime": {
            "language":       "Rust",
            "no_python_at_request_path": true,
            "cog_reader":     "pure-Rust HTTPS-range TIFF/IFD parser + Deflate + Predictor 2 (no GDAL, no rasterio)",
            "weather_source": "MET Norway api.met.no (no API key, no per-IP rate limit)",
            "stac_search":    "Element84 earth-search (anonymous; AWS Open Data backed)",
            "gateway_timeout_secs":      timeout_seconds(),
            "materializer_timeout_secs": materializer_timeout_secs(),
            "client_timeout_advice":     "Set your HTTP client read timeout to gateway_timeout_secs + 5 s. /v1/ask on a cold cell can fan out 8–24 parallel materialisations whose worst-case is bounded by materializer_timeout_secs; /v1/recall and /v1/locate complete in <2 s when warm. If you need a hard upper bound, request `cell` + a single concrete `band` to skip the temporal_recipe expansion.",
        },
        // How to make an answer portable across sessions, agents, and
        // audits. A fact CID is content-addressed and a receipt is signed,
        // so a citation verifies offline against the responder pubkey —
        // no need to re-fetch or trust the relaying agent.
        "cite_this_fact": {
            "single_fact": "emem_memory_token (REST POST /v1/memory_token) → `memt:<cell64>:<fact_cid>`. Hand that string to another agent / log it in an audit.",
            "many_facts":  "emem_memory_bundle (REST POST /v1/memory_bundle) → `memb:<bundle_cid>`. One signed handle citing N (cell, band, vintage) facts.",
            "resolve":     "emem_memory_token_resolve / emem_memory_bundle_resolve dereference the handle back to the signed body on any responder that holds it.",
            "verify_offline": "Paste the receipt at /verify (in-browser ed25519, no server trust) or call emem_verify_receipt (POST /v1/verify_receipt) for a server-side check. Either way the responder pubkey is the validator."
        },
        // The connectivity layer (v0.0.9): facts can LINK to each other
        // through typed, time-bounded edges, and the corpus can EVOLVE by
        // turning multi-attester disagreement into recorded edges + a
        // non-destructive contested marker. Both are append-only and
        // signed — a memory that improves never costs you the audit trail.
        "connect_and_evolve": {
            "edges": {
                "what":   "EdgeFact(subj, pred, obj, valid_from, valid_to) — a signed, bi-temporal link between two fact CIDs (e.g. disagrees_with, supersedes, observed_at).",
                "recall": "emem_edges_recall (POST /v1/edges/recall): the typed connections of a fact as of a point in time. Pass as_of_tslot so supersession keeps the newest edge per object.",
                "write":  "POST /v1/edges: a signed Attestation whose edges[] fold into the merkle root.",
                "attach": "Add include:[\"edges\"] to /v1/recall to ride a fact's edges back in the same call (CIDs thread into the receipt signature)."
            },
            "contradictions": {
                "scan": "emem_memory_contradictions (GET/POST /v1/memory_contradictions): where two+ attesters signed disagreeing values at the same (cell, band, tslot), with a per-band-kind severity score — instead of silently picking one."
            },
            "refinement_loop": {
                "opt_in_env": "EMEM_REFINEMENT_ENABLED",
                "what":       "A scheduled, non-destructive pass that turns scored contradictions into signed `disagrees_with` edges between the disputed fact CIDs and a `emem.fact_contested` marker on the contested fact. Originals are never deleted.",
                "see":        "POST /v1/edges/recall on a disputed subject CID to read the emitted edge once the pass has run."
            },
            "walkthrough": "examples/connect-and-evolve.md"
        },
        "tools": tools_summary,
    }))
}

