/// Minimal HTML escape for places we already control input shape but
/// still want to be safe (band keys, place labels, deks). Three chars
/// is enough — we never embed raw user URLs in attributes here.
fn html_escape_min(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

/// Fast, dependency-free viridis approximation. Input t ∈ [0,1].
/// Fitted from the canonical viridis stops (8 control points, linear
/// interpolation between the nearest two).
#[allow(dead_code)]
fn viridis_hex(t: f64) -> String {
    const STOPS: [(f64, [u8; 3]); 8] = [
        (0.0, [68, 1, 84]),
        (0.143, [72, 35, 116]),
        (0.286, [64, 67, 135]),
        (0.429, [52, 94, 141]),
        (0.571, [41, 120, 142]),
        (0.714, [32, 144, 140]),
        (0.857, [34, 167, 132]),
        (1.0, [253, 231, 36]),
    ];
    let t = t.clamp(0.0, 1.0);
    let (mut lo, mut hi) = (&STOPS[0], &STOPS[STOPS.len() - 1]);
    for w in STOPS.windows(2) {
        if t >= w[0].0 && t <= w[1].0 {
            lo = &w[0];
            hi = &w[1];
            break;
        }
    }
    let span = (hi.0 - lo.0).max(1e-9);
    let f = (t - lo.0) / span;
    let mix = |a: u8, b: u8| -> u8 {
        ((a as f64) * (1.0 - f) + (b as f64) * f)
            .round()
            .clamp(0.0, 255.0) as u8
    };
    let r = mix(lo.1[0], hi.1[0]);
    let g = mix(lo.1[1], hi.1[1]);
    let b = mix(lo.1[2], hi.1[2]);
    format!("#{:02x}{:02x}{:02x}", r, g, b)
}

async fn boring_recall_aggregated(
    state: &AppState,
    target: ResolvedTarget,
    bands: &[String],
    tslot: Option<u64>,
    include: &std::collections::HashSet<&str>,
    max_cells: usize,
) -> Result<JsonValue, ApiError> {
    // Point query: zero behaviour change vs the legacy code path.
    let polygon = match target.polygon.as_ref() {
        None => {
            return boring_recall_at(state, target.lat, target.lng, bands, tslot).await;
        }
        Some(p) => p.clone(),
    };

    // Sanity-bound the cell list. `resolve_target` already capped to the
    // global boring ceiling, but the per-endpoint `max_cells` can be tighter
    // (e.g. SoilGrids' per-POINT JSON API has no tile prewarm, so its fan-out
    // is capped lower — see `soil_max_cells`). Record whether the cap
    // actually truncated coverage so we can disclose it honestly rather than
    // silently sampling fewer cells.
    let n_available = polygon.sample_cells.len();
    let effective_cap = max_cells.min(boring_max_cells());
    let coverage_capped = n_available > effective_cap;
    let cells: Vec<String> = polygon
        .sample_cells
        .iter()
        .take(effective_cap)
        .cloned()
        .collect();
    if cells.is_empty() {
        // No cells — fall back to the centroid so we always serve
        // something (matches /v1/recall_polygon's degenerate-bbox path).
        return boring_recall_at(state, target.lat, target.lng, bands, tslot).await;
    }

    // Polygon-bbox tile prewarm — fire ONE `cog::sample_window` per
    // static-COG band over the polygon bbox so each later per-cell
    // `sample_pixel` is a `TILE_CACHE` byte-hit + decompress instead
    // of a fresh HTTP range read. Hansen treecover / lossyear / gain,
    // JRC GFC2020, ESA CCI Biomass, ESA WorldCover, and JRC GSW
    // recurrence currently benefit; STAC-driven and per-point JSON-
    // API bands (Open-Meteo, met.no, MODIS, S2/S1) silently no-op
    // here and pay the per-cell cost they would have paid anyway.
    // Same shape `/v1/recall_polygon` and `/v1/hunt`'s
    // `fan_out_and_rank` already use. Best-effort: tile-open failures
    // do not break the per-cell path.
    if !bands.is_empty() {
        prewarm_polygon_static_cog_bands(bands, polygon.bbox).await;
    }

    // Fan out per-cell recalls in TWO phases so a cold polygon can never
    // hold the connection past the boring budget — the 2026-05-31 outage
    // was abandoned cold-materialise requests leaking CLOSE-WAIT sockets
    // until the :443 accept backlog saturated.
    //
    //   Phase 1 (cheap, every cell): a cache-only `recall`. Warm cells —
    //   all requested bands already stored — finish here with zero upstream
    //   traffic, so the common case (re-querying a known place) stays fast.
    //
    //   Phase 2 (bounded): materialise at most `boring_cold_cap()` of the
    //   still-cold cells from upstream. Cold cells beyond the cap keep their
    //   empty phase-1 result and surface as `cold_cells_skipped` — the
    //   aggregate is then honestly `partial` rather than silently sampling
    //   fewer cells (and the caller can lower n_cells, re-query to warm
    //   more, or query a specific cell for full coverage).
    type CellRecall = (String, Result<(RecallResp, Vec<JsonValue>), ApiError>);
    let bands_for_recall: Option<Vec<String>> = if bands.is_empty() {
        None
    } else {
        Some(bands.iter().map(|b| resolve_band_name(b)).collect())
    };

    let mut per_cell: Vec<(String, RecallResp)> = Vec::with_capacity(cells.len());
    let mut materialize_notes_all: Vec<JsonValue> = Vec::new();
    let mut errors: Vec<JsonValue> = Vec::new();

    // Phase 1: cache-only classification (no materialisation).
    let mut p1: tokio::task::JoinSet<(String, Result<RecallResp, ApiError>)> =
        tokio::task::JoinSet::new();
    for cell in &cells {
        let req = RecallReq {
            cell: cell.clone(),
            bands: bands_for_recall.clone(),
            tslot,
            ..Default::default()
        };
        let cell = cell.clone();
        let s = state.clone();
        p1.spawn(async move {
            let r = recall(&req, &s).await.map_err(ApiError::from);
            (cell, r)
        });
    }
    let mut cold: Vec<String> = Vec::new();
    while let Some(j) = p1.join_next().await {
        if let Ok((cell, r)) = j {
            match r {
                Ok(resp) => {
                    if cell_needs_materialize(&resp, bands_for_recall.as_deref()) {
                        cold.push(cell);
                    } else {
                        per_cell.push((cell, resp));
                    }
                }
                Err(e) => errors.push(json!({
                    "cell": cell,
                    "code": e.1.code,
                    "message": e.1.message,
                    "status": e.0.as_u16(),
                })),
            }
        }
    }

    // Phase 2: bounded materialisation of the cold cells.
    let cold_cap = boring_cold_cap();
    let cold_cells_skipped = cold.len().saturating_sub(cold_cap);
    let to_materialize: Vec<String> = cold.into_iter().take(cold_cap).collect();
    let mut p2: tokio::task::JoinSet<CellRecall> = tokio::task::JoinSet::new();
    for cell in &to_materialize {
        let req = RecallReq {
            cell: cell.clone(),
            bands: bands_for_recall.clone(),
            tslot,
            ..Default::default()
        };
        let cell = cell.clone();
        let s = state.clone();
        p2.spawn(async move {
            let r = recall_with_auto_materialize(&req, &s).await;
            (cell, r)
        });
    }
    while let Some(j) = p2.join_next().await {
        if let Ok((cell, r)) = j {
            match r {
                Ok((resp, notes)) => {
                    materialize_notes_all.extend(notes);
                    per_cell.push((cell, resp));
                }
                Err(e) => {
                    errors.push(json!({
                        "cell": cell,
                        "code": e.1.code,
                        "message": e.1.message,
                        "status": e.0.as_u16(),
                    }));
                }
            }
        }
    }

    // Group facts by band across all cells. Track per-cell fact_cid +
    // signed_at + responder so the aggregated envelope can carry the
    // citation surface ({fact_cids: [...], captured_at_range: [...]}).
    use std::collections::BTreeMap;
    #[derive(Clone)]
    #[allow(dead_code)]
    struct PerCellFact {
        cell: String,
        fact: emem_fact::Fact,
        fact_cid: Option<String>,
        signed_at: String,
    }
    let mut by_band: BTreeMap<String, Vec<PerCellFact>> = BTreeMap::new();
    let mut latest_served_at = String::new();
    for (cell, resp) in &per_cell {
        if resp.receipt.served_at > latest_served_at {
            latest_served_at = resp.receipt.served_at.clone();
        }
        for (idx, fact) in resp.facts.iter().enumerate() {
            let (band, signed_at) = match fact {
                emem_fact::Fact::Primary(p) => (p.band.clone(), p.signed_at.clone()),
                emem_fact::Fact::Absence(a) => (a.band.clone(), a.signed_at.clone()),
                _ => continue,
            };
            let fact_cid = resp.receipt.fact_cids.get(idx).map(|c| c.0.clone());
            by_band.entry(band).or_default().push(PerCellFact {
                cell: cell.clone(),
                fact: fact.clone(),
                fact_cid,
                signed_at,
            });
        }
    }

    let pubkey_b32 = data_encoding::BASE32_NOPAD
        .encode(&state.identity.pubkey.0)
        .to_lowercase();

    // Bands the caller asked for. Use this as the iteration set so
    // requested-but-empty bands surface with `n_missing == n_cells`
    // instead of vanishing silently.
    let band_iter: Vec<String> = if bands.is_empty() {
        by_band.keys().cloned().collect()
    } else {
        bands.to_vec()
    };

    let mut bands_out = serde_json::Map::new();
    // Roll-up of missingness across bands so the response root can carry
    // a `partial: true` honesty flag — agents reading aggregate stats
    // mistake an incomplete fan-out for full coverage otherwise.
    let mut total_missing: usize = 0;
    let mut total_attempts: usize = 0;
    for band in &band_iter {
        let entries = by_band.get(band).cloned().unwrap_or_default();
        let kind = band_agg_kind(band);
        let n_total = cells.len();
        let n_present = entries.len();
        let n_missing = n_total.saturating_sub(n_present);
        // Split Primary vs Absence — only Primary feeds numeric stats.
        let mut primary_values: Vec<JsonValue> = Vec::with_capacity(entries.len());
        // Parallel array of cell64 strings for every entry in `primary_values`.
        // Used by `aggregate_band` to compute the cos(lat) equal-area weight
        // per cell — see the helper in emem_codec::geo for the bias this
        // removes.
        let mut primary_cells: Vec<String> = Vec::with_capacity(entries.len());
        let mut fact_cids: Vec<String> = Vec::with_capacity(entries.len());
        let mut signed_ats: Vec<String> = Vec::with_capacity(entries.len());
        let mut absence_count = 0usize;
        let mut sample_unit: Option<String> = None;
        let mut sample_source: Option<String> = None;
        // value_per_cell carries a tuple (cell64, lat, lng, value-or-null,
        // kind: "primary"|"absence") per sample cell so an agent can plot
        // its own histogram, identify outliers, render its own choropleth,
        // or persist for downstream analysis without re-fetching.
        let mut value_per_cell: Vec<JsonValue> = Vec::with_capacity(entries.len());
        for e in &entries {
            let (lat_c, lng_c) = match emem_codec::latlng_from_cell64(&e.cell) {
                Ok(ll) => (ll.lat_deg, ll.lng_deg),
                Err(_) => (f64::NAN, f64::NAN),
            };
            let (val_json, kind_str): (JsonValue, &str) = match &e.fact {
                emem_fact::Fact::Primary(p) => (ciborium_to_json(&p.value), "primary"),
                emem_fact::Fact::Absence(_) => (JsonValue::Null, "absence"),
                _ => (JsonValue::Null, "other"),
            };
            value_per_cell.push(json!({
                "cell":  e.cell,
                "lat":   lat_c,
                "lng":   lng_c,
                "value": val_json,
                "kind":  kind_str,
                "fact_cid": e.fact_cid,
            }));
            match &e.fact {
                emem_fact::Fact::Primary(p) => {
                    primary_values.push(ciborium_to_json(&p.value));
                    primary_cells.push(e.cell.clone());
                    if sample_unit.is_none() {
                        sample_unit = p.unit.clone();
                    }
                    if sample_source.is_none() {
                        sample_source = p.sources.first().map(|s| s.scheme.clone());
                    }
                }
                emem_fact::Fact::Absence(_) => absence_count += 1,
                _ => {}
            }
            if let Some(c) = &e.fact_cid {
                fact_cids.push(c.clone());
            }
            signed_ats.push(e.signed_at.clone());
        }
        let n_missing_eff = n_missing + absence_count;
        total_missing += n_missing_eff;
        total_attempts += n_total;

        let (aggregator, headline, stats, kind_str, extra) = aggregate_band(
            kind,
            &primary_cells,
            &primary_values,
            n_present,
            n_missing_eff,
        );

        let captured_at_range = if signed_ats.is_empty() {
            JsonValue::Null
        } else {
            let mut s = signed_ats.clone();
            s.sort();
            json!([s.first(), s.last()])
        };

        // Decorate value_per_cell with value_decoded for categorical bands
        // so the LLM doesn't have to consult class_decode at the band level
        // for every cell.
        if class_decode_for(band).is_some() {
            for entry in value_per_cell.iter_mut() {
                if let Some(map) = entry.as_object_mut() {
                    if let Some(v) = map.get("value").cloned() {
                        if let Some(label) = decode_class_value(band, &v) {
                            map.insert("value_decoded".into(), json!(label));
                        }
                    }
                }
            }
        }
        // Decode the headline value when categorical (mode → label).
        let headline_decoded = decode_class_value(band, &headline);
        let mut block = json!({
            "aggregator":            aggregator,
            "value":                 headline,
            "stats":                 stats,
            "kind":                  kind_str,
            "fact_cids":             fact_cids,
            "data_resolution_m":     band_input_resolution_m(band),
            "cell_dedupe_m":         RESOLUTION_M_GRID,
            "n":                     n_present,
            "n_missing":             n_missing_eff,
            "unit":                  sample_unit,
            "source":                sample_source,
            "captured_at_range":     captured_at_range,
            "responder_pubkey_b32":  pubkey_b32,
        });
        // pct_area_over reducer (D1): cos(lat)-weighted fraction of sampled
        // cells whose numeric value exceeds the caller's threshold (same
        // area weighting the mean uses). "% of plot with NDVI < 0.3" is
        // `1 - pct_area_over` at threshold 0.3; "% over 30 °C" is
        // pct_area_over at 30. Numeric values only; skipped otherwise.
        if let Some(thr) = target.threshold {
            let mut over_w = 0.0f64;
            let mut total_w = 0.0f64;
            for (v, c) in primary_values.iter().zip(primary_cells.iter()) {
                if let Some(x) = v.as_f64() {
                    let w = emem_codec::latlng_from_cell64(c)
                        .map(|ll| ll.lat_deg.to_radians().cos().abs().max(1e-6))
                        .unwrap_or(1.0);
                    total_w += w;
                    if x > thr {
                        over_w += w;
                    }
                }
            }
            if total_w > 0.0 {
                if let Some(map) = block.as_object_mut() {
                    map.insert("pct_area_over".into(), json!(over_w / total_w));
                    map.insert("pct_area_over_threshold".into(), json!(thr));
                }
            }
        }
        if let Some(map) = block.as_object_mut() {
            if include.contains("value_per_cell") {
                map.insert(
                    "value_per_cell".into(),
                    JsonValue::Array(value_per_cell.clone()),
                );
            } else {
                map.insert("value_per_cell_count".into(), json!(value_per_cell.len()));
            }
            if include.contains("geojson") {
                map.insert(
                    "geojson".into(),
                    cells_geojson_with_values(&value_per_cell, band),
                );
            }
        }
        if let Some(map) = block.as_object_mut() {
            for (k, v) in extra {
                // For categorical bands, transform `class_distribution`
                // from {"50":0.245} to {"50":{"label":"Built-up","share":0.245}}
                // so the LLM doesn't have to cross-reference class IDs
                // with the band metadata to render a histogram. Values
                // are equal-area shares (Σ = 1.0) under the cos(lat)
                // weighting introduced in `aggregate_band`.
                if k == "class_distribution" && class_decode_for(band).is_some() {
                    if let Some(obj) = v.as_object() {
                        let decoded: serde_json::Map<String, JsonValue> = obj
                            .iter()
                            .map(|(class_id_str, share)| {
                                let label = class_id_str
                                    .parse::<i64>()
                                    .ok()
                                    .and_then(|id| decode_class_value(band, &json!(id)))
                                    .unwrap_or_else(|| "unknown".to_string());
                                (
                                    class_id_str.clone(),
                                    json!({"label": label, "share": share}),
                                )
                            })
                            .collect();
                        map.insert(k, JsonValue::Object(decoded));
                        continue;
                    }
                }
                map.insert(k, v);
            }
            if let Some(label) = headline_decoded {
                map.insert("value_decoded".into(), json!(label));
            }
            let meta = band_metadata_for_response(band);
            if !meta.is_null() {
                map.insert("band_metadata".into(), meta);
            }
        }
        bands_out.insert(band.clone(), block);
    }

    // Area in km², same midlat formula /v1/recall_polygon uses.
    let area_km2 = {
        let mid_lat = (polygon.bbox.0 + polygon.bbox.1) / 2.0;
        let lat_km = (polygon.bbox.1 - polygon.bbox.0) * 111.0;
        let lng_km = (polygon.bbox.3 - polygon.bbox.2) * 111.0 * mid_lat.to_radians().cos().abs();
        (lat_km * lng_km).max(0.0)
    };
    // Per-cell scene/geojson URL pointers — agents can render their own
    // grid in a chat / report without re-querying. Overlay URL is a
    // server-side value-painted SVG of the polygon for the first band
    // (single-band hot path); multi-band callers can swap `?band=` to
    // get per-band overlays.
    let scene_thumbs: Vec<JsonValue> = cells
        .iter()
        .map(|c| {
            let (lat_c, lng_c) = match emem_codec::latlng_from_cell64(c) {
                Ok(ll) => (ll.lat_deg, ll.lng_deg),
                Err(_) => (f64::NAN, f64::NAN),
            };
            json!({
                "cell":         c,
                "lat":          lat_c,
                "lng":          lng_c,
                "scene_png":    format!("/v1/cells/{}/scene.png", c),
                "scene_rgb":    format!("/v1/cells/{}/scene.rgb", c),
                "geojson":      format!("/v1/cells/{}/geojson",   c),
                "info":         format!("/v1/cells/{}/info",      c),
            })
        })
        .collect();
    let overlay_band = bands.first().cloned().unwrap_or_default();
    let overlay_url = if !overlay_band.is_empty() {
        let label_for_url = polygon
            .place_label
            .as_deref()
            .map(|s| s.split(',').next().unwrap_or(s).trim().to_string())
            .unwrap_or_default();
        if label_for_url.is_empty() {
            json!(null)
        } else {
            // Percent-encode just spaces — full encoding via urlencoding
            // crate would pull in another dep; simple replace covers the
            // overwhelming majority of place labels.
            let encoded = label_for_url.replace(' ', "%20");
            json!(format!(
                "/v1/places/scene_overlay.svg?place={encoded}&band={overlay_band}&n_cells={}",
                cells.len()
            ))
        }
    } else {
        json!(null)
    };
    let place_label = polygon.place_label.clone();
    let mut polygon_block = json!({
        "bbox": {
            "min_lat": polygon.bbox.0, "max_lat": polygon.bbox.1,
            "min_lng": polygon.bbox.2, "max_lng": polygon.bbox.3,
        },
        "area_km2":         area_km2,
        "sample_cells":     cells.clone(),
        "n_sample_cells":   cells.len(),
        "source":           polygon.source,
        "scene_overlay_url": overlay_url,
    });
    if let Some(map) = polygon_block.as_object_mut() {
        if include.contains("scene_thumbs") {
            map.insert("scene_thumbs".into(), JsonValue::Array(scene_thumbs));
        } else {
            map.insert("scene_thumbs_count".into(), json!(scene_thumbs.len()));
        }
        if include.contains("geojson") {
            map.insert(
                "geojson".into(),
                polygon_outline_geojson(
                    &polygon.bbox,
                    place_label.as_deref(),
                    area_km2,
                    cells.len(),
                ),
            );
        }
    }

    let single = bands.len() == 1;
    let mut envelope = if single {
        // Backward-compat: hoist the single band's headline so existing
        // clients reading `body.value` keep working. Polygon block +
        // stats are layered alongside.
        let band = &bands[0];
        let band_block = bands_out
            .get(band)
            .cloned()
            .unwrap_or(JsonValue::Object(Default::default()));
        let mut env = band_block;
        if let Some(map) = env.as_object_mut() {
            map.insert("band".into(), json!(band));
        }
        env
    } else {
        json!({
            "bands":                JsonValue::Object(bands_out),
            "responder_pubkey_b32": pubkey_b32.clone(),
            "cell_dedupe_m":        RESOLUTION_M_GRID,
        })
    };

    if let Some(map) = envelope.as_object_mut() {
        map.insert("lat".into(), json!(target.lat));
        map.insert("lon".into(), json!(target.lng));
        map.insert("via".into(), json!(target.via));
        map.insert("polygon".into(), polygon_block);
        if let Some(ref label) = place_label {
            map.insert("place_label".into(), json!(label));
        }
        map.insert("n_cells_queried".into(), json!(cells.len()));
        map.insert("n_cells_returned".into(), json!(per_cell.len()));
        map.insert("served_at".into(), json!(latest_served_at));
        if !materialize_notes_all.is_empty() {
            map.insert(
                "materialize_notes".into(),
                JsonValue::Array(materialize_notes_all),
            );
        }
        if !errors.is_empty() {
            map.insert("cell_errors".into(), JsonValue::Array(errors));
        }
        // Honesty: an aggregated response that summarised over a partial
        // fan-out should not look identical to one with full coverage.
        // `partial: true` flips when ANY band has an unfilled cell across
        // the polygon sample (cell error, materializer skip, or signed
        // Absence). `coverage_fraction` quantifies how close to complete.
        let partial = total_missing > 0;
        let coverage_fraction = if total_attempts > 0 {
            (total_attempts - total_missing) as f64 / total_attempts as f64
        } else {
            0.0
        };
        map.insert("partial".into(), json!(partial));
        map.insert("coverage_fraction".into(), json!(coverage_fraction));
        map.insert("is_exhaustive".into(), json!(false));
        // Honesty: when the cold-cell cap stopped us materialising every
        // cold cell this request (the latency guard added after the
        // 2026-05-31 outage), say so explicitly. The skipped cells are
        // already counted as missing above (so `partial` is true); this
        // note tells the agent WHY — capped for latency, not empty-place.
        if cold_cells_skipped > 0 {
            map.insert("cold_cells_skipped".into(), json!(cold_cells_skipped));
            map.insert(
                "cold_cells_skipped_note".into(),
                json!(format!(
                    "{cold_cells_skipped} cold cell(s) were not materialised this request to \
                     stay within the latency budget (EMEM_BORING_COLD_CAP={cold_cap}). They are \
                     counted as missing in the aggregate, so `partial` is true. Re-query to warm \
                     more, lower n_cells, or query a specific cell for guaranteed coverage."
                )),
            );
        }
        // Honesty: when a per-endpoint fan-out cap truncated the polygon
        // sample (e.g. SoilGrids per-POINT API), say so explicitly so the
        // caller doesn't read the aggregate as covering the whole feature.
        if coverage_capped {
            map.insert("coverage_capped".into(), json!(true));
            map.insert(
                "coverage_capped_note".into(),
                json!(format!(
                    "Fan-out was capped at {} of {} candidate cells for this feature to \
                     bound latency (this source is queried per-point with no tileable \
                     prewarm). The aggregate summarises the sampled cells only; raise the \
                     cap via env or query a smaller area / specific cell for full coverage.",
                    cells.len(),
                    n_available
                )),
            );
        }
        let bbox = polygon.bbox;
        map.insert(
            "next".into(),
            json!({
                "raw_per_cell":     format!("POST /v1/recall_polygon {{polygon_bbox:{{min_lat:{},max_lat:{},min_lng:{},max_lng:{}}}, bands:[…]}}", bbox.0, bbox.1, bbox.2, bbox.3),
                "deep_recall":      "POST /v1/recall {cell:'<cell64>', bands:[…]}",
                "fact_dereference": "GET /v1/facts/{fact_cid}",
                "verify_offline":   "POST /v1/verify_receipt {receipt}",
            }),
        );
        map.insert(
            "place_resolution".into(),
            json!({
                "is_high_confidence": target.is_high_confidence,
                "confidence_reason":  target.confidence_reason,
                "area_km2":           area_km2,
                "input_query":        target.input_place_query,
                "resolved_label":     place_label,
                "via":                target.via,
            }),
        );
        if !target.is_high_confidence {
            map.insert(
                "warning".into(),
                json!(format!(
                    "Low-confidence geocode: '{}' resolved to '{}' ({:.0} km²). \
                 The result may cover a much larger area than intended. \
                 Re-query with a more specific place name or pass explicit lat/lng.",
                    target.input_place_query.as_deref().unwrap_or("?"),
                    place_label.as_deref().unwrap_or("unknown"),
                    area_km2,
                )),
            );
        }
        // Area-vs-intent guard: flag when a query implies a small feature
        // but the geocoder resolved to a region-scale polygon.
        const SMALL_FEATURE_HINTS: &[&str] = &[
            "village",
            "town",
            "neighbourhood",
            "neighborhood",
            "nagar",
            "colony",
            "mohalla",
            "ward",
            "street",
            "lane",
            "gali",
            "chowk",
            "para",
            "tola",
            "bastee",
            "basti",
            "hamlet",
        ];
        if let Some(ref q) = target.input_place_query {
            let q_lower = q.to_lowercase();
            let expects_small = SMALL_FEATURE_HINTS.iter().any(|h| q_lower.contains(h));
            if expects_small && area_km2 > 10_000.0 {
                map.insert(
                    "warning".into(),
                    json!(format!(
                        "Query '{}' mentions a small feature but resolved to {:.0} km² \
                     ('{}'). The geocoder likely expanded to a parent region. \
                     Pass a more specific name or explicit coordinates.",
                        q,
                        area_km2,
                        place_label.as_deref().unwrap_or("unknown"),
                    )),
                );
            }
        }
        map.insert(
            "agent_hint".into(),
            json!("Polygon aggregation: when a place name resolves to a feature with extent (airport, park, lake, region), the boring endpoint fans out to `polygon.sample_cells` and returns mean/median/min/max/std per band (mode + class distribution for categorical bands like esa_worldcover.lc_2021). Pass `n_cells:1` to force a single-cell read at the centroid; use POST /v1/recall_polygon for raw per-cell facts."),
        );
    }
    Ok(envelope)
}

/// Numeric / categorical / vector / multidim aggregator. Returns
/// `(aggregator_name, headline_value, stats_block, kind_string, extra_kv)`.
/// Extra fields (e.g. `class_distribution`) are merged into the band
/// block; keeps the caller flat.
///
/// `cells` is a parallel array to `values` — cell64 string per primary
/// fact. Used by NumericScalar and Categorical to compute the cos(lat)
/// equal-area weight: a 60° N cell covers ~50% the m² of an equator
/// cell, so weighting every cell equally (the old `sum / n` math) biases
/// the headline mean and the class-share distribution toward polar
/// cells. Order statistics (median/min/max) don't change under
/// reweighting and stay count-based.
fn aggregate_band(
    kind: AggKind,
    cells: &[String],
    values: &[JsonValue],
    n_present: usize,
    n_missing_eff: usize,
) -> (
    &'static str,
    JsonValue,
    JsonValue,
    &'static str,
    Vec<(String, JsonValue)>,
) {
    let mut extra: Vec<(String, JsonValue)> = Vec::new();
    match kind {
        AggKind::NumericScalar => {
            // Collect (weight, value) pairs so the cos(lat) reweighting
            // can be applied to mean / variance below. Order statistics
            // (median / min / max) are computed unweighted because they
            // are invariant under monotone reweighting of samples.
            let mut weighted: Vec<(f64, f64)> = Vec::with_capacity(values.len());
            for (i, v) in values.iter().enumerate() {
                let Some(x) = v.as_f64() else { continue };
                if !x.is_finite() {
                    continue;
                }
                // Cell may be missing if a future caller threads
                // fewer cells than values; fall back to weight 1.0.
                let w = cells
                    .get(i)
                    .map(|c| emem_codec::equal_area_weight_for(c))
                    .unwrap_or(1.0);
                weighted.push((w, x));
            }
            if weighted.is_empty() {
                return (
                    "mean",
                    JsonValue::Null,
                    json!({
                        "mean":  null, "median": null, "min": null, "max": null,
                        "std":   null, "n": n_present, "n_missing": n_missing_eff,
                        "cos_lat_weighting_applied": true,
                    }),
                    "numeric_scalar",
                    extra,
                );
            }
            // cos(lat) equal-area weighting: the sample cells are
            // uniformly spaced in lat/lng degrees, so polar cells
            // represent less real-world area per sample. Weighting by
            // cos(centroid lat) removes the up-to-21% high-latitude
            // bias on a 60°S–60°N polygon. See
            // `emem_codec::equal_area_weight_for`.
            let sum_w: f64 = weighted.iter().map(|(w, _)| *w).sum();
            // sum_w is positive in practice (cos clamps to ≥0, and at
            // least one finite sample exists). If it drops to 0 from a
            // pole-only fan-out, degrade to unweighted rather than
            // produce NaN — the caller still gets a usable headline.
            let (mean, var) = if sum_w > 0.0 {
                let m = weighted.iter().map(|(w, x)| w * x).sum::<f64>() / sum_w;
                let v = weighted
                    .iter()
                    .map(|(w, x)| w * (x - m).powi(2))
                    .sum::<f64>()
                    / sum_w;
                (m, v)
            } else {
                let n = weighted.len() as f64;
                let m = weighted.iter().map(|(_, x)| *x).sum::<f64>() / n;
                let v = weighted.iter().map(|(_, x)| (x - m).powi(2)).sum::<f64>() / n;
                (m, v)
            };
            let std = var.sqrt();
            // Unweighted order statistics — see comment above.
            let mut sorted: Vec<f64> = weighted.iter().map(|(_, x)| *x).collect();
            sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            let median = if sorted.len() % 2 == 1 {
                sorted[sorted.len() / 2]
            } else {
                (sorted[sorted.len() / 2 - 1] + sorted[sorted.len() / 2]) / 2.0
            };
            let min = *sorted.first().unwrap();
            let max = *sorted.last().unwrap();
            (
                "mean",
                json!(mean),
                json!({
                    "mean":  mean, "median": median, "min": min, "max": max,
                    "std":   std, "n": sorted.len(), "n_missing": n_missing_eff,
                    "cos_lat_weighting_applied": true,
                }),
                "numeric_scalar",
                extra,
            )
        }
        AggKind::Categorical => {
            use std::collections::BTreeMap;
            // hist_count: raw cell counts per class (used for `n` and
            // mode). hist_weight: cos(lat)-weighted area per class
            // (used for class_distribution). Mode stays count-based so
            // the headline class doesn't flip on a single polar pixel;
            // class_distribution becomes an equal-area share so an
            // agent computing % land-cover doesn't overstate polar
            // classes (snow/ice/tundra) on a 60°S–60°N fan-out.
            let mut hist_count: BTreeMap<i64, usize> = BTreeMap::new();
            let mut hist_weight: BTreeMap<i64, f64> = BTreeMap::new();
            for (i, v) in values.iter().enumerate() {
                let class = if let Some(i) = v.as_i64() {
                    Some(i)
                } else {
                    v.as_f64().map(|f| f as i64)
                };
                let Some(class) = class else { continue };
                *hist_count.entry(class).or_insert(0) += 1;
                let w = cells
                    .get(i)
                    .map(|c| emem_codec::equal_area_weight_for(c))
                    .unwrap_or(1.0);
                *hist_weight.entry(class).or_insert(0.0) += w;
            }
            let mode = hist_count.iter().max_by_key(|(_, c)| **c).map(|(k, _)| *k);
            // Normalise the weighted histogram so the distribution sums
            // to 1.0 — share-of-area per class, not raw weight. Falls
            // back to count-share if total weight is 0 (pole-only fan-out).
            let total_w: f64 = hist_weight.values().sum();
            let dist: serde_json::Map<String, JsonValue> = if total_w > 0.0 {
                hist_weight
                    .iter()
                    .map(|(k, w)| (k.to_string(), json!(w / total_w)))
                    .collect()
            } else {
                let total_c: usize = hist_count.values().sum();
                hist_count
                    .iter()
                    .map(|(k, c)| (k.to_string(), json!(*c as f64 / total_c.max(1) as f64)))
                    .collect()
            };
            extra.push(("class_distribution".into(), JsonValue::Object(dist)));
            extra.push(("cos_lat_weighting_applied".into(), json!(true)));
            let total: usize = hist_count.values().sum();
            (
                "mode",
                mode.map(|m| json!(m)).unwrap_or(JsonValue::Null),
                json!({
                    "mode":      mode,
                    "n_classes": hist_count.len(),
                    "n":         total,
                    "n_missing": n_missing_eff,
                }),
                "categorical",
                extra,
            )
        }
        AggKind::VectorEmbedding => {
            // Coerce each value to Vec<f64>; skip non-arrays.
            let mut vecs: Vec<Vec<f64>> = Vec::new();
            for v in values {
                if let Some(arr) = v.as_array() {
                    let row: Vec<f64> = arr.iter().filter_map(|x| x.as_f64()).collect();
                    if !row.is_empty() {
                        vecs.push(row);
                    }
                }
            }
            if vecs.is_empty() {
                // First value (likely fp16/bytes); embedding aggregation
                // not applicable — surface a note rather than guessing.
                return (
                    "first",
                    values.first().cloned().unwrap_or(JsonValue::Null),
                    json!({
                        "n":          n_present,
                        "n_missing":  n_missing_eff,
                        "note":       "embedding aggregation not applicable for this band (per-cell value isn't a JSON array of floats)",
                    }),
                    "vector_embedding",
                    extra,
                );
            }
            let dim = vecs.iter().map(|v| v.len()).min().unwrap_or(0);
            let n = vecs.len() as f64;
            let mut centroid = vec![0.0f64; dim];
            for v in &vecs {
                for (i, x) in v.iter().take(dim).enumerate() {
                    centroid[i] += x;
                }
            }
            for x in &mut centroid {
                *x /= n;
            }
            (
                "vector_centroid",
                json!(centroid),
                json!({
                    "dim":        dim,
                    "n":          vecs.len(),
                    "n_missing":  n_missing_eff,
                }),
                "vector_embedding",
                extra,
            )
        }
        AggKind::Multidim => {
            // Per-component mean/median/min/max for an array-of-floats band.
            let mut rows: Vec<Vec<f64>> = Vec::new();
            for v in values {
                if let Some(arr) = v.as_array() {
                    let row: Vec<f64> = arr.iter().filter_map(|x| x.as_f64()).collect();
                    if !row.is_empty() {
                        rows.push(row);
                    }
                }
            }
            if rows.is_empty() {
                return (
                    "first",
                    values.first().cloned().unwrap_or(JsonValue::Null),
                    json!({
                        "n":          n_present,
                        "n_missing":  n_missing_eff,
                        "note":       "multidim aggregation not applicable for this band (per-cell value isn't an array of floats)",
                    }),
                    "multidim",
                    extra,
                );
            }
            let dim = rows.iter().map(|r| r.len()).min().unwrap_or(0);
            let mut components: Vec<JsonValue> = Vec::with_capacity(dim);
            let mut means: Vec<f64> = Vec::with_capacity(dim);
            for d in 0..dim {
                let col: Vec<f64> = rows
                    .iter()
                    .filter_map(|r| r.get(d).copied().filter(|x| x.is_finite()))
                    .collect();
                if col.is_empty() {
                    components.push(JsonValue::Null);
                    means.push(0.0);
                    continue;
                }
                let n_d = col.len() as f64;
                let mean = col.iter().sum::<f64>() / n_d;
                let mut sorted = col.clone();
                sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                let median = if sorted.len() % 2 == 1 {
                    sorted[sorted.len() / 2]
                } else {
                    (sorted[sorted.len() / 2 - 1] + sorted[sorted.len() / 2]) / 2.0
                };
                let min = *sorted.first().unwrap();
                let max = *sorted.last().unwrap();
                components.push(json!({
                    "mean": mean, "median": median, "min": min, "max": max,
                    "n": col.len(),
                }));
                means.push(mean);
            }
            (
                "per_component_mean",
                json!(means),
                json!({
                    "components": components,
                    "n":          rows.len(),
                    "n_missing":  n_missing_eff,
                    "dim":        dim,
                }),
                "multidim",
                extra,
            )
        }
    }
}

/// `GET /v1/at?lat=&lon=&band=…&tslot=…`
/// Generic single-or-multi-band lat/lng lookup. CSV-or-repeated
/// `band` accepted via the `bands` field too.
async fn get_v1_at(
    State(s): State<AppState>,
    Query(q): Query<LatLngQ>,
) -> Result<Json<JsonValue>, ApiError> {
    // Multi-band /v1/at defaults to point (n_cells=1) to keep cost
    // bounded — multi-band × multi-cell explodes the upstream fetch
    // count. Caller can opt in with `n_cells: <n>`.
    let target = q.resolve_target(1).await?;
    let mut bands: Vec<String> = Vec::new();
    if let Some(b) = &q.band {
        bands.push(b.clone());
    }
    if let Some(csv) = &q.bands {
        for tok in csv.split(',').map(|s| s.trim()).filter(|s| !s.is_empty()) {
            if !bands.iter().any(|b| b == tok) {
                bands.push(tok.to_string());
            }
        }
    }
    // Default band-set for /v1/at when neither `band` nor `bands` is
    // supplied — gives an agent that doesn't know what to ask for a
    // useful at-this-point bundle. Mirrors the documented MCP
    // `emem_locate` follow-up suggestions.
    if bands.is_empty() {
        for b in DEFAULT_AT_BANDS {
            bands.push((*b).to_string());
        }
    }
    let inc_set: std::collections::HashSet<&str> = q
        .include
        .as_ref()
        .map(|v| v.iter().map(|s| s.as_str()).collect())
        .unwrap_or_default();
    let tag = format!("at bands {bands:?}");
    let v = with_boring_budget(
        &tag,
        boring_recall_aggregated(&s, target, &bands, q.tslot, &inc_set, boring_max_cells()),
    )
    .await?;
    Ok(Json(v))
}

/// Default multi-band bundle for `/v1/at` when the caller omits both
/// `band` and `bands`. Picks the cheapest-cold-start, best-coverage
/// bands across the registry so a naked `?lat=&lon=` answers
/// something useful instead of an empty hash.
const DEFAULT_AT_BANDS: &[&str] = &[
    "copdem30m.elevation_mean",
    "esa_worldcover.lc_2021",
    "weather.temperature_2m",
];

/// Overall boring-endpoint wall-clock budget, in seconds, from
/// `EMEM_BORING_TIMEOUT_SECS` (default 25, clamped 5..=120). Single
/// source of truth so every boring handler picks the same value.
/// Lowered 60→25 on 2026-05-31: a 60 s hold per request is what let
/// abandoned cold-materialise requests pile sockets into CLOSE-WAIT and
/// saturate the accept backlog (see the outage note in `build_router`).
/// The cold-cell cap in `boring_recall_aggregated` (EMEM_BORING_COLD_CAP)
/// keeps a request inside this budget by materialising at most a handful
/// of cold cells and returning the rest as an honest `partial` note,
/// rather than racing the deadline.
fn boring_budget_secs() -> u64 {
    std::env::var("EMEM_BORING_TIMEOUT_SECS")
        .ok()
        .and_then(|s| s.parse::<u64>().ok())
        .unwrap_or(25u64)
        .clamp(5, 120)
}

/// Maximum number of *cold* (not-yet-materialised) cells a single boring
/// fan-out will materialise from upstream before it stops and returns the
/// warm cells it already has, plus an honest `cold_cells_skipped` note.
/// Warm cells (cache hits) are never capped — only the slow upstream
/// fetches are. Defaults to 8; tunable via `EMEM_BORING_COLD_CAP`
/// (clamped 1..=512). This is the lever that keeps a boring request inside
/// `boring_budget_secs` so it never holds a connection long enough to leak
/// CLOSE-WAIT sockets. Set high to restore the old unbounded behaviour.
fn boring_cold_cap() -> usize {
    std::env::var("EMEM_BORING_COLD_CAP")
        .ok()
        .and_then(|s| s.parse::<usize>().ok())
        .unwrap_or(8)
        .clamp(1, 512)
}

/// Wrap an async boring-endpoint body in the EMEM_BORING_TIMEOUT_SECS
/// budget so any handler — `boring_named`, `elevation_coherent`,
/// any future per-endpoint specialisation — gets the same wall-clock
/// ceiling. Without this wrapper a polygon fan-out that exceeds the
/// budget can stall indefinitely (regression observed on
/// `/v1/elevation` after the n_cells cap was raised to 512). The
/// `tag` is surfaced verbatim in the 504 message so the caller knows
/// which endpoint timed out.
async fn with_boring_budget<F, T>(tag: &str, fut: F) -> Result<T, ApiError>
where
    F: std::future::Future<Output = Result<T, ApiError>>,
{
    let budget = boring_budget_secs();
    match tokio::time::timeout(std::time::Duration::from_secs(budget), fut).await {
        Ok(inner) => inner,
        Err(_) => Err(ApiError(
            StatusCode::GATEWAY_TIMEOUT,
            ErrorBody {
                code: emem_core::error::ErrorCode::SourceFetchFailed,
                message: format!(
                    "boring-endpoint fan-out over {tag} exceeded {budget}s. \
                     Tune EMEM_BORING_TIMEOUT_SECS, lower n_cells, \
                     or call /v1/recall with a single band to bypass the fan-out."
                ),
                details: None,
            },
        )),
    }
}

/// Build a fixed-bands boring response. Used by every named shorthand
/// (/v1/ndvi, /v1/elevation, …). Single-band endpoints default to a
/// 16-cell polygon fan-out when `place` resolves to an OSM feature
/// with extent; the caller can opt out via `n_cells: 1`.
async fn boring_named(
    s: &AppState,
    q: LatLngQ,
    bands: &[&str],
) -> Result<Json<JsonValue>, ApiError> {
    boring_named_capped(s, q, bands, None).await
}

/// Like [`boring_named`] but with an explicit per-endpoint fan-out cap.
/// `max_cells = None` uses the global boring ceiling (`boring_max_cells`);
/// `Some(n)` clamps tighter (used by the SoilGrids endpoints, whose per-POINT
/// JSON API has no tileable prewarm — see `soil_max_cells`).
async fn boring_named_capped(
    s: &AppState,
    q: LatLngQ,
    bands: &[&str],
    max_cells: Option<usize>,
) -> Result<Json<JsonValue>, ApiError> {
    let inc_set: std::collections::HashSet<&str> = q
        .include
        .as_ref()
        .map(|v| v.iter().map(|s| s.as_str()).collect())
        .unwrap_or_default();
    let target = q.resolve_target(16).await?;
    let bands_owned: Vec<String> = bands.iter().map(|s| (*s).to_string()).collect();
    let tag = format!("bands {bands:?}");
    let cap = max_cells.unwrap_or_else(boring_max_cells);
    let v = with_boring_budget(
        &tag,
        boring_recall_aggregated(s, target, &bands_owned, q.tslot, &inc_set, cap),
    )
    .await?;
    Ok(Json(v))
}

/// `GET /v1/ndvi?lat=&lon=` → indices.ndvi
async fn get_v1_ndvi(
    State(s): State<AppState>,
    Query(q): Query<LatLngQ>,
) -> Result<Json<JsonValue>, ApiError> {
    boring_named(&s, q, &["indices.ndvi"]).await
}

/// `GET /v1/elevation?lat=&lon=` — cross-band coherent elevation.
/// Always recalls Cop-DEM (land) + GMRT (ocean bathymetry) +
/// WorldCover (land-cover veto for the "0 m at sea" case) and reports
/// a `validity` derived from the three. Over open ocean the headline
/// `elevation_m` is null + `bathymetry_m` carries the GMRT depth (signed,
/// negative below sea level); over land the headline carries Cop-DEM.
/// All three sub-facts are exposed under `sub_facts`.
async fn get_v1_elevation(
    State(s): State<AppState>,
    Query(q): Query<LatLngQ>,
) -> Result<Json<JsonValue>, ApiError> {
    let target = q.resolve_target(16).await?;
    // Wrap in the boring-endpoint budget so a wide polygon fan-out
    // (n_cells up to 512 since commit 4) can't run past the wall-clock
    // budget. Without this, elevation_coherent_polygon spawns one
    // JoinSet task per cell with no ceiling, and a long-tail materializer
    // can keep the request live well past the boring 60 s contract.
    let v = with_boring_budget("elevation_coherence", elevation_coherent(&s, target)).await?;
    Ok(Json(v))
}

