    // ── P0 #1 (2026-05-05 deepscan): payload caps tests ─────────────
    //
    // The three regressions these tests pin in place:
    //   (a) `?page_size=` MUST be clamped to PAGINATION_MAX_PAGE_SIZE
    //       so a careless agent can't pull the entire 190 KB algorithm
    //       registry in one shot.
    //   (b) `?summary=true` on `/v1/algorithms` MUST drop the long
    //       `formula` body — that field alone is ~80% of the payload.
    //   (c) `/v1/ask` with `verbose=false` (the new default) MUST omit
    //       per-algorithm `formula` and `temporal_recipe` from the
    //       `algorithms_for_question[]` list while preserving every
    //       receipt-critical field (signed_at, fact_cid, signer,
    //       registry_cid, schema_cid).

    #[test]
    fn page_size_clamps_to_max() {
        // Caller asks for 9999; should be clamped to PAGINATION_MAX_PAGE_SIZE.
        let q = PageQuery {
            page: Some(1),
            page_size: Some(9999),
            summary: None,
        };
        let (page, page_size) = resolve_page_params(&q);
        assert_eq!(page, 1);
        assert_eq!(
            page_size, PAGINATION_MAX_PAGE_SIZE,
            "page_size MUST clamp to {PAGINATION_MAX_PAGE_SIZE} so a careless agent can't pull the full registry"
        );
        // page_size=0 is clamped to 1 (never 0 — would produce
        // div-by-zero in pagination_envelope).
        let q0 = PageQuery {
            page: None,
            page_size: Some(0),
            summary: None,
        };
        let (_p, ps) = resolve_page_params(&q0);
        assert_eq!(ps, 1, "page_size=0 must clamp to 1, not stay 0");
        // Page < 1 floors to 1 — no negative or zero pages.
        let q_neg = PageQuery {
            page: Some(0),
            page_size: None,
            summary: None,
        };
        let (p, ps) = resolve_page_params(&q_neg);
        assert_eq!(p, 1, "page=0 must floor to 1");
        assert_eq!(ps, PAGINATION_DEFAULT_PAGE_SIZE);
    }

    #[test]
    fn pagination_envelope_has_next_math_is_honest() {
        // 47 items, page 1 of size 20: next exists, prev doesn't.
        let env = pagination_envelope(1, 20, 47, "/v1/algorithms", "");
        assert_eq!(env["page"].as_u64(), Some(1));
        assert_eq!(env["page_size"].as_u64(), Some(20));
        assert_eq!(env["total"].as_u64(), Some(47));
        assert_eq!(env["total_pages"].as_u64(), Some(3));
        assert_eq!(env["has_next"].as_bool(), Some(true));
        assert_eq!(env["has_prev"].as_bool(), Some(false));
        assert_eq!(
            env["next_url"].as_str(),
            Some("/v1/algorithms?page=2&page_size=20")
        );
        assert!(env["prev_url"].is_null());
        // Last page: has_next is false, prev_url filled.
        let last = pagination_envelope(3, 20, 47, "/v1/algorithms", "&summary=true");
        assert_eq!(last["has_next"].as_bool(), Some(false));
        assert_eq!(last["has_prev"].as_bool(), Some(true));
        assert!(last["next_url"].is_null());
        assert_eq!(
            last["prev_url"].as_str(),
            Some("/v1/algorithms?page=2&page_size=20&summary=true")
        );
    }

    #[tokio::test]
    async fn algorithms_summary_true_drops_formula_bodies() {
        // Pin the contract: `?summary=true` MUST drop `formula` and
        // `temporal_recipe` per entry. Non-summary mode keeps them.
        let summary_resp = algorithms(axum::extract::Query(PageQuery {
            page: None,
            page_size: Some(100),
            summary: Some(true),
        }))
        .await
        .0;
        let items = summary_resp["items"]
            .as_array()
            .expect("items[] must be present");
        assert!(!items.is_empty(), "registry shouldn't be empty");
        for entry in items {
            assert!(
                entry.get("formula").is_none(),
                "summary=true MUST drop `formula` from {:?}",
                entry["key"]
            );
            assert!(
                entry.get("temporal_recipe").is_none(),
                "summary=true MUST drop `temporal_recipe` from {:?}",
                entry["key"]
            );
            // Headline fields preserved.
            assert!(
                entry.get("key").and_then(|v| v.as_str()).is_some(),
                "summary entry must keep `key`"
            );
            assert!(
                entry.get("kind").is_some(),
                "summary entry must keep `kind`"
            );
            assert!(
                entry.get("inputs").is_some(),
                "summary entry must keep `inputs[]`"
            );
            assert!(
                entry.get("citation").is_some(),
                "summary entry must keep `citation`"
            );
            assert!(
                entry.get("fetch_url").is_some(),
                "summary entry must point at /v1/algorithms/<key>"
            );
        }
        assert_eq!(
            summary_resp["pagination"]["page"].as_u64(),
            Some(1),
            "default page=1"
        );
        // total surfaces the full registry size — agents need this to
        // know they're seeing a slice. Default is page 1 not the full
        // set, so total_pages MUST be ≥ 1.
        let total = summary_resp["pagination"]["total"].as_u64().unwrap();
        assert!(
            total >= items.len() as u64,
            "pagination.total ({total}) MUST be ≥ items length ({}) — slicing must be honest",
            items.len()
        );
        // Compare with non-summary: verbose entries DO carry `formula`.
        let full_resp = algorithms(axum::extract::Query(PageQuery {
            page: None,
            page_size: Some(5),
            summary: None,
        }))
        .await
        .0;
        let full_items = full_resp["items"]
            .as_array()
            .expect("items[] must be present");
        assert!(
            full_items.iter().any(|e| e.get("formula").is_some()),
            "non-summary mode MUST keep `formula` on every entry that has one"
        );
        assert_eq!(
            full_resp["pagination"]["page_size"].as_u64(),
            Some(5),
            "explicit page_size honoured"
        );
    }

    #[test]
    fn ask_req_verbose_defaults_to_false() {
        // The 2026-05-05 deepscan flagged /v1/ask returning 84 KB; the
        // fix is `verbose=false` by default. New callers that omit the
        // field MUST get the trimmed shape, not the legacy verbose one.
        let r: AskReq = serde_json::from_value(serde_json::json!({
            "q": "is this flood-prone", "place": "Ashok Nagar, Ranchi"
        }))
        .unwrap();
        assert!(
            r.verbose.is_none(),
            "AskReq.verbose absent => None (handler unwraps to false)"
        );
        // Explicit verbose=true round-trips.
        let r_v: AskReq = serde_json::from_value(serde_json::json!({
            "q": "x", "place": "y", "verbose": true
        }))
        .unwrap();
        assert_eq!(r_v.verbose, Some(true));
    }

    #[test]
    fn ask_algorithms_for_question_verbose_false_drops_formula_keeps_key() {
        // Direct projection-level test — verbose=false MUST drop
        // `formula` and `temporal_recipe` while preserving the
        // receipt-relevant fields (`key`, `input_bands`, `citation`,
        // `fetch_url`). The signed-receipt fields themselves
        // (`signed_at`, `fact_cid`, signer pubkey, registry/schema CIDs)
        // live in `facts.facts[]` — that path is NEVER touched by the
        // verbose toggle, so once `formula` is gone here we know the
        // payload-cap fix didn't bleed into receipt signing.
        let reg = &*emem_core::algorithms::DEFAULT;
        let alg = reg
            .lookup("flood_risk@2")
            .expect("flood_risk@2 must be in the registry");
        let inputs: Vec<&str> = alg
            .inputs
            .iter()
            .filter_map(|i| i.band.as_deref())
            .collect();
        let trimmed = project_algorithm_for_question(
            "flood_risk_composite",
            alg,
            &inputs,
            /* verbose= */ false,
        );
        assert!(
            trimmed.get("formula").is_none(),
            "verbose=false MUST drop `formula`"
        );
        assert!(
            trimmed.get("temporal_recipe").is_none(),
            "verbose=false MUST drop `temporal_recipe`"
        );
        assert_eq!(trimmed["key"].as_str(), Some("flood_risk@2"));
        assert!(
            trimmed["input_bands"].is_array()
                && !trimmed["input_bands"].as_array().unwrap().is_empty(),
            "verbose=false MUST keep `input_bands[]`"
        );
        assert!(
            trimmed["citation"].is_string(),
            "verbose=false MUST keep `citation`"
        );
        assert_eq!(
            trimmed["fetch_url"].as_str(),
            Some("/v1/algorithms/flood_risk@2")
        );

        // Verbose=true keeps everything.
        let full = project_algorithm_for_question(
            "flood_risk_composite",
            alg,
            &inputs,
            /* verbose= */ true,
        );
        assert!(
            full["formula"].is_string(),
            "verbose=true MUST carry `formula`"
        );
        assert!(
            full.get("temporal_recipe").is_some(),
            "verbose=true MUST carry `temporal_recipe` (flood_risk@2 has one)"
        );
    }

    #[test]
    fn project_materializer_summary_drops_notes() {
        let entry = serde_json::json!({
            "band":              "modis.ndvi_mean",
            "unit":              null,
            "value_kind":        "primary",
            "coverage":          "global",
            "upstream_scheme":   "ornl_modis",
            "upstream_endpoint": "https://example/api",
            "derivation_fn_key": "modis_ornl_subset@1",
            "confidence":        0.9,
            "notes":             "A long editorial paragraph that bloats the response. Ten sentences. Every entry has one. ~62 KB total at 0.0.4.",
        });
        let trimmed = project_materializer_entry(&entry, true);
        assert!(
            trimmed.get("notes").is_none(),
            "summary=true MUST drop the long `notes` field"
        );
        assert_eq!(trimmed["band"].as_str(), Some("modis.ndvi_mean"));
        assert_eq!(trimmed["upstream_scheme"].as_str(), Some("ornl_modis"));
        assert_eq!(trimmed["summary"].as_bool(), Some(true));

        // Non-summary mode passes the entry through unchanged.
        let full = project_materializer_entry(&entry, false);
        assert!(
            full["notes"].is_string(),
            "summary=false MUST preserve `notes`"
        );
    }

    /// `ErrorCode` MUST serialise to snake_case on the wire so agents can
    /// look up the recovery hint in `errors_payload()`. Regression guard
    /// for the bug where `format!("{:?}", code)` was leaking PascalCase
    /// (e.g. `"CidNotFound"`) into per-cell error envelopes — the
    /// catalog publishes `cid_not_found`, so an agent doing
    /// `errors_payload[code]` would never match.
    #[test]
    fn error_code_serialises_snake_case() {
        use emem_core::error::ErrorCode;
        let pairs = [
            (ErrorCode::CidNotFound, "cid_not_found"),
            (ErrorCode::InvalidArgument, "invalid_argument"),
            (ErrorCode::SourceFetchFailed, "source_fetch_failed"),
            (ErrorCode::CacheError, "cache_error"),
            (ErrorCode::Internal, "internal"),
        ];
        for (code, expected) in pairs {
            let v = serde_json::to_value(code).expect("ErrorCode serialises");
            assert_eq!(
                v.as_str(),
                Some(expected),
                "ErrorCode {code:?} must serialise as snake_case `{expected}`"
            );
        }
    }

    /// Default (`verbose=false`) behaviour of the helper that drives
    /// `/v1/recall_polygon`'s metadata enrichment: each fact must
    /// pick up `value_decoded` for categorical bands, but NOT
    /// `band_metadata` (that gets hoisted to a single top-level block
    /// by the recall_polygon handler). Regression guard for the
    /// deepscan finding that band_metadata was duplicating per-fact.
    #[test]
    fn enrich_facts_inner_default_drops_band_metadata_keeps_value_decoded() {
        let mut v = json!({
            "facts": [
                {
                    "band": "esa_worldcover.lc_2021",
                    "value": 50,
                    "tslot": 0,
                },
                {
                    "band": "indices.ndvi",
                    "value": 0.42,
                    "tslot": 0,
                },
            ],
        });
        enrich_facts_inner(&mut v, false);
        let facts = v.get("facts").and_then(|f| f.as_array()).unwrap();
        for f in facts {
            assert!(
                f.get("band_metadata").is_none(),
                "band_metadata must be omitted when with_band_metadata=false: {f}"
            );
        }
        // Categorical bands still get value_decoded.
        let lc = &facts[0];
        assert!(
            lc.get("value_decoded").is_some(),
            "categorical bands keep value_decoded regardless of verbose: {lc}"
        );
    }

    /// `verbose=true` re-enables the per-fact `band_metadata` block —
    /// preserving the wire shape callers had pre-deepscan.
    #[test]
    fn enrich_facts_inner_verbose_emits_band_metadata() {
        let mut v = json!({
            "facts": [
                {"band": "indices.ndvi", "value": 0.42, "tslot": 0},
            ],
        });
        enrich_facts_inner(&mut v, true);
        let f = &v["facts"][0];
        assert!(
            f.get("band_metadata").is_some(),
            "with_band_metadata=true must restore the per-fact block: {f}"
        );
    }

    /// `unique_band_keys_in_facts` is what the polygon handler uses
    /// to hoist a single keyed `band_metadata` map. It must
    /// deduplicate (a 16-fact polygon over 2 bands surfaces only 2
    /// keys) and stay deterministic.
    #[test]
    fn unique_band_keys_dedupe_and_sort() {
        let v = json!({
            "facts": [
                {"band": "indices.ndvi", "value": 0.4},
                {"band": "esa_worldcover.lc_2021", "value": 50},
                {"band": "indices.ndvi", "value": 0.5},
                {"band": "indices.ndvi", "value": 0.6},
            ],
        });
        let keys = unique_band_keys_in_facts(&v);
        // Sorted deterministically (BTreeSet) and deduplicated.
        assert_eq!(
            keys,
            vec!["esa_worldcover.lc_2021".to_string(), "indices.ndvi".into()]
        );
    }

    /// Every code emitted in error-bodies must appear in the catalog
    /// returned by `errors_payload()`. If you add a new ErrorCode variant,
    /// add a corresponding row to `errors_payload` so agents can look up
    /// the meaning + recovery hint for the code they just received.
    #[test]
    fn every_error_code_variant_has_a_catalog_entry() {
        use emem_core::error::ErrorCode;
        let payload = errors_payload();
        let codes: std::collections::HashSet<String> = payload
            .get("codes")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|e| e.get("code").and_then(|c| c.as_str()).map(String::from))
                    .collect()
            })
            .unwrap_or_default();
        let all_variants = [
            ErrorCode::InvalidCell,
            ErrorCode::InvalidResolution,
            ErrorCode::TslotMismatch,
            ErrorCode::BandNotInRegistry,
            ErrorCode::FunctionNotInRegistry,
            ErrorCode::SourceSchemeUnknown,
            ErrorCode::CidNotFound,
            ErrorCode::NoGeocoderMatch,
            ErrorCode::RegistryCidUnknown,
            ErrorCode::SchemaCidUnknown,
            ErrorCode::PrivacyRefused,
            ErrorCode::LevelTooLow,
            ErrorCode::AttesterRevoked,
            ErrorCode::Unauthorized,
            ErrorCode::ClaimUndecidable,
            ErrorCode::BadSignature,
            ErrorCode::BadMerkleProof,
            ErrorCode::CanonicalEncodingDivergence,
            ErrorCode::SourceFetchFailed,
            ErrorCode::SourceFormatMismatch,
            ErrorCode::ComputeTimeout,
            ErrorCode::ComputeQuotaExceeded,
            ErrorCode::RateLimited,
            ErrorCode::CacheError,
            ErrorCode::InvalidArgument,
            ErrorCode::Internal,
        ];
        for v in all_variants {
            let wire = serde_json::to_value(v)
                .ok()
                .and_then(|j| j.as_str().map(String::from))
                .expect("ErrorCode serialises to a string");
            assert!(
                codes.contains(&wire),
                "ErrorCode::{v:?} (`{wire}`) is not documented in errors_payload()"
            );
        }
    }

    /// `topics_payload()` is the single source of truth shared with
    /// `/v1/locate`'s `data_at_this_cell` block. Sanity guard so a
    /// future refactor that drops a key (e.g. removes
    /// `live_bands_by_topic` or `algorithms_for_topic`) breaks the
    /// test, not an agent in production.
    #[test]
    fn topics_payload_carries_required_blocks() {
        let v = topics_payload();
        for required in [
            "live_bands_by_topic",
            "algorithms_for_topic",
            "visual_surfaces",
            "declared_but_no_materializer_at_this_responder",
            "how_to_use",
            "for_temporal_questions",
        ] {
            assert!(
                v.get(required).is_some(),
                "topics_payload() missing required block `{required}`: {v}"
            );
        }
    }

    /// Window-grammar parser for `temporal_diff:<inner>:<window>`.
    /// Days/weeks/months/years; reject zero, negative, garbage,
    /// over-short. These constants are the public contract.
    #[test]
    fn temporal_diff_window_parser_accepts_units() {
        assert_eq!(parse_temporal_diff_window_secs("1d"), Some(86_400));
        assert_eq!(parse_temporal_diff_window_secs("30d"), Some(30 * 86_400));
        assert_eq!(parse_temporal_diff_window_secs("1w"), Some(7 * 86_400));
        assert_eq!(parse_temporal_diff_window_secs("4w"), Some(28 * 86_400));
        assert_eq!(parse_temporal_diff_window_secs("1m"), Some(30 * 86_400));
        assert_eq!(
            parse_temporal_diff_window_secs("1y"),
            Some((365.25_f64 * 86_400.0).round() as i64)
        );
        assert_eq!(
            parse_temporal_diff_window_secs("2y"),
            Some(2 * (365.25_f64 * 86_400.0).round() as i64)
        );
    }

    #[test]
    fn temporal_diff_window_parser_rejects_garbage() {
        for bad in [
            "", "0d", "0y", "y", "d", "30", "30x", "30days", "1.5y", "-1y", "  30d", "30d ", "abc",
        ] {
            assert!(
                parse_temporal_diff_window_secs(bad).is_none(),
                "expected None for `{bad}`, got {:?}",
                parse_temporal_diff_window_secs(bad)
            );
        }
    }

    #[test]
    fn temporal_diff_key_parser_splits_inner_and_window() {
        assert_eq!(
            parse_temporal_diff_key("temporal_diff:indices.ndvi:1y"),
            Some((
                "indices.ndvi".to_string(),
                (365.25_f64 * 86_400.0).round() as i64
            ))
        );
        assert_eq!(
            parse_temporal_diff_key("temporal_diff:weather.temperature_2m:30d"),
            Some(("weather.temperature_2m".to_string(), 30 * 86_400))
        );
        // Nested temporal_diff (delta of a delta) — the parser splits
        // on the LAST colon so the outer wrapper sees an inner band of
        // `temporal_diff:foo:30d` and a window of `1y`. Recursion in
        // the dispatcher then handles the inner.
        assert_eq!(
            parse_temporal_diff_key("temporal_diff:temporal_diff:foo:30d:1y"),
            Some((
                "temporal_diff:foo:30d".to_string(),
                (365.25_f64 * 86_400.0).round() as i64
            ))
        );
    }

    #[test]
    fn temporal_diff_key_parser_rejects_malformed() {
        for bad in [
            "indices.ndvi:1y",                // missing temporal_diff: prefix
            "temporal_diff:indices.ndvi",     // missing window
            "temporal_diff::1y",              // empty inner band
            "temporal_diff:indices.ndvi:",    // empty window
            "temporal_diff:indices.ndvi:99x", // invalid window unit
            "temporal_diff:indices.ndvi:0y",  // zero window
        ] {
            assert!(
                parse_temporal_diff_key(bad).is_none(),
                "expected None for `{bad}`"
            );
        }
    }

    /// MODIS MOD13Q1 is a native 16-day composite; `band_materializer_meta`
    /// MUST surface it as `Composite16Day` so adjacent granules don't
    /// collide into the same Medium (30-day) tslot bucket.
    #[test]
    fn band_tempo_for_key_modis_uses_16day_composite() {
        let m =
            band_materializer_meta("modis.ndvi_mean").expect("modis.ndvi_mean has a materializer");
        assert_eq!(m.tempo, emem_core::tslot::Tempo::Composite16Day);
        assert_eq!(
            tempo_for_band("modis.ndvi_mean"),
            Some(emem_core::tslot::Tempo::Composite16Day)
        );
    }

    /// The 8-day ORNL MODIS products tslot at their native cadence.
    #[test]
    fn band_tempo_for_key_modis_8day_uses_8day_composite() {
        for key in [
            "modis.lst_day_8day",
            "modis.lst_night_8day",
            "modis.et_8day",
            "modis.gpp_8day",
            "modis.lai_8day",
        ] {
            let m = band_materializer_meta(key)
                .unwrap_or_else(|| panic!("{key} should have a materializer"));
            assert_eq!(
                m.tempo,
                emem_core::tslot::Tempo::Composite8Day,
                "{key} should be Composite8Day"
            );
            assert_eq!(
                tempo_for_band(key),
                Some(emem_core::tslot::Tempo::Composite8Day),
                "{key} via tempo_for_band"
            );
        }
    }

    /// `band_materializer_meta` resolves every documented temporal_diff
    /// example by inheriting the inner band's tempo + history bounds.
    /// Guards the parametric prefix arm against silent breakage when
    /// the inner band's meta changes.
    #[test]
    fn temporal_diff_meta_inherits_from_inner_band() {
        let inner =
            band_materializer_meta("indices.ndvi").expect("indices.ndvi has a materializer");
        let wrapped = band_materializer_meta("temporal_diff:indices.ndvi:1y")
            .expect("temporal_diff over indices.ndvi must resolve");
        assert_eq!(wrapped.tempo, inner.tempo);
        assert_eq!(wrapped.history_from_unix, inner.history_from_unix);
        assert_eq!(wrapped.history_to_unix, inner.history_to_unix);
        assert!(
            wrapped.wire_path.contains("temporal_diff"),
            "wire_path should advertise the temporal_diff convention; got `{}`",
            wrapped.wire_path
        );
    }

    /// Polygon mask actually filters out cells outside the boundary.
    /// On an L-shape inside a 1×1 deg bbox, the NE quadrant is
    /// excluded; the bbox-only sample must contain at least one
    /// NE-quadrant cell (proving the mask is necessary), and the
    /// masked sample must contain zero. Length comparison is
    /// intentionally not asserted because both samples can saturate at
    /// the target_n budget — the correctness signal is *which* cells
    /// pass, not how many.
    #[test]
    fn sample_cells_in_polygon_excludes_concave_corner() {
        // L-shape in (lng, lat): exclude NE quadrant of [0,1]×[0,1].
        let coords: Vec<Vec<[f64; 2]>> = vec![vec![
            [0.0, 0.0],
            [1.0, 0.0],
            [1.0, 0.5],
            [0.5, 0.5],
            [0.5, 1.0],
            [0.0, 1.0],
            [0.0, 0.0],
        ]];
        let poly = emem_core::Polygon::from_geojson_coords(&coords).unwrap();
        let polys = vec![poly];

        let bbox = (0.0, 1.0, 0.0, 1.0); // (lat_min, lat_max, lng_min, lng_max)
        let bbox_only = sample_cells_in_bbox(bbox, 64);
        let masked = sample_cells_in_polygon(bbox, 64, &polys);

        let in_ne = |cell: &str| -> bool {
            emem_codec::latlng_from_cell64(cell)
                .map(|info| info.lng_deg > 0.5 && info.lat_deg > 0.5)
                .unwrap_or(false)
        };
        let ne_in_bbox = bbox_only.iter().filter(|c| in_ne(c)).count();
        let ne_in_masked = masked.iter().filter(|c| in_ne(c)).count();
        assert!(
            ne_in_bbox > 0,
            "bbox-only sample should include NE-quadrant cells \
             (got {ne_in_bbox})"
        );
        assert_eq!(
            ne_in_masked, 0,
            "polygon mask let through {ne_in_masked} NE-quadrant cells"
        );
    }

    /// Parsing a Nominatim-shape `Polygon` GeoJSON value yields a
    /// usable `emem_core::Polygon`. Guards the GeoJSON → core::Polygon
    /// path that recall_polygon depends on.
    #[test]
    fn parse_polygon_geojson_polygon() {
        let g = serde_json::json!({
            "type": "Polygon",
            "coordinates": [[
                [0.0, 0.0],
                [1.0, 0.0],
                [1.0, 1.0],
                [0.0, 1.0],
                [0.0, 0.0],
            ]],
        });
        let polys = parse_polygon_geojson(&g).expect("Polygon must parse");
        assert_eq!(polys.len(), 1);
        assert!(polys[0].contains(0.5, 0.5));
        assert!(!polys[0].contains(1.5, 0.5));
    }

    /// `MultiPolygon` parses into one `emem_core::Polygon` per outer
    /// ring. Both polygons must contain their own interior point and
    /// reject the other's.
    #[test]
    fn parse_polygon_geojson_multipolygon() {
        let g = serde_json::json!({
            "type": "MultiPolygon",
            "coordinates": [
                [[
                    [0.0, 0.0],
                    [1.0, 0.0],
                    [1.0, 1.0],
                    [0.0, 1.0],
                    [0.0, 0.0],
                ]],
                [[
                    [10.0, 10.0],
                    [11.0, 10.0],
                    [11.0, 11.0],
                    [10.0, 11.0],
                    [10.0, 10.0],
                ]],
            ],
        });
        let polys = parse_polygon_geojson(&g).expect("MultiPolygon must parse");
        assert_eq!(polys.len(), 2);
        assert!(polys[0].contains(0.5, 0.5));
        assert!(!polys[0].contains(10.5, 10.5));
        assert!(polys[1].contains(10.5, 10.5));
        assert!(!polys[1].contains(0.5, 0.5));
    }

    /// Non-polygon geometries (Point, LineString) MUST return None so
    /// the recall_polygon path falls back to the bbox sample rather
    /// than panic-parsing a wrong shape.
    #[test]
    fn parse_polygon_geojson_rejects_non_polygon() {
        let g = serde_json::json!({"type": "Point", "coordinates": [0.0, 0.0]});
        assert!(parse_polygon_geojson(&g).is_none());
        let g = serde_json::json!({
            "type": "LineString",
            "coordinates": [[0.0, 0.0], [1.0, 1.0]],
        });
        assert!(parse_polygon_geojson(&g).is_none());
    }

    // ── Hallucination guards (audit 2026-05-17) ──────────────────────
    //
    // These tests assert on *behaviour*, not specific coordinates or
    // place names — they keep the disambiguation + conceptual-token
    // refusal logic honest as the manifests evolve. None of them
    // hard-codes "Springfield, IL" or "Sentinel-2 = 10 m"; the truth
    // surface is the live registry + geocoder, content-addressed.

    /// `Sentinel-2 RGB bands` is entirely technical names from the
    /// bands + sources manifests — the conceptual-token guard MUST
    /// refuse to geocode this. Otherwise Photon happily resolves
    /// "Sentinel" to a peak in Czechia.
    #[test]
    fn candidate_is_conceptual_catches_technical_names() {
        for cand in &["NDVI", "Sentinel-2", "Sentinel-2 RGB bands"] {
            let m = candidate_is_conceptual(cand);
            assert!(
                m.is_some(),
                "candidate `{cand}` should be classified conceptual (got {m:?})"
            );
        }
    }

    /// Real places must NEVER be flagged as conceptual — that would
    /// route them to the definitional response and skip the geocoder.
    /// The names below are populated cities in the embedded GeoNames
    /// gazetteer; none of their tokens overlaps a band / source key.
    #[test]
    fn candidate_is_conceptual_lets_places_through() {
        for cand in &[
            "Paris",
            "Cambridge",
            "Saint Petersburg",
            "the Amazon",
            "Mumbai",
            "Manaus",
            "the Moon",
        ] {
            assert!(
                candidate_is_conceptual(cand).is_none(),
                "candidate `{cand}` is a place — guard must not refuse it"
            );
        }
    }

    /// `CONCEPT_TOKENS` is built from the live manifests. We don't
    /// assert specific membership values (those would drift when bands
    /// are renamed), but the set must be non-empty and contain at
    /// least one token longer than 4 chars per band — otherwise the
    /// manifest got truncated and the guard is silently disabled.
    #[test]
    fn concept_tokens_built_from_live_manifests() {
        let n = CONCEPT_TOKENS.len();
        assert!(
            n > 20,
            "concept-token set has only {n} entries — bands/sources manifest likely under-loaded"
        );
        // Anchor tokens that any reasonable bands manifest will carry
        // (these are *families*, not specific places). Drift-safe
        // because they're all proper-noun families that emem ships.
        for required in &["sentinel1", "sentinel2", "geotessera"] {
            assert!(
                CONCEPT_TOKENS.contains(*required),
                "expected concept-token `{required}` derived from bands manifest"
            );
        }
    }

    /// Foundation-embedding bands (`clay_v1`, `prithvi_eo2`, `geotessera*`)
    /// declare `tempo: slow` in the band registry. The materializers must
    /// derive tslot from the scene/vintage time — a hardcoded `tslot: 0`
    /// collides every vintage on the (cell, band, tslot) storage key
    /// (sled_hot.rs:153-160) and the later write overwrites the earlier
    /// vintage. This guard pins the year→tslot math so a future refactor
    /// can't silently regress to constant 0.
    #[test]
    fn slow_tslot_for_tessera_vintages_is_year_aligned() {
        use emem_core::tslot::{Tempo, Tslot};
        assert_eq!(Tslot::from_unix(1_483_228_800, Tempo::Slow).0, 47);
        assert_eq!(Tslot::from_unix(1_704_067_200, Tempo::Slow).0, 54);
        assert_ne!(
            Tslot::from_unix(1_483_228_800, Tempo::Slow).0,
            Tslot::from_unix(1_704_067_200, Tempo::Slow).0,
        );
    }

    /// `days_from_civil` is what each materializer calls to anchor a
    /// vintage year to its Jan-1 Unix second before snapping to a Slow
    /// tslot.
    #[test]
    fn days_from_civil_anchors_tessera_year_to_jan1_unix() {
        assert_eq!(days_from_civil(2024, 1, 1) * 86_400, 1_704_067_200);
        assert_eq!(days_from_civil(2017, 1, 1) * 86_400, 1_483_228_800);
    }

    /// Lock the documented release dates for static products against
    /// silent drift back to `signed_at`.
    #[test]
    fn static_band_release_dates_dont_drift_to_signed_at() {
        assert_eq!(
            static_release_date("copdem30m.elevation_mean"),
            Some("2021-04-30T00:00:00Z")
        );
        assert_eq!(static_release_date("koppen"), Some("2018-10-30T00:00:00Z"));
        assert_eq!(
            static_release_date("esa_worldcover.lc_2021"),
            Some("2022-10-28T00:00:00Z")
        );
        assert_eq!(static_release_date("population"), None);
        assert_eq!(static_release_date("s2.ndvi"), None);
    }

    /// Every algorithm key cited in `algorithms_for_topic` MUST
    /// resolve in the registry. Without this guard a renamed or
    /// removed algorithm would silently break `emem_topics` →
    /// `emem_explain_algorithm` chaining.
    #[test]
    fn topics_payload_algorithm_keys_resolve_in_registry() {
        let v = topics_payload();
        let reg = &*emem_core::algorithms::DEFAULT;
        let topics = v
            .get("algorithms_for_topic")
            .and_then(|t| t.as_object())
            .expect("algorithms_for_topic is an object");
        for (topic, algos) in topics {
            let arr = algos
                .as_array()
                .unwrap_or_else(|| panic!("topic {topic} value is not an array: {algos:?}"));
            for k in arr {
                let key = k.as_str().expect("algorithm key is a string");
                assert!(
                    reg.lookup(key).is_some(),
                    "topic `{topic}` references unknown algorithm `{key}` — \
                     keep emem_topics + emem_algorithms in sync"
                );
            }
        }
    }

