    /// MCP async task handle (spec revision 2025-11-25): spawning a tool as
    /// a background task returns a `CreateTaskResult` immediately with a
    /// `taskId`/`status`; polling the registry eventually yields a
    /// `CallToolResult` byte-EQUAL to the synchronous path for the same
    /// args. We use the fast, deterministic, fully-local `emem_grid_info`
    /// tool as the stand-in for the slow tools so the test is hermetic.
    #[tokio::test]
    async fn async_task_handle() {
        let _g = MCP_TASK_TEST_LOCK.lock().await;
        let s = test_app_state();

        // Synchronous reference result (what tools/call returns today).
        let sync_inner = mcp_tool_call("emem_grid_info", json!({}), &s)
            .await
            .expect("sync grid_info ok");
        let sync_result = mcp_wrap_call_tool_result(sync_inner);

        // Async path: spawn → CreateTaskResult with a running task.
        let create = mcp_spawn_task("emem_grid_info", json!({}), mcp_task_default_ttl_ms(), &s)
            .expect("spawn ok");
        let task = create.get("task").expect("CreateTaskResult has task");
        let task_id = task
            .get("taskId")
            .and_then(|v| v.as_str())
            .expect("taskId present")
            .to_string();
        assert!(task_id.starts_with("emem-task-"));
        let initial_status = task.get("status").and_then(|v| v.as_str()).unwrap();
        assert!(
            initial_status == TASK_STATUS_WORKING || initial_status == TASK_STATUS_COMPLETED,
            "fresh task should be working (or already completed on a fast tool), got {initial_status}"
        );
        // Spec Task object shape.
        assert!(task.get("createdAt").is_some());
        assert!(task.get("lastUpdatedAt").is_some());
        assert!(task.get("pollInterval").is_some());

        // Poll the registry (mirrors what the tasks/get + tasks/result
        // dispatch does) until terminal, with a bounded number of yields.
        let mut polled_result = None;
        for _ in 0..200 {
            {
                let map = mcp_tasks_lock();
                let slot = map.get(&task_id).expect("slot still present");
                if slot.is_terminal() {
                    assert_eq!(slot.status, TASK_STATUS_COMPLETED);
                    polled_result = slot.result.clone();
                    break;
                }
            }
            tokio::task::yield_now().await;
            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        }
        let polled_result = polled_result.expect("task reached terminal state with a result");

        // The async result must equal the synchronous one for the same args.
        assert_eq!(
            polled_result, sync_result,
            "async task result must equal the synchronous tools/call result"
        );

        // tasks/result-style read after completion returns the same payload.
        let after = {
            let map = mcp_tasks_lock();
            map.get(&task_id).unwrap().result.clone().unwrap()
        };
        assert_eq!(after, sync_result);
    }

    /// A spawned task that completes with an error must surface a non-null
    /// `statusMessage` on the slot, so `tasks/get` reports the failure
    /// without the host having to read `tasks/result`.
    #[tokio::test]
    async fn async_task_failure_has_status_message() {
        let _g = MCP_TASK_TEST_LOCK.lock().await;
        let s = test_app_state();

        // Spawning an unknown tool drives the `isError:true` completion path
        // hermetically (no network) — `mcp_tool_call` returns -32602.
        let create = mcp_spawn_task(
            "emem_definitely_not_a_real_tool",
            json!({}),
            mcp_task_default_ttl_ms(),
            &s,
        )
        .expect("spawn ok");
        let task_id = create
            .get("task")
            .and_then(|t| t.get("taskId"))
            .and_then(|v| v.as_str())
            .expect("taskId present")
            .to_string();

        // Poll to terminal.
        let mut status_message = None;
        let mut status = String::new();
        for _ in 0..200 {
            {
                let map = mcp_tasks_lock();
                let slot = map.get(&task_id).expect("slot present");
                if slot.is_terminal() {
                    status = slot.status.clone();
                    status_message = slot.status_message.clone();
                    break;
                }
            }
            tokio::task::yield_now().await;
            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        }

        assert_eq!(status, TASK_STATUS_FAILED, "errored task should be failed");
        let msg = status_message.expect("failed task must carry a non-null statusMessage");
        assert!(!msg.is_empty(), "statusMessage should be a concise error");
        assert!(
            msg.contains("tool error") || msg.contains("unknown tool"),
            "statusMessage should describe the failure, got {msg:?}"
        );

        // The Task object exposed to hosts also carries it (not null).
        let obj = {
            let map = mcp_tasks_lock();
            task_object(&task_id, map.get(&task_id).unwrap())
        };
        assert!(
            obj.get("statusMessage").and_then(|v| v.as_str()).is_some(),
            "tasks/get Task.statusMessage must be non-null on failure"
        );
    }

    /// TTL robustness: the reaper must NEVER evict a non-terminal (working)
    /// slot regardless of how long it has run, and a completed task's result
    /// must remain retrievable within a fresh retention window that starts at
    /// completion time (not at the long-running task's creation time).
    #[tokio::test]
    async fn async_task_ttl_robustness() {
        let _g = MCP_TASK_TEST_LOCK.lock().await;
        let s = test_app_state();

        // 1. A still-working slot is never reaped, even with an already-past
        //    TTL and a reap clock far in the future.
        let working_id = "emem-task-working-never-reaped".to_string();
        {
            let mut map = mcp_tasks_lock();
            map.insert(
                working_id.clone(),
                McpTaskSlot {
                    status: TASK_STATUS_WORKING.to_string(),
                    status_message: None,
                    created_at_iso: iso8601_now_utc(),
                    last_updated_iso: iso8601_now_utc(),
                    last_updated_ms: 0, // ancient
                    ttl_ms: 1,          // already past
                    result: None,
                    abort: None, // is_terminal() keys off abort; force working below
                },
            );
            // A None abort would make is_terminal() true; emulate a live
            // handle by spawning a never-completing task and stashing it.
            let never = tokio::spawn(async {
                tokio::time::sleep(std::time::Duration::from_secs(3600)).await;
            });
            map.get_mut(&working_id).unwrap().abort = Some(never.abort_handle());
        }
        mcp_tasks_reap(u64::MAX); // reap clock far in the future
        {
            let map = mcp_tasks_lock();
            assert!(
                map.contains_key(&working_id),
                "a working (non-terminal) slot must survive the reaper regardless of age"
            );
            // Clean up the live handle so it doesn't leak across the test.
            if let Some(slot) = map.get(&working_id) {
                if let Some(a) = &slot.abort {
                    a.abort();
                }
            }
        }
        {
            let mut map = mcp_tasks_lock();
            map.remove(&working_id);
        }

        // 2. A completed task's result is retrievable, and the completion
        //    fold-back resets the retention clock so the host's TTL window
        //    starts at completion. Spawn a real task, let it finish, and
        //    assert the slot is terminal with a result and a fresh
        //    last_updated_ms (>= the spawn time).
        let before = now_unix_ms();
        let create = mcp_spawn_task("emem_grid_info", json!({}), mcp_task_default_ttl_ms(), &s)
            .expect("spawn ok");
        let task_id = create
            .get("task")
            .and_then(|t| t.get("taskId"))
            .and_then(|v| v.as_str())
            .expect("taskId present")
            .to_string();

        let mut terminal_updated_ms = None;
        for _ in 0..200 {
            {
                let map = mcp_tasks_lock();
                let slot = map.get(&task_id).expect("slot present");
                if slot.is_terminal() {
                    assert_eq!(slot.status, TASK_STATUS_COMPLETED);
                    assert!(
                        slot.result.is_some(),
                        "completed task must retain its terminal result"
                    );
                    terminal_updated_ms = Some(slot.last_updated_ms);
                    break;
                }
            }
            tokio::task::yield_now().await;
            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        }
        let updated = terminal_updated_ms.expect("task reached a terminal, result-bearing state");
        assert!(
            updated >= before,
            "completion must reset the retention clock to completion time \
             (got last_updated_ms={updated} < spawn={before})"
        );
        // A poll within the fresh retention window still returns the result:
        // the reaper at exactly the completion instant must not evict it.
        mcp_tasks_reap(updated);
        {
            let map = mcp_tasks_lock();
            assert!(
                map.get(&task_id).and_then(|sl| sl.result.clone()).is_some(),
                "result must be retrievable within the post-completion TTL window"
            );
        }
        {
            let mut map = mcp_tasks_lock();
            map.remove(&task_id);
        }
    }

    /// Build a registry slot for the capacity tests. `terminal` controls
    /// whether the slot counts as evictable (terminal slots have no abort
    /// handle); `updated_ms` drives the oldest-first eviction tie-break.
    fn mk_task_slot(terminal: bool, updated_ms: u64) -> McpTaskSlot {
        McpTaskSlot {
            status: if terminal {
                TASK_STATUS_COMPLETED.to_string()
            } else {
                TASK_STATUS_WORKING.to_string()
            },
            status_message: None,
            created_at_iso: iso8601_now_utc(),
            last_updated_iso: iso8601_now_utc(),
            last_updated_ms: updated_ms,
            ttl_ms: 60_000,
            result: if terminal { Some(json!({})) } else { None },
            // is_terminal() keys off `abort.is_none()`. A non-terminal slot
            // needs a live abort handle; a terminal one has None.
            abort: if terminal {
                None
            } else {
                let never = tokio::runtime::Handle::current().spawn(std::future::pending::<()>());
                Some(never.abort_handle())
            },
        }
    }

    /// Capacity REJECTION: at `max_tasks` with NO terminal slot to evict, a
    /// new spawn is rejected with the JSON-RPC -32000 capacity error. Drives
    /// the pure `mcp_make_room_locked` policy on a LOCAL map so the
    /// process-global registry and `EMEM_MCP_MAX_TASKS` env are untouched
    /// (no parallel-test races).
    #[tokio::test]
    async fn mcp_task_capacity_rejected_when_full_of_running() {
        let mut map: std::collections::HashMap<String, McpTaskSlot> =
            std::collections::HashMap::new();
        // Fill to capacity (2) with NON-terminal (running) slots.
        map.insert("run-a".into(), mk_task_slot(false, 10));
        map.insert("run-b".into(), mk_task_slot(false, 20));

        let err = mcp_make_room_locked(&mut map, 2)
            .expect_err("at capacity with no terminal slot must be rejected");
        assert_eq!(err.0, -32000, "capacity rejection uses JSON-RPC -32000");
        assert!(
            err.1.contains("at capacity"),
            "error message names the capacity condition: {}",
            err.1
        );
        assert_eq!(map.len(), 2, "rejection must NOT evict a running slot");

        // Abort the live handles so they don't leak past the test.
        for slot in map.values() {
            if let Some(a) = &slot.abort {
                a.abort();
            }
        }
    }

    /// Oldest-finished EVICTION: at capacity but WITH a terminal slot, a new
    /// spawn evicts the OLDEST terminal slot (smallest `last_updated_ms`) and
    /// succeeds, leaving room for the incoming task. A newer terminal slot
    /// and any running slot survive.
    #[tokio::test]
    async fn mcp_task_evicts_oldest_finished_at_capacity() {
        let mut map: std::collections::HashMap<String, McpTaskSlot> =
            std::collections::HashMap::new();
        // Capacity 3: one running, one OLD terminal, one NEW terminal.
        map.insert("running".into(), mk_task_slot(false, 5));
        map.insert("old-done".into(), mk_task_slot(true, 10));
        map.insert("new-done".into(), mk_task_slot(true, 99));

        mcp_make_room_locked(&mut map, 3).expect("eviction makes room → Ok");

        assert_eq!(map.len(), 2, "exactly one slot evicted to make room");
        assert!(
            !map.contains_key("old-done"),
            "the OLDEST terminal slot is the eviction victim"
        );
        assert!(
            map.contains_key("new-done"),
            "the newer terminal slot survives"
        );
        assert!(
            map.contains_key("running"),
            "a running (non-terminal) slot is never evicted"
        );

        // Abort the live handle on the surviving running slot.
        if let Some(a) = map.get("running").and_then(|sl| sl.abort.as_ref()) {
            a.abort();
        }
    }

    /// A `task`-param `tools/call` against a tool whose taskSupport is
    /// `forbidden` (the spec default for everything except the slow tools)
    /// must be rejected — async mode is never silently downgraded to sync.
    #[test]
    fn async_task_forbidden_for_non_task_tools() {
        // grid_info is fast/local — explicitly NOT in the async allow-list.
        assert_eq!(emem_mcp::tool_task_support("emem_grid_info"), "forbidden");
        // The documented slow tools opt in.
        assert_eq!(emem_mcp::tool_task_support("emem_eudr_dds"), "optional");
        assert_eq!(emem_mcp::tool_task_support("emem_hunt"), "optional");
    }

    /// initialize advertises ONLY capabilities emem actually implements at
    /// the advertised protocolVersion. The advertised version must be one
    /// of the real supported MCP revisions, and the `tasks` capability — if
    /// present — must correspond to the implemented tasks/* dispatch and
    /// only appear at the 2025-11-25 revision that defines it. Sampling and
    /// elicitation are client capabilities with no server-side path here,
    /// so they MUST NOT be advertised.
    #[tokio::test]
    async fn initialize_capabilities_honest() {
        use axum::body::to_bytes;
        use axum::response::IntoResponse;

        // Real, published MCP protocol revisions (schema dirs on the spec
        // repo). 2025-11-25 is the latest and the one that defines tasks.
        const REAL_SUPPORTED: &[&str] = &["2024-11-05", "2025-03-26", "2025-06-18", "2025-11-25"];

        async fn do_initialize(s: &AppState, requested: Option<&str>) -> JsonValue {
            let params = match requested {
                Some(v) => json!({ "protocolVersion": v }),
                None => json!({}),
            };
            let body = serde_json::to_vec(&json!({
                "jsonrpc": "2.0", "id": 1, "method": "initialize", "params": params,
            }))
            .unwrap();
            let resp = mcp_jsonrpc(
                State(s.clone()),
                axum::http::HeaderMap::new(),
                axum::body::Bytes::from(body),
            )
            .await
            .into_response();
            let bytes = to_bytes(resp.into_body(), usize::MAX).await.unwrap();
            serde_json::from_slice(&bytes).unwrap()
        }

        let s = test_app_state();

        // Default initialize (no requested version) → latest real revision.
        let v = do_initialize(&s, None).await;
        let result = v.get("result").expect("initialize returns a result");
        let proto = result
            .get("protocolVersion")
            .and_then(|p| p.as_str())
            .expect("protocolVersion present");
        assert!(
            REAL_SUPPORTED.contains(&proto),
            "advertised protocolVersion `{proto}` must be a real published revision"
        );
        assert_eq!(
            proto, "2025-11-25",
            "default must negotiate the latest real revision"
        );

        let caps = result.get("capabilities").expect("capabilities present");
        // Implemented capabilities.
        assert!(caps.get("tools").is_some(), "tools is implemented");
        assert!(caps.get("resources").is_some(), "resources is implemented");
        assert!(caps.get("prompts").is_some(), "prompts is implemented");
        // tasks present at 2025-11-25 and matches the implemented dispatch
        // (tasks/list, tasks/cancel, task-augmented tools/call).
        let tasks = caps.get("tasks").expect("tasks advertised at 2025-11-25");
        assert!(tasks.get("list").is_some());
        assert!(tasks.get("cancel").is_some());
        assert!(tasks
            .get("requests")
            .and_then(|r| r.get("tools"))
            .and_then(|t| t.get("call"))
            .is_some());
        // Honesty: no sampling / elicitation path implemented → not claimed.
        assert!(
            caps.get("sampling").is_none(),
            "emem implements no server-initiated sampling path; must not advertise it"
        );
        assert!(
            caps.get("elicitation").is_none(),
            "emem implements no elicitation path; must not advertise it"
        );

        // An older negotiated revision must NOT advertise the tasks
        // capability (it isn't defined before 2025-11-25), even though the
        // tasks/* methods remain reachable for clients that try them.
        let v_old = do_initialize(&s, Some("2025-06-18")).await;
        let caps_old = v_old.get("result").unwrap().get("capabilities").unwrap();
        assert_eq!(
            v_old.get("result").unwrap().get("protocolVersion").unwrap(),
            "2025-06-18"
        );
        assert!(
            caps_old.get("tasks").is_none(),
            "tasks capability is 2025-11-25-only and must not appear at 2025-06-18"
        );
    }

    /// `soil_max_cells()` defaults to a tight 64-cell cap, reads the env
    /// override at runtime (NOT cached), and never exceeds the global boring
    /// ceiling. This is what bounds a place-name /v1/soil fan-out so it can't
    /// serialise into hundreds of per-point SoilGrids calls.
    #[test]
    fn soil_max_cells_caps_fanout() {
        let _g = eudr_test_env_guard();
        let prev_soil = std::env::var("EMEM_SOIL_MAX_CELLS").ok();
        let prev_boring = std::env::var("EMEM_BORING_MAX_CELLS").ok();

        std::env::remove_var("EMEM_SOIL_MAX_CELLS");
        std::env::remove_var("EMEM_BORING_MAX_CELLS");
        assert_eq!(soil_max_cells(), 64, "default soil cap is 64");
        assert!(
            soil_max_cells() <= boring_max_cells(),
            "soil cap never exceeds the global boring ceiling"
        );

        // Runtime-readable override (proves no LazyLock caching).
        std::env::set_var("EMEM_SOIL_MAX_CELLS", "16");
        assert_eq!(soil_max_cells(), 16, "env override is read at runtime");

        // Clamped to the global ceiling: a soil cap above the boring max is
        // pulled back down to it.
        std::env::set_var("EMEM_BORING_MAX_CELLS", "32");
        std::env::set_var("EMEM_SOIL_MAX_CELLS", "1000");
        assert_eq!(
            soil_max_cells(),
            32,
            "soil cap is clamped down to the global boring ceiling"
        );

        // Restore.
        match prev_soil {
            Some(v) => std::env::set_var("EMEM_SOIL_MAX_CELLS", v),
            None => std::env::remove_var("EMEM_SOIL_MAX_CELLS"),
        }
        match prev_boring {
            Some(v) => std::env::set_var("EMEM_BORING_MAX_CELLS", v),
            None => std::env::remove_var("EMEM_BORING_MAX_CELLS"),
        }
    }

